INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('grover-law-firm-calgary','Grover Law Firm','Calgary','AB','ab-calgary',0,5,769,50.9936982,-114.0702399,'{"name":"Grover Law Firm","city":"Calgary","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"ab-calgary","province":"AB","lat":50.9936982,"lng":-114.0702399,"address":"Sovereign Centre, 6700 Macleod Trl SE Ste 390, Calgary, AB T2H 0L3","phone":"+14032531029","rating":5,"count":769,"slug":"grover-law-firm-calgary","mapsUrl":"https://www.google.com/maps/search/Grover+Law+Firm+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=Sovereign+Centre%2C+6700+Macleod+Trl+SE+Ste+390%2C+Calgary%2C+AB+T2H+0L3","website":"https://www.groverlawfirm.com","blurb":"Personal Injury / Civil Litigation in Calgary. Rated 5.0 from 769 Google reviews.","type":"logo","src":"images/logos/grover-law-firm-calgary.webp"}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Grover Law Firm is a Calgary personal injury practice handling vehicle, motorcycle and trucking collisions, slip and falls and dog bites.

