INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('parr-business-law-vancouver','Parr Business Law','Vancouver','BC','bc-vancouver',0,4.9,205,49.2643703,-123.1156041,'{"name":"Parr Business Law","city":"Vancouver","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"bc-vancouver","province":"BC","lat":49.2643703,"lng":-123.1156041,"address":"525 W 8th Ave #800, Vancouver, BC V5Z 1C6","phone":"+16042838622","rating":4.9,"count":205,"slug":"parr-business-law-vancouver","mapsUrl":"https://www.google.com/maps/search/Parr+Business+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=525+W+8th+Ave+%23800%2C+Vancouver%2C+BC+V5Z+1C6","website":"https://www.parrbusinesslaw.com","blurb":"Business Law in Vancouver. Rated 4.9 from 205 Google reviews.","type":"logo","src":"images/logos/parr-business-law-vancouver.webp"}',NULL,'Parr Business Law is a Vancouver firm handling incorporations, contracts, business sales and purchases, wills and estate planning.

