INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('a-dhillon-law-brampton','A. Dhillon Law','Brampton','ON','peel-halton',0,5,199,43.7578005,-79.6923212,'{"name":"A. Dhillon Law","city":"Brampton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.7578005,"lng":-79.6923212,"address":"9300 Goreway Dr Unit#218, Brampton, ON L6P 4N1","phone":"+16479633612","rating":5,"count":199,"slug":"a-dhillon-law-brampton","mapsUrl":"https://www.google.com/maps/search/A.+Dhillon+Law+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9300+Goreway+Dr+Unit%23218%2C+Brampton%2C+ON+L6P+4N1","website":"https://adhillonlaw.com","blurb":"Criminal Defence in Brampton. Rated 5.0 from 199 Google reviews.","type":"logo","src":"images/logos/a-dhillon-law-brampton.webp"}',NULL,'A Dhillon Law is a Brampton criminal defence firm serving clients in Toronto, Mississauga and across Southern Ontario.

The firm is led by Akash Dhillon, who holds an Hons B.A. and J.D. Its site refers to charges such as sexual assault and impaired driving, and its blog covers identity fraud in Milton, disobeying a court order in Orangeville and youth charges in Ontario. It notes that a criminal charge can affect freedom, immigration status, career and travel, and says each case gets a defence strategy based on the evidence. Flexible payment plans are listed.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('shaffie-law-toronto','Shaffie Law','Toronto','ON','toronto',0,4.9,203,43.6484203,-79.373554,'{"name":"Shaffie Law","city":"Toronto","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"toronto","province":"ON","lat":43.6484203,"lng":-79.373554,"address":"65 Front St E Ste 300, Toronto, ON M5E 1B5","phone":"+16475005186","rating":4.9,"count":203,"slug":"shaffie-law-toronto","mapsUrl":"https://www.google.com/maps/search/Shaffie+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=65+Front+St+E+Ste+300%2C+Toronto%2C+ON+M5E+1B5","website":"https://www.shaffielaw.ca","blurb":"Criminal Defence / Civil Litigation in Toronto. Rated 4.9 from 203 Google reviews.","type":"logo","src":"images/logos/shaffie-law-toronto.png"}',NULL,'Shaffie Law is a Toronto criminal defence firm that focuses on domestic assault and sexual assault charges across Ontario.

Shayan Shaffie is a former Crown Attorney who began at the Crown Attorney''s Office in Hamilton and worked as a trial Crown for several years before entering private practice. He holds a law degree from the University of Toronto. The firm says it has spent over a decade on domestic violence charges, and its pages explain topics such as orders barring communication, what to expect at a first court appearance, the role of victims and the use of affidavits.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('batth-law-office-brampton','Batth Law Office','Brampton','ON','peel-halton',0,4.9,201,43.6620636,-79.7208755,'{"name":"Batth Law Office","city":"Brampton","featured":false,"tags":[],"caseTypes":[],"region":"peel-halton","province":"ON","lat":43.6620636,"lng":-79.7208755,"address":"195 County Ct Blvd #204, Brampton, ON L6W 4P7","phone":"+19059656562","rating":4.9,"count":201,"slug":"batth-law-office-brampton","mapsUrl":"https://www.google.com/maps/search/Batth+Law+Office+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=195+County+Ct+Blvd+%23204%2C+Brampton%2C+ON+L6W+4P7","website":"https://www.batthlaw.com","blurb":"Law firm in Brampton. Rated 4.9 from 201 Google reviews.","type":"logo","src":"images/logos/batth-law-office-brampton.png"}',NULL,'Batth Law Office is a Brampton firm handling immigration, family law, wills and estates, criminal defence, real estate and notary services.

As Batth Law Professional Corporation, it serves Brampton, Mississauga, Oakville, Toronto and the Greater Toronto Area and works in English, Punjabi, Hindi and Urdu. Immigration work includes work permits, spousal and family sponsorship, study permits, Express Entry, Visitor and Super Visa applications, and appeals. Notary services cover certified true copies, statutory declarations, affidavits and travel consent letters for minors.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('michael-juskey-toronto','Michael Juskey','Toronto','ON','toronto',0,4.9,200,43.6475556,-79.3962148,'{"name":"Michael Juskey","city":"Toronto","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"toronto","province":"ON","lat":43.6475556,"lng":-79.3962148,"address":"130 Spadina Ave. #606, Toronto, ON M5V 2L4","phone":"+14164282760","rating":4.9,"count":200,"slug":"michael-juskey-toronto","mapsUrl":"https://www.google.com/maps/search/Michael+Juskey+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=130+Spadina+Ave.+%23606%2C+Toronto%2C+ON+M5V+2L4","website":"https://mpjlaw.ca","blurb":"Criminal Defence / Civil Litigation in Toronto. Rated 4.9 from 200 Google reviews.","type":"logo","src":"images/logos/michael-juskey-toronto.png"}',NULL,'Michael Juskey is a Toronto criminal defence lawyer representing clients charged with assault, theft, fraud, young offender and driving offences.

The practice acts in Toronto, Newmarket, Brampton and throughout Southern Ontario, appearing in the Ontario Court of Justice and the Superior Court of Justice. Born and raised in Toronto, Michael studied political science at the University of Western Ontario and earned his LL.B. at the University of Leicester with first class honours. He interned with a community Legal Aid clinic and continues to provide legal aid services. The firm lists domestic assault, sexual assault, mischief and weapons offences among its focus areas.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bhardwaj-co-family-law-edmonton','Bhardwaj+Co Family Law','Edmonton','AB','ab-edmonton',0,4.7,208,53.54055,-113.5025538,'{"name":"Bhardwaj+Co Family Law","city":"Edmonton","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"ab-edmonton","province":"AB","lat":53.54055,"lng":-113.5025538,"address":"10055 106 St #1250, Edmonton, AB T5J 2Y2","phone":"+17802222386","rating":4.7,"count":208,"slug":"bhardwaj-co-family-law-edmonton","mapsUrl":"https://www.google.com/maps/search/Bhardwaj%2BCo+Family+Law+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10055+106+St+%231250%2C+Edmonton%2C+AB+T5J+2Y2","website":"https://bhardwajco.ca","blurb":"Family Law in Edmonton. Rated 4.7 from 208 Google reviews.","type":"logo","src":"images/logos/bhardwaj-co-family-law-edmonton.png"}',NULL,'Bhardwaj+Co is an Edmonton firm, with a second office in Leduc, handling family law, real estate, wills and estates, and employment matters.

