INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('miller-boileau-family-law-group-edmonton','Miller Boileau Family Law Group','Edmonton','AB','ab-edmonton',0,4.7,103,53.556588,-113.5408809,'{"name":"Miller Boileau Family Law Group","city":"Edmonton","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"ab-edmonton","province":"AB","lat":53.556588,"lng":-113.5408809,"address":"10981 127 St, Edmonton, AB T5M 0T1","phone":"+17804822888","rating":4.7,"count":103,"slug":"miller-boileau-family-law-group-edmonton","mapsUrl":"https://www.google.com/maps/search/Miller+Boileau+Family+Law+Group+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10981+127+St%2C+Edmonton%2C+AB+T5M+0T1","website":"https://www.millerboileau.com","blurb":"Family Law in Edmonton. Rated 4.7 from 103 Google reviews.","type":"logo","src":"images/logos/miller-boileau-family-law-group-edmonton.png"}',NULL,'Miller Boileau Family Law Group is an Edmonton firm that handles divorce, separation, property division, parenting, child support and spousal support.

The firm says family law is the only area it practises. Its practice pages also cover common law and adult interdependent partners, along with prenuptial and cohabitation agreements. On the process side, it lists negotiation, mediation, collaboration, arbitration and litigation as options, and explains that in mediation a neutral third party helps the parties reach their own agreement. The site says its lawyers have decades of experience and describes matching each client with the level of legal service the situation needs.','dynamic','live',NULL);
