INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sg-injury-law-ottawa','SG Injury Law','Ottawa','ON','eastern',0,4.8,92,45.3771635,-75.7055705,'{"name":"SG Injury Law","city":"Ottawa","featured":false,"tags":["Personal Injury","Employment Law"],"caseTypes":["injury","employment"],"region":"eastern","province":"ON","lat":45.3771635,"lng":-75.7055705,"address":"1101 Prince of Wales Dr #295, Ottawa, ON K2C 3W7","phone":"+16135182416","rating":4.8,"count":92,"slug":"sg-injury-law-ottawa","mapsUrl":"https://www.google.com/maps/search/SG+Injury+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1101+Prince+of+Wales+Dr+%23295%2C+Ottawa%2C+ON+K2C+3W7","website":"https://www.sginjurylaw.ca","blurb":"Personal Injury / Employment Law in Ottawa. Rated 4.8 from 92 Google reviews.","type":"logo","src":"images/logos/sg-injury-law-ottawa.jpg"}','{"1":[["08:30","18:30"]],"2":[["08:30","18:30"]],"3":[["08:30","18:30"]],"4":[["08:30","18:30"]],"5":[["08:30","18:30"]]}','SG Injury Law is an Ottawa firm whose only practice areas are personal injury, long-term disability insurance and employment law.

The lawyers describe themselves as former insurance defence lawyers. Their injury work covers car accidents, including no-fault accident benefits, and slip and fall cases, while the employment group handles wrongful dismissal, employment contracts, severance pay and termination package assessment. The firm says it acts in Ottawa and in Eastern Ontario communities such as Pembroke, Cornwall, Kingston, Brockville, Perth and Arnprior. Its site also walks through the steps of an injury case, from a notice letter and examinations for discovery to mediation, pre-trial conference and trial.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('robb-macdonald-toronto','Robb MacDonald','Toronto','ON','toronto',0,4.9,87,43.6483555,-79.3959124,'{"name":"Robb MacDonald","city":"Toronto","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"toronto","province":"ON","lat":43.6483555,"lng":-79.3959124,"address":"130 Spadina Ave. #606, Toronto, ON M5V 2L4","phone":"+14163151505","rating":4.9,"count":87,"slug":"robb-macdonald-toronto","mapsUrl":"https://www.google.com/maps/search/Robb+MacDonald+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=130+Spadina+Ave.+%23606%2C+Toronto%2C+ON+M5V+2L4","website":"https://www.lawintoronto.com","blurb":"Criminal Defence in Toronto. Rated 4.9 from 87 Google reviews.","type":"logo","src":"images/logos/robb-macdonald-toronto.webp"}',NULL,'Robb MacDonald is a Toronto criminal defence lawyer whose practice centres on jury trials for serious charges, from assault and impaired driving to murder.

The site says he was called to the Ontario bar in 2007, holds a J.D. from Queen''s University and trained under Edward Greenspan, and describes two decades of defence work. Charges listed include assault and violent offences, conspiracy and organized crime, over 80, drug offences, fraud and economic crimes, sexual offences, and murder and manslaughter. It also cites the case R. v. Hoang and says other lawyers refer files to him. Its assault page covers what the Crown must prove across the Greater Toronto Area.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dietrich-law-office-kitchener','Dietrich Law Office','Kitchener','ON','waterloo-guelph',0,4.7,90,43.4488203,-80.4838247,'{"name":"Dietrich Law Office","city":"Kitchener","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"waterloo-guelph","province":"ON","lat":43.4488203,"lng":-80.4838247,"address":"141 Duke St E, Kitchener, ON N2H 1A6","phone":"+15197490770","rating":4.7,"count":90,"slug":"dietrich-law-office-kitchener","mapsUrl":"https://www.google.com/maps/search/Dietrich+Law+Office+Kitchener+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=141+Duke+St+E%2C+Kitchener%2C+ON+N2H+1A6","website":"https://www.dietrichlaw.ca","blurb":"Personal Injury in Kitchener. Rated 4.7 from 90 Google reviews.","type":"logo","src":"images/logos/dietrich-law-office-kitchener.png"}',NULL,'Dietrich Law Office is a Kitchener firm that represents injured people and those seeking disability benefits in Waterloo Region and nearby areas.

Its site says the lawyers serve Kitchener, Waterloo, Cambridge, the GTA, Brant and Oxford. The personal injury lawyers follow changes to motor vehicle accident legislation and the law of negligence, and the disability lawyers work with orthopaedic, psychological, chronic pain and fibromyalgia diagnoses. The firm says it pays attention to treatment and medication needs and to income replacement, and it states that its practice is limited to personal injury and disability law.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pollack-tsimerman-llp-north-york','Pollack Tsimerman LLP','North York','ON','toronto',0,5,408,43.7711721,-79.3226303,'{"name":"Pollack Tsimerman LLP","city":"North York","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"toronto","province":"ON","lat":43.7711721,"lng":-79.3226303,"address":"2450 Victoria Park Ave, North York, ON M2J 4A2","phone":"+14164910111","rating":5,"count":408,"slug":"pollack-tsimerman-llp-north-york","mapsUrl":"https://www.google.com/maps/search/Pollack+Tsimerman+LLP+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2450+Victoria+Park+Ave%2C+North+York%2C+ON+M2J+4A2","website":"https://ptlawyers.ca","blurb":"Personal Injury / Civil Litigation in North York. Rated 5.0 from 408 Google reviews.","type":"logo","src":"images/logos/pollack-tsimerman-llp-north-york.png"}',NULL,'Pollack Tsimerman LLP is a North York personal injury firm whose lawyers have worked on both the plaintiff and insurance sides of injury litigation.

The firm''s site names Philip Pollack, Ziv Tsimerman, Lianne Sharvit, Michelle Farb, Julie Koritar, Laura Barbosa, Luca Drago and Ayla Koritar. Philip Pollack, a graduate of Western University and Osgoode Hall Law School, formerly practised civil litigation at a large Toronto firm acting for national and international insurers. His injury work centres on motor vehicle and snowmobile accidents, slip and falls, long-term disability, product liability and sport and recreational litigation, and he appears before the Ontario Superior Court of Justice. The firm says it is prepared to take cases to trial.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('stepup-immigration-inc-edmonton','StepUp Immigration Inc.','Edmonton','AB','ab-edmonton',0,5,402,53.4169202,-113.4791498,'{"name":"StepUp Immigration Inc.","city":"Edmonton","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"ab-edmonton","province":"AB","lat":53.4169202,"lng":-113.4791498,"address":"1803 91 St SW Unit 205, Edmonton, AB T6X 0W8","phone":"+17808858115","rating":5,"count":402,"slug":"stepup-immigration-inc-edmonton","mapsUrl":"https://www.google.com/maps/search/StepUp+Immigration+Inc.+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1803+91+St+SW+Unit+205%2C+Edmonton%2C+AB+T6X+0W8","website":"https://www.stepupimmigration.com","blurb":"Immigration in Edmonton. Rated 5.0 from 402 Google reviews.","type":"logo","src":"images/logos/stepup-immigration-inc-edmonton.png"}',NULL,'StepUp Immigration is an Edmonton firm of Registered Canadian Immigration Consultants assisting with visas, work permits and permanent residence.

According to its website, the firm has served clients for over a decade and supports people who want to study, work or settle in Canada, from visa applications to permanent residency applications. It also offers post-landing guidance on banking, transport and renting or buying a home, along with application tracking. Its news section covers topics such as new language test rules for permanent residence applications and open work permit changes for high-skilled workers as of January 2025.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('amer-ali-law-ottawa','Amer Ali Law','Ottawa','ON','eastern',0,5,388,45.4915491,-75.4821114,'{"name":"Amer Ali Law","city":"Ottawa","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"eastern","province":"ON","lat":45.4915491,"lng":-75.4821114,"address":"890 Taylor Creek Dr, Orléans, ON K4A 0Z9","phone":"+13436335997","rating":5,"count":388,"slug":"amer-ali-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Amer+Ali+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=890+Taylor+Creek+Dr%2C+Orl%C3%A9ans%2C+ON+K4A+0Z9","website":"https://www.ameralilaw.com","blurb":"Real Estate in Ottawa. Rated 5.0 from 388 Google reviews.","type":"logo","src":"images/logos/amer-ali-law-ottawa.png"}',NULL,'Amer Ali Law is a virtual Ontario firm, with Ottawa, Orleans and Toronto listed, that handles real estate closings, incorporations and wills.

The firm describes its model as technology paired with personal service, with documents signed electronically and remotely, or in person when arranged in advance. Its real estate page lists buying and selling, title transfers and survivorship applications, mortgage transactions, mortgage refinancing and debt consolidation, and reviewing the agreement of purchase and sale. It says it acts for homeowners, realtors, lenders and mortgage professionals on residential and commercial properties, and that it has completed thousands of real estate deals.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('isenberg-and-shuman-north-york','Isenberg & Shuman','North York','ON','toronto',0,4.9,490,43.7678675,-79.4120987,'{"name":"Isenberg & Shuman","city":"North York","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.7678675,"lng":-79.4120987,"address":"5075 Yonge St Ste 804, North York, ON M2N 6Z4","phone":"+14162255136","rating":4.9,"count":490,"slug":"isenberg-and-shuman-north-york","mapsUrl":"https://www.google.com/maps/search/Isenberg+%26+Shuman+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5075+Yonge+St+Ste+804%2C+North+York%2C+ON+M2N+6Z4","website":"https://www.shumanlaw.ca","blurb":"Real Estate in North York. Rated 4.9 from 490 Google reviews.","type":"logo","src":"images/logos/isenberg-and-shuman-north-york.png"}',NULL,'Isenberg & Shuman is a boutique firm in North York, Toronto, handling real estate, wills and powers of attorney, estate administration and business law.

The firm says it helps hundreds of clients each year and offers remote video conference signings whenever needed. Its wills page explains why a valid will and power of attorney matter, noting that a power of attorney lets a person appoint someone to manage personal and financial affairs in the event of incapacity. The practice areas listed are real estate law, wills and powers of attorney, estate administration and business law, and the site publishes articles on these topics.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('chaudhary-law-office-north-york','Chaudhary Law Office','North York','ON','toronto',0,4.9,308,43.7238665,-79.3373244,'{"name":"Chaudhary Law Office","city":"North York","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.7238665,"lng":-79.3373244,"address":"18 Wynford Dr Ste 709, North York, ON M3C 3S2","phone":"+14164476118","rating":4.9,"count":308,"slug":"chaudhary-law-office-north-york","mapsUrl":"https://www.google.com/maps/search/Chaudhary+Law+Office+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=18+Wynford+Dr+Ste+709%2C+North+York%2C+ON+M3C+3S2","website":"https://chaudharylaw.com","blurb":"Immigration in North York. Rated 4.9 from 308 Google reviews.","type":"logo","src":"images/logos/chaudhary-law-office-north-york.png"}','{"1":[["09:30","17:30"]],"2":[["09:30","17:00"]],"3":[["09:30","17:00"]],"4":[["09:30","17:00"]],"5":[["09:30","17:00"]]}','Chaudhary Law Office is a North York firm practising immigration, citizenship and refugee law, including appeals and inadmissibility matters.

Its services include temporary residence, permanent residence, family sponsorship, Express Entry, provincial nominee programs, business immigration, citizenship, refugee protection, inadmissibility, appeals, name changes in Ontario and notary services. The firm says it deals with decision makers at Immigration, Refugee and Citizenship Canada, the Canada Border Services Agency and the Federal Court. The site says legal services are available in English, French, Mandarin, Farsi and Spanish. Max Chaudhary is identified as owner, and Loughlin Adams-Murphy and Maxwell Musgrove appear on the team page.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lecker-and-associates-north-york','Lecker & Associates','North York','ON','toronto',0,4.9,704,43.7611521,-79.4103034,'{"name":"Lecker & Associates","city":"North York","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.7611521,"lng":-79.4103034,"address":"4789 Yonge St #514, North York, ON M2N 0G3","phone":"+16478731961","rating":4.9,"count":704,"slug":"lecker-and-associates-north-york","mapsUrl":"https://www.google.com/maps/search/Lecker+%26+Associates+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4789+Yonge+St+%23514%2C+North+York%2C+ON+M2N+0G3","website":"https://www.leckerslaw.com","blurb":"Employment Law in North York. Rated 4.9 from 704 Google reviews.","type":"logo","src":"images/logos/lecker-and-associates-north-york.jpg"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Lecker & Associates is a North York employment law firm acting only for employees in wrongful and constructive dismissal and severance matters.

Its structured data gives 1984 as the founding date and says the firm has worked for Ontario employees for over 40 years, with more than 10,000 clients. The site also lists discrimination, harassment, denied disability benefits and forced resignation from toxic workplaces among its subjects. The firm says its lawyers have litigated precedent-setting cases, and its service area names Toronto and North York. Pages are addressed to Ontario workers.','dynamic','live',NULL);
