INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('macisaac-gow-llp-oakville','MacIsaac Gow LLP','Oakville','ON','peel-halton',0,4.9,296,43.4924514,-79.6747164,'{"name":"MacIsaac Gow LLP","city":"Oakville","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"peel-halton","province":"ON","lat":43.4924514,"lng":-79.6747164,"address":"1660 North Service Rd E Ste 102, Oakville, ON L6H 7G3","phone":"+13657774529","rating":4.9,"count":296,"slug":"macisaac-gow-llp-oakville","mapsUrl":"https://www.google.com/maps/search/MacIsaac+Gow+LLP+Oakville+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1660+North+Service+Rd+E+Ste+102%2C+Oakville%2C+ON+L6H+7G3","website":"https://www.mglawyers.ca","blurb":"Personal Injury in Oakville. Rated 4.9 from 296 Google reviews.","type":"logo","src":"images/logos/macisaac-gow-llp-oakville.webp"}','{"1":[["08:30","17:00"]],"2":[["08:30","17:00"]],"3":[["08:30","17:00"]],"4":[["08:30","17:00"]],"5":[["08:30","17:00"]]}','MacIsaac Gow LLP is an Oakville personal injury firm handling motor vehicle accidents, slip and fall injuries, bicycle accidents and dog bite injuries.

The firm''s site describes its lawyers as having more than 35 combined years of litigation experience, much of it working for insurance companies before acting for injured people. It says they have conducted trials before juries and judges across Ontario and argued matters at the highest level of court in the province. Partners Matthew C. MacIsaac and Fraser R. Gow are named, along with associates Alex Robart, Mark McDonald and Maximilian Jagoda, and its pages are written for clients in Mississauga and the surrounding area.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('korman-and-company-toronto','Korman & Company','Toronto','ON','toronto',0,4.8,317,43.6589058,-79.3492541,'{"name":"Korman & Company","city":"Toronto","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.6589058,"lng":-79.3492541,"address":"721 Queen St E, Toronto, ON M4M 1H1","phone":"+14164654232","rating":4.8,"count":317,"slug":"korman-and-company-toronto","mapsUrl":"https://www.google.com/maps/search/Korman+%26+Company+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=721+Queen+St+E%2C+Toronto%2C+ON+M4M+1H1","website":"https://www.kormancompany.com","blurb":"Real Estate in Toronto. Rated 4.8 from 317 Google reviews.","type":"logo","src":"images/logos/korman-and-company-toronto.webp"}',NULL,'Korman & Company is a Toronto firm of real estate lawyers, with notary public services listed alongside other areas of practice.

The site''s navigation shows a real estate practice section, a page on other areas of practice, a notary public services page and a team page introducing its lawyers. Much of the visible page text is unrelated placeholder or off-topic material, so little further detail about the firm''s approach, history or clients can be stated reliably from its own website.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('neinstein-personal-injury-lawyers-toronto','Neinstein Personal Injury Lawyers','Toronto','ON','toronto',0,4.8,592,43.6699987,-79.3898475,'{"name":"Neinstein Personal Injury Lawyers","city":"Toronto","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"toronto","province":"ON","lat":43.6699987,"lng":-79.3898475,"address":"1200 Bay St. Suite 700, Toronto, ON M5R 2A5","phone":"+14169204242","rating":4.8,"count":592,"slug":"neinstein-personal-injury-lawyers-toronto","mapsUrl":"https://www.google.com/maps/search/Neinstein+Personal+Injury+Lawyers+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1200+Bay+St.+Suite+700%2C+Toronto%2C+ON+M5R+2A5","website":"https://www.neinstein.com","blurb":"Personal Injury in Toronto. Rated 4.8 from 592 Google reviews.","type":"logo","src":"images/logos/neinstein-personal-injury-lawyers-toronto.png"}',NULL,'Neinstein Personal Injury Lawyers is a Toronto firm that represents seriously and catastrophically injured people across Ontario.

The site says its lawyers have practised personal injury law in Ontario since 1970, a span it describes as more than 55 years. It lists serious car accidents, motorcycle accidents, long-term disability insurance disputes and slip and fall injuries among its matters. The firm says it has argued complex trials in courts across the country and negotiated multi-million dollar settlements, and that it works with clients on a contingency basis. Its structured data lists Toronto, Ontario and Canada as areas served.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('green-and-spiegel-llp-toronto','Green and Spiegel LLP','Toronto','ON','toronto',0,4.8,1213,43.649616,-79.384656,'{"name":"Green and Spiegel LLP","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.649616,"lng":-79.384656,"address":"150 York St 5th floor, Toronto, ON M5H 3S5","phone":"+14168627880","rating":4.8,"count":1213,"slug":"green-and-spiegel-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Green+and+Spiegel+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=150+York+St+5th+floor%2C+Toronto%2C+ON+M5H+3S5","website":"https://www.gands.com","blurb":"Immigration in Toronto. Rated 4.8 from 1213 Google reviews.","type":"logo","src":"images/logos/green-and-spiegel-llp-toronto.png"}',NULL,'Green and Spiegel LLP is a Toronto immigration firm practising Canadian and U.S. immigration law for corporations and individuals.

According to its website, Mendel Green established the firm in 1962, and it has practised only immigration law since. The site traces a move into the United States in the 1990s and the establishment of Green & Spiegel U.S. in 2012. Its head offices are in Toronto and Philadelphia. Services are organized into corporate immigration, covering global mobility and compliance for businesses, and individual immigration, with separate Canadian and U.S. sections.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('unified-immigration-lawyers-toronto','Unified Immigration Lawyers','Toronto','ON','toronto',0,4.8,809,43.6503578,-79.3967078,'{"name":"Unified Immigration Lawyers","city":"Toronto","featured":false,"tags":["Immigration","Civil Litigation"],"caseTypes":["immigration","litigation"],"region":"toronto","province":"ON","lat":43.6503578,"lng":-79.3967078,"address":"197 Spadina Ave. Ste 400, Toronto, ON M5T 2C8","phone":"+14375251293","rating":4.8,"count":809,"slug":"unified-immigration-lawyers-toronto","mapsUrl":"https://www.google.com/maps/search/Unified+Immigration+Lawyers+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=197+Spadina+Ave.+Ste+400%2C+Toronto%2C+ON+M5T+2C8","website":"https://uilawyers.com","blurb":"Immigration / Civil Litigation in Toronto. Rated 4.8 from 809 Google reviews.","type":"logo","src":"images/logos/unified-immigration-lawyers-toronto.webp"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Unified Immigration Lawyers is a Toronto firm handling Canadian and U.S. immigration applications, appeals and sponsorships.

The firm was formerly known as Matkowsky Immigration Law. Its structured data gives 2017 as the founding year. The firm says it acts for individuals, families and corporations, with work ranging from Federal Court appeals and spousal sponsorship to executive work visas. It states that clients deal directly with lawyers rather than consultants or paralegals, and that it works on flat fees. Sonia Akilov is named on the site, and a step-by-step page explains how a file moves from first meeting to filing.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('axess-law-toronto','Axess Law','Toronto','ON','toronto',0,4.8,2534,43.6899033,-79.3929527,'{"name":"Axess Law","city":"Toronto","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"toronto","province":"ON","lat":43.6899033,"lng":-79.3929527,"address":"43 Alvin Ave, Toronto, ON M4T 2A7","phone":"+18444705020","rating":4.8,"count":2534,"slug":"axess-law-toronto","mapsUrl":"https://www.google.com/maps/search/Axess+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=43+Alvin+Ave%2C+Toronto%2C+ON+M4T+2A7","website":"https://www.axesslaw.com","blurb":"Wills & Estates in Toronto. Rated 4.8 from 2534 Google reviews.","type":"logo","src":"images/logos/axess-law-toronto.png"}',NULL,'Axess Law is a Toronto firm that handles home closings online or at the client''s home, and also advises small businesses on incorporation and registration.

The site says the firm has focused for over a decade on virtual real estate closings, with a short onboarding process, video signing meetings, in-home signing and status updates. It also mentions closings for Quebec properties. Its business law page covers business names, registration, incorporation and partnerships for small businesses and start-ups, through virtual or in-person appointments in Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('randy-ai-law-office-toronto','Randy Ai Law Office','Toronto','ON','toronto',0,4.8,558,43.6546403,-79.3790879,'{"name":"Randy Ai Law Office","city":"Toronto","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.6546403,"lng":-79.3790879,"address":"210 Victoria St #4311, Toronto, ON M5B 2R3","phone":"+18662910998","rating":4.8,"count":558,"slug":"randy-ai-law-office-toronto","mapsUrl":"https://www.google.com/maps/search/Randy+Ai+Law+Office+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=210+Victoria+St+%234311%2C+Toronto%2C+ON+M5B+2R3","website":"https://www.employmentlawyer-toronto.com","blurb":"Employment Law in Toronto. Rated 4.8 from 558 Google reviews.","type":"logo","src":"images/logos/randy-ai-law-office-toronto.jpg"}','{"1":[["06:00","22:30"]],"2":[["06:00","22:30"]],"3":[["06:00","22:30"]],"4":[["06:00","22:30"]],"5":[["06:00","22:30"]],"6":[["06:00","22:30"]],"7":[["06:00","22:30"]]}','Randy Ai Law Office is a Toronto employment law practice handling severance, wrongful dismissal and workplace harassment matters.

According to its website, the firm was founded in 2014 by Randy Ai and acts for both employees and employers across Ontario. Its listed areas include labour law, human rights, disability law, employment litigation and class actions, and it cites the Employment Standards Act, the Canada Labour Code and the Ontario Human Rights Code. The site says the firm has represented more than 10,000 clients, offers evening and weekend appointments, and notes that Randy Ai appears on CTV News and writes for the Globe and Mail.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('unified-llp-toronto','Unified LLP','Toronto','ON','toronto',0,4.8,317,43.6503576,-79.3967077,'{"name":"Unified LLP","city":"Toronto","featured":false,"tags":["Real Estate","Employment Law"],"caseTypes":["realestate","employment"],"region":"toronto","province":"ON","lat":43.6503576,"lng":-79.3967077,"address":"197 Spadina Ave. 4th Floor, Toronto, ON M5T 2C8","phone":"+14167877678","rating":4.8,"count":317,"slug":"unified-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Unified+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=197+Spadina+Ave.+4th+Floor%2C+Toronto%2C+ON+M5T+2C8","website":"https://www.unifiedllp.com","blurb":"Real Estate / Employment Law in Toronto. Rated 4.8 from 317 Google reviews.","type":"logo","src":"images/logos/unified-llp-toronto.webp"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Unified LLP is a Toronto firm handling long-term disability, family, real estate, labour and employment matters for clients across Ontario.

The firm says its offices are in Toronto and that it also serves the GTA and Kitchener. On the labour side it acts for unions, not individual grievors, in grievance arbitration, tribunals, professional regulators and courts. Its family group lists uncontested and contested divorces, separation agreements, support and parenting, with flat-fee options for straightforward matters. For disability claims, the site describes help for people whose short-term or long-term benefits are denied, delayed or cut off, and says some matters proceed on a contingency fee basis.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ylaw-vancouver','YLaw','Vancouver','BC','bc-vancouver',0,4.8,337,49.2752185,-123.1208857,'{"name":"YLaw","city":"Vancouver","featured":false,"tags":["Family Law","Civil Litigation","Employment Law","Immigration"],"caseTypes":["family","litigation","employment","immigration"],"region":"bc-vancouver","province":"BC","lat":49.2752185,"lng":-123.1208857,"address":"1122 Mainland St #580, Vancouver, BC V6B 5L1","phone":"+16049749529","rating":4.8,"count":337,"slug":"ylaw-vancouver","mapsUrl":"https://www.google.com/maps/search/YLaw+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1122+Mainland+St+%23580%2C+Vancouver%2C+BC+V6B+5L1","website":"https://www.ylaw.ca","blurb":"Family Law / Civil Litigation in Vancouver. Rated 4.8 from 337 Google reviews.","type":"logo","src":"images/logos/ylaw-vancouver.png"}',NULL,'YLaw is a Vancouver firm handling family, employment, estate litigation, immigration and strata law matters across British Columbia.

The firm lists offices in Vancouver, Langley and Chilliwack, and its site also refers to Surrey. Its family lawyers deal with divorce, common-law separation, asset and debt division, spousal and child support and parenting time, plus mediation. The employment group covers wrongful dismissal, severance, contracts and workplace equity, while estate litigators handle will disputes and unfair wills. YLaw also lists civil litigation and class actions. It says it does not treat every case as a battle and focuses on a client''s long-term family, career and financial interests.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('immiland-montreal','Immiland','Montreal','QC','qc-montreal',0,4.8,1067,45.529777,-73.5565972,'{"name":"Immiland","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.529777,"lng":-73.5565972,"address":"2025 Rue Parthenais #320, Montreal, Quebec H2K 3T2","phone":"+14386302527","rating":4.8,"count":1067,"slug":"immiland-montreal","mapsUrl":"https://www.google.com/maps/search/Immiland+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2025+Rue+Parthenais+%23320%2C+Montreal%2C+Quebec+H2K+3T2","website":"https://www.immilandcanada.com","blurb":"Immigration in Montreal. Rated 4.8 from 1067 Google reviews.","type":"logo","src":"images/logos/immiland-montreal.png"}',NULL,'Immiland is a Montreal immigration consulting company that helps families, workers and students plan a move to Canada, with its website written in Spanish.

Its service list covers immigration, recruitment, education, translation and settlement, along with pages on working in Canada, studying in Canada and tourist visas. The firm says it holds more than 100 education agreements with colleges, universities and institutes recognized as Designated Learning Institutions, which lets it process study permits. Its site also addresses practical settlement questions such as choosing a neighbourhood. Immiland states that it is regulated by the Law Society of Ontario and the College of Immigration and Citizenship Consultants, and its office is on Rue Parthenais.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('liberty-law-llp-edmonton','Liberty Law LLP','Edmonton','AB','ab-edmonton',0,4.8,298,53.5410763,-113.5049513,'{"name":"Liberty Law LLP","city":"Edmonton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-edmonton","province":"AB","lat":53.5410763,"lng":-113.5049513,"address":"10110 107 St NW, Edmonton, AB T5J 1J4","phone":"+17807847500","rating":4.8,"count":298,"slug":"liberty-law-llp-edmonton","mapsUrl":"https://www.google.com/maps/search/Liberty+Law+LLP+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10110+107+St+NW%2C+Edmonton%2C+AB+T5J+1J4","website":"https://libertylaw.ca","blurb":"Criminal Defence in Edmonton. Rated 4.8 from 298 Google reviews.","type":"logo","src":"images/logos/liberty-law-llp-edmonton.webp"}','{"1":[["08:30","17:00"]],"2":[["08:30","17:00"]],"3":[["08:30","17:00"]],"4":[["08:30","17:00"]],"5":[["08:30","17:00"]]}','Liberty Law LLP is an Edmonton criminal defence firm that represents people charged with offences at every level of Alberta courts.

The firm says it practises criminal defence only. Its lawyers appear in Provincial Court, the Court of King''s Bench and the Court of Appeal, and the matters it lists include murder, sexual assault, drug and weapon offences, domestic violence, impaired driving and appeals. Besides its downtown Edmonton office, it has offices in Grande Prairie and Fort McMurray, and its structured data names Alberta, Saskatchewan and the Northwest Territories as areas served. The site describes a team of more than twenty lawyers, including senior trial and appellate counsel.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gogna-immigration-inc-edmonton','Gogna Immigration Inc.','Edmonton','AB','ab-edmonton',0,4.9,291,53.5482266,-113.6209608,'{"name":"Gogna Immigration Inc.","city":"Edmonton","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"ab-edmonton","province":"AB","lat":53.5482266,"lng":-113.6209608,"address":"17415 105 Ave NW, Edmonton, AB T5S 2G8","phone":"+17802441907","rating":4.9,"count":291,"slug":"gogna-immigration-inc-edmonton","mapsUrl":"https://www.google.com/maps/search/Gogna+Immigration+Inc.+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=17415+105+Ave+NW%2C+Edmonton%2C+AB+T5S+2G8","website":"https://www.gognaimmigration.com","blurb":"Immigration in Edmonton. Rated 4.9 from 291 Google reviews.","type":"logo","src":"images/logos/gogna-immigration-inc-edmonton.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Gogna Immigration Inc., based in Edmonton, is a team of regulated immigration consultants handling Canadian visas, citizenship and immigration applications.

The company says it serves clients across Canada and overseas, and names St. Albert, Leduc, Sherwood Park, Fort Saskatchewan and Spruce Grove among the nearby communities it covers. Rather than limiting itself to one category or program, it describes helping with a broad range of applications. Its site highlights Neha, who it says has worked in immigration consulting for more than a decade, and states that its aim is to simplify immigration steps for people whose applications affect their families and futures.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('shapiro-llp-north-york','Shapiro LLP','North York','ON','toronto',0,4.7,446,43.765946,-79.3900944,'{"name":"Shapiro LLP","city":"North York","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.765946,"lng":-79.3900944,"address":"333 Sheppard Ave E #201, North York, ON M2N 3B3","phone":"+14162240808","rating":4.7,"count":446,"slug":"shapiro-llp-north-york","mapsUrl":"https://www.google.com/maps/search/Shapiro+LLP+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=333+Sheppard+Ave+E+%23201%2C+North+York%2C+ON+M2N+3B3","website":"https://www.shapirollp.ca","blurb":"Real Estate in North York. Rated 4.7 from 446 Google reviews.","type":"logo","src":"images/logos/shapiro-llp-north-york.png"}',NULL,'Shapiro LLP is a North York law firm serving the Greater Toronto Area in residential and commercial real estate, business law, and wills and estates.

According to its website, the firm''s work also includes commercial matters and private mortgages, and it describes providing legal services across Canada. Its listing places the practice at Sheppard Avenue East in North York. The site text available for this profile is brief, so the practice areas above are the ones the firm itself names, grouped under real estate, business and commercial law, private mortgage work and wills, estates and trusts.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bellissimo-immigration-law-group-pc-toronto','Bellissimo Immigration Law Group PC','Toronto','ON','toronto',0,4.7,560,43.7066847,-79.3994865,'{"name":"Bellissimo Immigration Law Group PC","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.7066847,"lng":-79.3994865,"address":"20 Eglinton Ave W #1402, Toronto, ON M4R 1K8","phone":"+14167876505","rating":4.7,"count":560,"slug":"bellissimo-immigration-law-group-pc-toronto","mapsUrl":"https://www.google.com/maps/search/Bellissimo+Immigration+Law+Group+PC+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=20+Eglinton+Ave+W+%231402%2C+Toronto%2C+ON+M4R+1K8","website":"https://www.bellissimolawgroup.com","blurb":"Immigration in Toronto. Rated 4.7 from 560 Google reviews.","type":"logo","src":"images/logos/bellissimo-immigration-law-group-pc-toronto.webp"}',NULL,'Bellissimo Immigration Law Group PC is a Toronto firm handling immigration, citizenship and refugee matters for individuals and families from around the world.

The firm says it is one of few remaining law firms in Canada that focus exclusively on citizenship, immigration and refugee law, and that its team''s experience goes back more than forty-five years. It states that it has been responsible for key court decisions, policy work and publications in the field. Its work includes complex citizenship, immigration and refugee appeals and inadmissibility cases. The site also describes a client-centred approach with plain and transparent communication, and answers common questions about hiring an immigration lawyer in Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('choice-immigration-services-edmonton','Choice Immigration Services','Edmonton','AB','ab-edmonton',0,4.7,322,53.4518213,-113.4778738,'{"name":"Choice Immigration Services","city":"Edmonton","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"ab-edmonton","province":"AB","lat":53.4518213,"lng":-113.4778738,"address":"9650 20 Ave NW Ste 103, Edmonton, AB T6N 1G1","phone":"+17804367666","rating":4.7,"count":322,"slug":"choice-immigration-services-edmonton","mapsUrl":"https://www.google.com/maps/search/Choice+Immigration+Services+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9650+20+Ave+NW+Ste+103%2C+Edmonton%2C+AB+T6N+1G1","website":"https://choiceimmigration.ca","blurb":"Immigration in Edmonton. Rated 4.7 from 322 Google reviews.","type":"logo","src":"images/logos/choice-immigration-services-edmonton.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Choice Immigration Services is an Edmonton immigration practice handling permanent residence, study and work visas, sponsorships and citizenship applications.

The firm lists provincial nominations, LMIA applications, immigration appeals and refugee cases among its work, and also offers assessments and commissioner of oaths services. It says its team of regulated immigration consultants has over 16 years of combined experience. Clients are taken through three steps: an assessment, preparation of the case and filing of the application, and then the outcome. The site describes managing an application from document preparation through submission, and notes that Alberta and wider Canadian immigration rules have become stricter over time.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lambert-avocats-montreal','Lambert Avocats','Montreal','QC','qc-montreal',0,4.7,399,45.5013271,-73.5707508,'{"name":"Lambert Avocats","city":"Montreal","featured":false,"tags":["Personal Injury","Civil Litigation","Criminal Defence","Real Estate"],"caseTypes":["injury","litigation","criminal","realestate"],"region":"qc-montreal","province":"QC","lat":45.5013271,"lng":-73.5707508,"address":"1200 McGill College Ave bureau 1800, Montreal, Quebec H3B 4G7","phone":"+15145262378","rating":4.7,"count":399,"slug":"lambert-avocats-montreal","mapsUrl":"https://www.google.com/maps/search/Lambert+Avocats+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1200+McGill+College+Ave+bureau+1800%2C+Montreal%2C+Quebec+H3B+4G7","website":"https://lambertavocats.ca","blurb":"Personal Injury / Civil Litigation in Montreal. Rated 4.7 from 399 Google reviews.","type":"logo","src":"images/logos/lambert-avocats-montreal.png"}',NULL,'Lambert Avocats is a Montreal firm handling civil, administrative, criminal, penal and disciplinary law, including SAAQ and injury claims.

The firm''s website, written in French, says it offers percentage-based, hourly or mixed fee arrangements and is available around the clock in criminal matters. Its civil liability work covers injuries from unsafe public places and collapsed stairs or balconies. A further section addresses disciplinary law, with a page for nurses facing complaints before the Ordre des infirmières et infirmiers. The practice is located on McGill College Avenue and says it represents clients through each stage, from explaining rights and obligations to filing proceedings and appearing in court.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('barrou-nadia-montreal','Barrou Nadia','Montreal','QC','qc-montreal',0,4.7,351,45.4958427,-73.6163753,'{"name":"Barrou Nadia","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.4958427,"lng":-73.6163753,"address":"5000 Decelles Ave Suite 101, Montreal, Quebec H3V 1H7","phone":"+15142861613","rating":4.7,"count":351,"slug":"barrou-nadia-montreal","mapsUrl":"https://www.google.com/maps/search/Barrou+Nadia+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5000+Decelles+Ave+Suite+101%2C+Montreal%2C+Quebec+H3V+1H7","website":"https://www.barrou.com","blurb":"Immigration in Montreal. Rated 4.7 from 351 Google reviews.","type":"logo","src":"images/logos/barrou-nadia-montreal.png"}',NULL,'Barrou Nadia is a Montreal immigration law practice handling temporary visas, permanent residence, sponsorship and citizenship applications.

The firm says it has worked in Canadian immigration law since 1998, with a team of lawyers and consultants. Its site lists applications for foreign students, temporary workers, permanent residents, sponsored family members, visitors and prospective citizens. Work permit routes it names include labour market impact assessment streams, the International Mobility Program, the Programme de l''expérience québécoise and the regular skilled worker program, along with permanent resident card renewals. The site notes that Nadia Barrou Avocate Inc. now operates as Barrou Immigration Inc. and says the team presents online webinars.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lmrt-immigration-services-montreal','LMRT Immigration Services','Montreal','QC','qc-montreal',0,4.7,481,45.5390818,-73.6550021,'{"name":"LMRT Immigration Services","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.5390818,"lng":-73.6550021,"address":"433 Rue Chabanel O Office 620, Montreal, Quebec H2N 2J9","phone":"+14387006165","rating":4.7,"count":481,"slug":"lmrt-immigration-services-montreal","mapsUrl":"https://www.google.com/maps/search/LMRT+Immigration+Services+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=433+Rue+Chabanel+O+Office+620%2C+Montreal%2C+Quebec+H2N+2J9","website":"https://lmrtimmigration.com","blurb":"Immigration in Montreal. Rated 4.7 from 481 Google reviews.","type":"logo","src":"images/logos/lmrt-immigration-services-montreal.png"}','{"1":[["09:30","16:30"]],"2":[["09:30","16:30"]],"3":[["09:30","16:30"]],"4":[["09:30","16:30"]],"5":[["09:30","16:30"]]}','LMRT Immigration Services is a Montreal team of regulated immigration consultants handling asylum claims, family sponsorship and Express Entry.

The firm says it has worked on refugee and sponsorship files since 2017 and that its founder, Loujin Khalil, is a regulated consultant authorized to appear before the Immigration and Refugee Board. His background includes business immigration streams such as entrepreneur programs, the Start-up Visa and owner-operator. The site lists English, French, Arabic and Persian, mentions Quebec programs, offers online appointments and publishes guides on topics such as the four divisions of the Immigration and Refugee Board of Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('diversitas-law-group-london','Diversitas Law Group','London','ON','southwestern',0,4.7,312,42.9730033,-81.2624282,'{"name":"Diversitas Law Group","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9730033,"lng":-81.2624282,"address":"145 Wharncliffe Rd S #100, London, ON N6J 2K4","phone":"+15199143380","rating":4.7,"count":312,"slug":"diversitas-law-group-london","mapsUrl":"https://www.google.com/maps/search/Diversitas+Law+Group+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=145+Wharncliffe+Rd+S+%23100%2C+London%2C+ON+N6J+2K4","website":"https://www.dlawgroup.ca","blurb":"Family Law in London. Rated 4.7 from 312 Google reviews.","type":"logo","src":"images/logos/diversitas-law-group-london.png"}',NULL,'Diversitas Law Group is a London, Ontario association of independent practitioners handling immigration, citizenship and refugee protection matters.

The group states plainly that it is not a law firm, partnership or limited liability company: each sole practitioner runs a separate practice, shares office space and administrative resources, and holds the solicitor-client relationship personally. It reports more than thirty years of combined experience and offers service in Arabic, Spanish, Mandarin, Cantonese, Hindi, Punjabi and Urdu. Its pages cover immigration, refugee and citizenship appeals, including reconsideration, residency obligation appeals and responses to various immigration refusals.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ronen-kurzfeld-immigration-lawyer-toronto-north-york','Ronen Kurzfeld Immigration Lawyer Toronto','North York','ON','toronto',0,4.8,279,43.7634621,-79.404535,'{"name":"Ronen Kurzfeld Immigration Lawyer Toronto","city":"North York","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.7634621,"lng":-79.404535,"address":"110 Sheppard Ave E Ste 630, North York, ON M2N 6Y8","phone":"+16472497976","rating":4.8,"count":279,"slug":"ronen-kurzfeld-immigration-lawyer-toronto-north-york","mapsUrl":"https://www.google.com/maps/search/Ronen+Kurzfeld+Immigration+Lawyer+Toronto+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=110+Sheppard+Ave+E+Ste+630%2C+North+York%2C+ON+M2N+6Y8","website":"https://www.immigrationway.com","blurb":"Immigration in North York. Rated 4.8 from 279 Google reviews.","type":"logo","src":"images/logos/ronen-kurzfeld-immigration-lawyer-toronto-north-york.webp"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Ronen Kurzfeld Immigration Lawyer Toronto is a North York practice handling spousal sponsorship, Express Entry, citizenship and immigration appeals.

The firm describes itself as a licensed and insured immigration law office headquartered in the Toronto area. It says Ronen Kurzfeld graduated from Osgoode Hall Law School, studied in its intensive immigration and refugee law programme, and has more than twenty years in the field with over 2,500 clients worldwide. Services named include business applications and enforcement matters, and the site says the team can represent clients in almost any language. It also mentions payment plans and publishes articles on refugee claims and refusal appeals.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('randhawa-law-centre-surrey','Randhawa Law Centre','Surrey','BC','bc-fraser',0,4.8,277,49.1475771,-122.8671023,'{"name":"Randhawa Law Centre","city":"Surrey","featured":false,"tags":["Family Law","Real Estate","Wills & Estates"],"caseTypes":["family","realestate","wills"],"region":"bc-fraser","province":"BC","lat":49.1475771,"lng":-122.8671023,"address":"12830 80 Ave #105B, Surrey, BC V3W 3A8","phone":"+17785644774","rating":4.8,"count":277,"slug":"randhawa-law-centre-surrey","mapsUrl":"https://www.google.com/maps/search/Randhawa+Law+Centre+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=12830+80+Ave+%23105B%2C+Surrey%2C+BC+V3W+3A8","website":"https://www.randhawalawyer.com","blurb":"Family Law / Real Estate in Surrey. Rated 4.8 from 277 Google reviews.","type":"logo","src":"images/logos/randhawa-law-centre-surrey.png"}','{"1":[["09:00","18:00"]],"2":[["09:00","18:00"]],"3":[["09:00","18:00"]],"4":[["09:00","18:00"]],"5":[["09:00","18:00"]],"6":[["09:00","18:00"]]}','Randhawa Law Centre is a Surrey, BC law office and notary practice handling real estate, family law, and wills and estates for the Lower Mainland.

The firm was founded by Honveer Randhawa, who earned his law degree at the University of Manitoba, and it serves clients in English, Punjabi and Hindi. Its listed work includes divorce, builder''s liens, property sales and purchases, refinancing, mortgage conveyancing, certificates of pending litigation and notary services, with immigration also mentioned. The site says it keeps late weekday hours, is available on weekends when needed, and welcomes walk-ins at its ground-floor office on 80 Avenue.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('crossroads-law-vancouver','Crossroads Law','Vancouver','BC','bc-vancouver',0,4.9,270,49.2873133,-123.1160038,'{"name":"Crossroads Law","city":"Vancouver","featured":false,"tags":["Family Law","Civil Litigation","Wills & Estates"],"caseTypes":["family","litigation","wills"],"region":"bc-vancouver","province":"BC","lat":49.2873133,"lng":-123.1160038,"address":"999 W Hastings St Ste 1660, Vancouver, BC V6C 2W2","phone":"+18004661838","rating":4.9,"count":270,"slug":"crossroads-law-vancouver","mapsUrl":"https://www.google.com/maps/search/Crossroads+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=999+W+Hastings+St+Ste+1660%2C+Vancouver%2C+BC+V6C+2W2","website":"https://www.crossroadslaw.ca","blurb":"Family Law / Civil Litigation in Vancouver. Rated 4.9 from 270 Google reviews.","type":"logo","src":"images/logos/crossroads-law-vancouver.png"}','{"1":[["08:30","16:30"]],"2":[["08:30","16:30"]],"3":[["08:30","16:30"]],"4":[["08:30","16:30"]],"5":[["08:30","16:30"]]}','Crossroads Law is a Vancouver family law firm handling divorce, separation, child support and parenting matters in British Columbia and Alberta.

According to its site, the firm was founded in 2017 and has family lawyers in Vancouver, Calgary and Edmonton. Beyond court proceedings, it offers mediation, collaborative family law and arbitration, and describes billing choices that range from flat-rate fees to legal coaching and unbundled services. Remote legal support is also listed. The firm says it takes a client-centred approach, features a discussion of legal coaching with lawyer Marcus Sixta, and describes volunteer work and partnerships with community organizations in both provinces.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('anderson-haak-and-engels-edmonton','Anderson Haak & Engels','Edmonton','AB','ab-edmonton',0,4.8,255,53.4670976,-113.4822157,'{"name":"Anderson Haak & Engels","city":"Edmonton","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"ab-edmonton","province":"AB","lat":53.4670976,"lng":-113.4822157,"address":"9811 34 Ave NW, Edmonton, AB T6E 5X9","phone":"+17804131763","rating":4.8,"count":255,"slug":"anderson-haak-and-engels-edmonton","mapsUrl":"https://www.google.com/maps/search/Anderson+Haak+%26+Engels+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9811+34+Ave+NW%2C+Edmonton%2C+AB+T6E+5X9","website":"https://www.albertarealestatelawyers.com","blurb":"Real Estate in Edmonton. Rated 4.8 from 255 Google reviews.","type":"logo","src":"images/logos/anderson-haak-and-engels-edmonton.png"}',NULL,'Anderson Haak & Engels is an Edmonton real estate law firm handling home and condo purchases, sales and mortgage refinancing in Alberta.

The site explains that a lawyer is needed in Alberta to transfer title on a purchase or sale, and says the firm brings more than sixty years of experience to that work. Its homepage cites over 45,000 real estate transactions and names partners Kenneth R. Haak and Robert A. Engels. The firm also prepares wills, personal care directives and enduring powers of attorney, and it publishes base fees for each service on its services page.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lm-law-group-toronto','LM Law Group','Toronto','ON','toronto',0,4.9,249,43.6522998,-79.3752505,'{"name":"LM Law Group","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.6522998,"lng":-79.3752505,"address":"103 Church St #500, Toronto, ON M5C 2G3","phone":"+14165489101","rating":4.9,"count":249,"slug":"lm-law-group-toronto","mapsUrl":"https://www.google.com/maps/search/LM+Law+Group+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=103+Church+St+%23500%2C+Toronto%2C+ON+M5C+2G3","website":"https://www.lmlawgroup.com","blurb":"Immigration in Toronto. Rated 4.9 from 249 Google reviews.","type":"logo","src":"images/logos/lm-law-group-toronto.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','LM Law Group is a Toronto immigration firm handling study permits, work permits, permanent residence, visitor visas, Express Entry and citizenship applications.

The firm lists 2007 as its founding year and describes a team of about 25. Partners named on its site are Elizabeth Long, Aadil Mangalji and Ziah Sumar, with associates including Erin Levitsky and Catanne Boan-Mitchell. Its services are organized by client group: employers, students, permanent residents, workers, visitors, citizens and entrepreneurs. The firm says each case is reviewed individually so that the immigration path fits the person, and it describes an empathy-focused approach.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('seif-law-firm-richmond-hill','Seif Law Firm','Richmond Hill','ON','york-durham',0,4.7,255,43.8781396,-79.4392513,'{"name":"Seif Law Firm","city":"Richmond Hill","featured":false,"tags":["Wills & Estates","Civil Litigation"],"caseTypes":["wills","litigation"],"region":"york-durham","province":"ON","lat":43.8781396,"lng":-79.4392513,"address":"10288 Yonge St Unit 3, Richmond Hill, ON L4C 3B8","phone":"+19052377343","rating":4.7,"count":255,"slug":"seif-law-firm-richmond-hill","mapsUrl":"https://www.google.com/maps/search/Seif+Law+Firm+Richmond+Hill+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10288+Yonge+St+Unit+3%2C+Richmond+Hill%2C+ON+L4C+3B8","website":"https://www.seiflawfirm.com","blurb":"Wills & Estates / Civil Litigation in Richmond Hill. Rated 4.7 from 255 Google reviews.","type":"logo","src":"images/logos/seif-law-firm-richmond-hill.jpg"}',NULL,'Seif Law Firm is a Richmond Hill practice serving the Greater Toronto Area, with real estate, wills, powers of attorney and notary services.

The firm says its main focus is real estate law, covering buying, selling and refinancing, and it also lists private mortgages, family law and litigation. Adam Seif is licensed in Canada and the United States, belongs to the Florida Bar and opened his own practice in 2011 after articling. The team includes lawyers, law clerks and legal assistants, and the site says a live person answers around the clock. It mentions a multilingual team and includes text in French.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dimitri-trofimoff-lawyer-ottawa','Dimitri Trofimoff Lawyer','Ottawa','ON','eastern',0,4.9,238,45.3009275,-75.8822862,'{"name":"Dimitri Trofimoff Lawyer","city":"Ottawa","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"eastern","province":"ON","lat":45.3009275,"lng":-75.8822862,"address":"430 Hazeldean Rd Unit 6, Ottawa, ON K2L 1T9","phone":"+18885119118","rating":4.9,"count":238,"slug":"dimitri-trofimoff-lawyer-ottawa","mapsUrl":"https://www.google.com/maps/search/Dimitri+Trofimoff+Lawyer+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=430+Hazeldean+Rd+Unit+6%2C+Ottawa%2C+ON+K2L+1T9","website":"https://gotlaw.ca","blurb":"Family Law in Ottawa. Rated 4.9 from 238 Google reviews.","type":"logo","src":"images/logos/dimitri-trofimoff-lawyer-ottawa.png"}',NULL,'Dimitri Trofimoff Lawyer is an Ottawa practice handling family law and criminal defence, with offices serving Ottawa, Kanata and Perth.

On the criminal side, the site describes representation from police interaction and bail hearings through negotiation with prosecutors, judicial pre-trial and trial in Ontario courts. Its family work covers anything from a simple divorce to a complicated separation. The office also provides certification of copies, witnessing of signatures, commissioning of oaths, and travel and invitation letters. It lists three locations in the region and virtual meetings, and describes Dimitri Trofimoff''s education across Russia, England and Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lawyerg-calgary','LawyerG','Calgary','AB','ab-calgary',0,4.9,234,51.0672085,-114.0684562,'{"name":"LawyerG","city":"Calgary","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"ab-calgary","province":"AB","lat":51.0672085,"lng":-114.0684562,"address":"320 16 Ave NW Ste 105, Calgary, AB T2M 0H6","phone":"+14034545294","rating":4.9,"count":234,"slug":"lawyerg-calgary","mapsUrl":"https://www.google.com/maps/search/LawyerG+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=320+16+Ave+NW+Ste+105%2C+Calgary%2C+AB+T2M+0H6","website":"https://www.lawyerg.ca","blurb":"Real Estate / Wills & Estates in Calgary. Rated 4.9 from 234 Google reviews.","type":"logo","src":"images/logos/lawyerg-calgary.jpg"}',NULL,'LawyerG is a Calgary law office led by Gurpreet Aulakh, handling real estate, corporate and commercial law, wills and family matters.

The firm describes itself as full service, with a focus on real property and on corporate and commercial work. For home buyers and sellers it covers real property reports and land title transfers; for families it also prepares prenuptial and cohabitation contracts, and it offers notary services such as travel documents. Civil litigation and personal injury also appear on its list. Gurpreet Aulakh holds law and business degrees, a cyber crime investigation certification, and memberships in the Law Society of Alberta, Legal Aid Alberta and the Calgary Bar Association.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('alexander-hu-professional-corporation-toronto','Alexander Hu Professional Corporation','Toronto','ON','toronto',0,5,229,43.6556261,-79.3864674,'{"name":"Alexander Hu Professional Corporation","city":"Toronto","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.6556261,"lng":-79.3864674,"address":"180 Dundas St W 25th Floor, Toronto, ON M5G 1Z8","phone":"+16473628618","rating":5,"count":229,"slug":"alexander-hu-professional-corporation-toronto","mapsUrl":"https://www.google.com/maps/search/Alexander+Hu+Professional+Corporation+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=180+Dundas+St+W+25th+Floor%2C+Toronto%2C+ON+M5G+1Z8","website":"https://www.alexhulaw.ca","blurb":"Real Estate in Toronto. Rated 5.0 from 229 Google reviews.","type":"logo","src":"images/logos/alexander-hu-professional-corporation-toronto.png"}',NULL,'Alexander Hu Professional Corporation is a Downtown Toronto law firm limited to real estate, handling home and condo purchases, sales and mortgages.

The firm''s structured data describes work on title examination, financing and closing coordination, and its pages mention the examination of condominium status certificates and collaboration with realtors and mortgage lenders. It serves Toronto, Peel, Durham, York and Halton regions, with page content on Central Toronto, Old York, East York, Etobicoke, North York and Scarborough. Topics covered include multiple offers, rezoning and development, property taxes, land transfer taxes and mixed-use or commercial properties.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mandall-immigration-law-toronto','Mandall Immigration Law','Toronto','ON','toronto',0,5,229,43.6599948,-79.3851994,'{"name":"Mandall Immigration Law","city":"Toronto","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"toronto","province":"ON","lat":43.6599948,"lng":-79.3851994,"address":"763 Bay St. #3008, Toronto, ON M7A 1S5","phone":"+16479305067","rating":5,"count":229,"slug":"mandall-immigration-law-toronto","mapsUrl":"https://www.google.com/maps/search/Mandall+Immigration+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=763+Bay+St.+%233008%2C+Toronto%2C+ON+M7A+1S5","website":"https://mandallimmigrationlaw.com","blurb":"Immigration in Toronto. Rated 5.0 from 229 Google reviews.","type":"logo","src":"images/logos/mandall-immigration-law-toronto.webp"}',NULL,'Mandall Immigration Law is a Toronto firm handling visitor visas, study and work permits, spousal sponsorship, Express Entry and immigration appeals.

The firm is led by founder Austin Mandall Rooplall, who personally examines every file according to its site, and it has offices in Toronto and Ottawa. Its structured data gives a 2024 founding date. Other services include PR card renewals, humanitarian applications, inadmissibility matters and LMIA-related work permits, and pages explain the difference between LMIA-based and exempt permits. The firm says it serves clients across Canada and worldwide and describes a transparent, client-centred approach.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dlegal-law-office-wills-calgary','DLegal Law Office: Wills','Calgary','AB','ab-calgary',0,4.9,232,50.9019759,-114.0571543,'{"name":"DLegal Law Office: Wills","city":"Calgary","featured":false,"tags":["Family Law","Real Estate","Wills & Estates","Employment Law"],"caseTypes":["family","realestate","wills","employment"],"region":"ab-calgary","province":"AB","lat":50.9019759,"lng":-114.0571543,"address":"40 Sunpark Plaza SE Ste 226, Calgary, AB T2X 3X7","phone":"+15878851783","rating":4.9,"count":232,"slug":"dlegal-law-office-wills-calgary","mapsUrl":"https://www.google.com/maps/search/DLegal+Law+Office%3A+Wills+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=40+Sunpark+Plaza+SE+Ste+226%2C+Calgary%2C+AB+T2X+3X7","website":"https://dlegal.ca","blurb":"Family Law / Real Estate in Calgary. Rated 4.9 from 232 Google reviews.","type":"logo","src":"images/logos/dlegal-law-office-wills-calgary.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','DLegal Law Office: Wills is a Calgary practice handling wills and estate planning, family matters, real estate transactions and business law.

The firm describes its approach as everyday legal services for everyday needs, supporting Calgary families through each stage of life. It publishes its flat fees on its website and says transparency and predictability matter to its clients. Lawyer and notary Anna Dunaeva is named on the site, which also carries resources on the roles of executors and estate trustees and on the Estate Administration Act in Alberta. The firm mentions serving on community boards and teaching seminars around Calgary.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hammerco-lawyers-llp-vancouver','Hammerco Lawyers LLP','Vancouver','BC','bc-vancouver',0,4.7,241,49.2654367,-123.1097418,'{"name":"Hammerco Lawyers LLP","city":"Vancouver","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"bc-vancouver","province":"BC","lat":49.2654367,"lng":-123.1097418,"address":"2233 Columbia St #400, Vancouver, BC V5Y 0M6","phone":"+16042698500","rating":4.7,"count":241,"slug":"hammerco-lawyers-llp-vancouver","mapsUrl":"https://www.google.com/maps/search/Hammerco+Lawyers+LLP+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2233+Columbia+St+%23400%2C+Vancouver%2C+BC+V5Y+0M6","website":"https://hammerco.ca","blurb":"Personal Injury in Vancouver. Rated 4.7 from 241 Google reviews.","type":"logo","src":"images/logos/hammerco-lawyers-llp-vancouver.png"}',NULL,'Hammerco Lawyers LLP is a Vancouver firm handling class actions, commercial litigation, estate litigation, personal injury and medical negligence.

The firm says it has served individuals and businesses for over twenty-five years in British Columbia and now in Ontario, with offices on Vancouver Island, in Vancouver and in London, Ontario. It also acts in civil sexual assault cases and publishes a guide for survivors of sexual assault. Lawyers named on its site include Morgyn Chandler, Douglas Chiu, Dale McGregor, Kevin McLaren, Krista Simon, Alexia Majidi and Sabrina Lombardi, and its pages mention service in Mandarin and Cantonese among other languages.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bottos-law-group-edmonton','Bottos Law Group','Edmonton','AB','ab-edmonton',0,4.9,223,53.543681,-113.499782,'{"name":"Bottos Law Group","city":"Edmonton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-edmonton","province":"AB","lat":53.543681,"lng":-113.499782,"address":"10226 104 Street NW 4th floor, Edmonton, AB T5J 1B8","phone":"+17804217001","rating":4.9,"count":223,"slug":"bottos-law-group-edmonton","mapsUrl":"https://www.google.com/maps/search/Bottos+Law+Group+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10226+104+Street+NW+4th+floor%2C+Edmonton%2C+AB+T5J+1B8","website":"https://bottoslaw.ca","blurb":"Criminal Defence in Edmonton. Rated 4.9 from 223 Google reviews.","type":"logo","src":"images/logos/bottos-law-group-edmonton.webp"}','{"1":[["08:00","17:00"]],"2":[["08:00","17:00"]],"3":[["08:00","17:00"]],"4":[["08:00","17:00"]],"5":[["08:00","17:00"]]}','Bottos Law Group is an Edmonton criminal defence firm representing people accused of serious criminal and regulatory charges across Alberta.

The firm says it was founded in 2012 and that its barristers have been involved in many high-profile criminal cases in Edmonton and elsewhere in the province. According to its site, it acts for individuals accused of any crime, and no matter is considered too small or too serious. Its lawyers, including Will van Engen, are described as offering straightforward and thorough legal advice. The firm also advertises articling positions for law students and publishes news items on its blog.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('addelman-baum-gilbert-llp-ottawa','Addelman Baum Gilbert LLP','Ottawa','ON','eastern',0,4.8,226,45.4222969,-75.6953132,'{"name":"Addelman Baum Gilbert LLP","city":"Ottawa","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"eastern","province":"ON","lat":45.4222969,"lng":-75.6953132,"address":"75 Albert St #207, Ottawa, ON K1P 5E7","phone":"+16132372673","rating":4.8,"count":226,"slug":"addelman-baum-gilbert-llp-ottawa","mapsUrl":"https://www.google.com/maps/search/Addelman+Baum+Gilbert+LLP+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=75+Albert+St+%23207%2C+Ottawa%2C+ON+K1P+5E7","website":"https://www.abgottawa.com","blurb":"Criminal Defence in Ottawa. Rated 4.8 from 226 Google reviews.","type":"logo","src":"images/logos/addelman-baum-gilbert-llp-ottawa.png"}',NULL,'Addelman Baum Gilbert LLP is an Ottawa firm handling criminal defence and child protection (C.A.S.) proceedings across Eastern Ontario.

The firm was formed in January 2010 by Richard Addelman, Douglas Baum, Jason Gilbert and Joseph Addelman. Based in Ottawa, it says it also serves Brockville, Cornwall, L''Orignal, Perth, Pembroke, Renfrew and Smiths Falls. It acts in criminal and regulatory offences as well as child protection cases, and describes trial and appellate work on matters such as homicides. Its site notes that Richard Addelman graduated from the University of Ottawa Faculty of Law in 1969 and helped found the Defence Counsel Association of Ottawa in 1975.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tim-louis-and-company-law-firm-vancouver','Tim Louis & Company Law Firm','Vancouver','BC','bc-vancouver',0,4.9,218,49.2671893,-123.1629687,'{"name":"Tim Louis & Company Law Firm","city":"Vancouver","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"bc-vancouver","province":"BC","lat":49.2671893,"lng":-123.1629687,"address":"2526 W 5th Ave, Vancouver, BC V6K 1T1","phone":"+16047327678","rating":4.9,"count":218,"slug":"tim-louis-and-company-law-firm-vancouver","mapsUrl":"https://www.google.com/maps/search/Tim+Louis+%26+Company+Law+Firm+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2526+W+5th+Ave%2C+Vancouver%2C+BC+V6K+1T1","website":"https://timlouislaw.com","blurb":"Personal Injury in Vancouver. Rated 4.9 from 218 Google reviews.","type":"logo","src":"images/logos/tim-louis-and-company-law-firm-vancouver.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]]}','Tim Louis & Company Law Firm is a Vancouver practice handling long-term disability claims, wills and estates, personal injury and employment law.

The firm is led by Tim Louis, who graduated from UBC Law in 1983, articled with Harry Rankin in 1984 and then opened his own practice. His site says he co-founded the BC Coalition of the Disabled, now Disability Alliance BC, and the Public Interest Advocacy Centre, and served on the Vancouver Park Board, City Council and Library Board. The firm assists clients across British Columbia with probate, estate disputes, wrongful dismissal and denied benefits, and offers service in English and Spanish.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('aviron-law-professional-corporation-brampton','Aviron Law Professional Corporation','Brampton','ON','peel-halton',0,5,211,43.6903483,-79.7316513,'{"name":"Aviron Law Professional Corporation","city":"Brampton","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.6903483,"lng":-79.7316513,"address":"159 Rutherford Rd S 2nd Floor, Brampton, ON L6W 3N5","phone":"+19054971200","rating":5,"count":211,"slug":"aviron-law-professional-corporation-brampton","mapsUrl":"https://www.google.com/maps/search/Aviron+Law+Professional+Corporation+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=159+Rutherford+Rd+S+2nd+Floor%2C+Brampton%2C+ON+L6W+3N5","website":"https://www.avironlaw.com","blurb":"Real Estate in Brampton. Rated 5.0 from 211 Google reviews.","type":"logo","src":"images/logos/aviron-law-professional-corporation-brampton.png"}',NULL,'Aviron Law Professional Corporation is a Brampton firm handling real estate, wills and estate planning, business law, immigration and civil litigation.

Its principal lawyer, Dilvir S. Tatter, holds LL.M. and LL.B. degrees, practises as barrister, solicitor and notary public, and began his career in litigation on contractual disputes. The real estate group acts on residential, commercial and condominium purchases and sales, mortgage refinancing, survivorship applications and title transfers. Its litigation page describes civil disputes from a demand letter through negotiation, mediation and trial, including shareholder and partnership conflicts, failed closings and deposit disputes. Team member Avinash Kaur is also named.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kh-dunkley-law-group-calgary','KH/Dunkley Law Group','Calgary','AB','ab-calgary',0,4.7,224,51.0810737,-114.013771,'{"name":"KH/Dunkley Law Group","city":"Calgary","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"ab-calgary","province":"AB","lat":51.0810737,"lng":-114.013771,"address":"1915 32 Ave NE, Calgary, AB T2E 6R6","phone":"+15873234155","rating":4.7,"count":224,"slug":"kh-dunkley-law-group-calgary","mapsUrl":"https://www.google.com/maps/search/KH%2FDunkley+Law+Group+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1915+32+Ave+NE%2C+Calgary%2C+AB+T2E+6R6","website":"https://www.khlawgroup.com","blurb":"Real Estate in Calgary. Rated 4.7 from 224 Google reviews.","type":"logo","src":"images/logos/kh-dunkley-law-group-calgary.png"}',NULL,'KH | Dunkley Law Group is a Calgary firm handling residential and commercial real estate, wills and estates, and corporate law.

The firm says it was formed in 2012 through the merger of KH Law and Michael C. Dunkley Law Offices. It operates from three locations: a main office in northeast Calgary, a central office near Bonnybrook and Inglewood, and a south office near Shawnessy and Sundance. It states that clients always meet with a lawyer, offers flat-rate pricing on nearly all services, and holds evening signing appointments. Its general services include notary public work, commissioning of oaths, powers of attorney, independent legal advice certificates and travel consent letters.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('cangaly-montreal','Cangaly','Montreal','QC','qc-montreal',0,5,208,45.4960199,-73.5765625,'{"name":"Cangaly","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.4960199,"lng":-73.5765625,"address":"1440 Sainte-Catherine St. West Ste 404, Montreal, Quebec H3G 1R8","phone":"+15145839566","rating":5,"count":208,"slug":"cangaly-montreal","mapsUrl":"https://www.google.com/maps/search/Cangaly+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1440+Sainte-Catherine+St.+West+Ste+404%2C+Montreal%2C+Quebec+H3G+1R8","website":"https://www.jialicanada.com","blurb":"Immigration in Montreal. Rated 5.0 from 208 Google reviews.","type":"logo","src":"images/logos/cangaly-montreal.png"}',NULL,'Cangaly is a Montreal immigration consulting company assisting with Quebec PEQ, federal Express Entry, provincial nomination and study permit applications.

Its website, written in Chinese, says the company is registered to handle entry and exit affairs, immigration and study abroad, employment placement, and education training. The consultant it presents holds a bachelor''s degree in applied linguistics and a master''s in information processing and analysis, previously worked at the China Scholarship Council, and can represent clients before immigration authorities, the border agency and the Immigration and Refugee Board on appeal. The firm also says it carries one million dollars of insurance each year and has teams in Canada and China.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mcintosh-and-zayed-s-r-l-winnipeg','McIntosh & Zayed s.r.l.','Winnipeg','MB','mb-winnipeg',0,5,205,49.8791528,-97.1179486,'{"name":"McIntosh & Zayed s.r.l.","city":"Winnipeg","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"mb-winnipeg","province":"MB","lat":49.8791528,"lng":-97.1179486,"address":"221B Kitson St, Winnipeg, MB R2H 0Z4","phone":"+12046662503","rating":5,"count":205,"slug":"mcintosh-and-zayed-s-r-l-winnipeg","mapsUrl":"https://www.google.com/maps/search/McIntosh+%26+Zayed+s.r.l.+Winnipeg+Manitoba","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=221B+Kitson+St%2C+Winnipeg%2C+MB+R2H+0Z4","website":"https://www.mcintoshzayed.ca","blurb":"Personal Injury in Winnipeg. Rated 5.0 from 205 Google reviews.","type":"logo","src":"images/logos/mcintosh-and-zayed-s-r-l-winnipeg.png"}',NULL,'In Winnipeg, McIntosh & Zayed s.r.l., a local firm, handles immigration, real estate, business and wills and estates matters.

Its immigration work covers refugee matters, applications and appeals, and the real estate group acts on purchases, sales and developments, walking Manitoba buyers through the costs and paperwork. The business group deals with corporations, contracts and litigation, while the wills and estates group handles wills, powers of attorney and probate. The firm says it uses custom technology to help clients put their testamentary documents in order, and it also offers notary public appointments. Its site is organized around the idea of bringing peace of mind.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('maclean-law-vancouver','MacLean Law','Vancouver','BC','bc-vancouver',0,4.6,222,49.2876342,-123.1175718,'{"name":"MacLean Law","city":"Vancouver","featured":false,"tags":["Family Law","Wills & Estates"],"caseTypes":["family","wills"],"region":"bc-vancouver","province":"BC","lat":49.2876342,"lng":-123.1175718,"address":"1021 W Hastings St #2900, Vancouver, BC V6E 0C3","phone":"+16046029000","rating":4.6,"count":222,"slug":"maclean-law-vancouver","mapsUrl":"https://www.google.com/maps/search/MacLean+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1021+W+Hastings+St+%232900%2C+Vancouver%2C+BC+V6E+0C3","website":"https://macleanfamilylaw.ca","blurb":"Family Law / Wills & Estates in Vancouver. Rated 4.6 from 222 Google reviews.","type":"logo","src":"images/logos/maclean-law-vancouver.webp"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','MacLean Law is a Vancouver family law firm handling parenting, guardianship, high net worth divorce and estate litigation matters.

The firm''s data gives 1983 as its founding date, and its site speaks of more than 43 years of practice. It lists offices in Vancouver, West Vancouver, Victoria, Surrey, Kelowna and Calgary. Its stated areas include child parenting time, guardianship and fertility, adult guardianship, power of attorney abuse and undue influence, the division of family trusts and family businesses, and foreign child custody orders in British Columbia. Lorne MacLean, KC, Fraser MacLean, Sophie Bartholomew and Rana Yavari are named as co-authors of the Chambers and Partners Family Law Guide for Canada.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('cougle-co-real-estate-business-law-calgary','Cougle + Co. │ Real Estate + Business Law','Calgary','AB','ab-calgary',0,4.9,204,51.0375842,-114.1181314,'{"name":"Cougle + Co. │ Real Estate + Business Law","city":"Calgary","featured":false,"tags":["Real Estate","Business Law"],"caseTypes":["realestate","business"],"region":"ab-calgary","province":"AB","lat":51.0375842,"lng":-114.1181314,"address":"2505 17 Ave SW Unit 220, Calgary, AB T3E 7V3","phone":"+14032499000","rating":4.9,"count":204,"slug":"cougle-co-real-estate-business-law-calgary","mapsUrl":"https://www.google.com/maps/search/Cougle+%2B+Co.+%E2%94%82+Real+Estate+%2B+Business+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2505+17+Ave+SW+Unit+220%2C+Calgary%2C+AB+T3E+7V3","website":"https://www.cougle.co","blurb":"Real Estate / Business Law in Calgary. Rated 4.9 from 204 Google reviews.","type":"logo","src":"images/logos/cougle-co-real-estate-business-law-calgary.png"}',NULL,'Cougle + Co., a Calgary firm, limits its practice to two areas, real estate conveyancing and business law.

The lawyers say they chose to know a lot about a few things rather than a little about many, and describe the work as helping people reach their goals. Their site names honesty, authenticity and integrity as values and presents the team as forward-thinking. The firm also makes a notable billing promise: if it fails to meet its service and value commitments, it invites the client to adjust the bill to what the client believes is fair. Its pages are organized around legal services, its approach and the people behind the firm.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('de-krupe-law-north-york','De Krupe Law','North York','ON','toronto',0,4.9,200,43.7520036,-79.4653329,'{"name":"De Krupe Law","city":"North York","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.7520036,"lng":-79.4653329,"address":"20 De Boers Dr Ste 300, North York, ON M3J 0H1","phone":"+14169019344","rating":4.9,"count":200,"slug":"de-krupe-law-north-york","mapsUrl":"https://www.google.com/maps/search/De+Krupe+Law+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=20+De+Boers+Dr+Ste+300%2C+North+York%2C+ON+M3J+0H1","website":"https://dekrupelaw.ca","blurb":"Real Estate in North York. Rated 4.9 from 200 Google reviews.","type":"logo","src":"images/logos/de-krupe-law-north-york.png"}',NULL,'De Krupe Law is a North York firm handling real estate closings, mortgage refinancing, wills and estates, corporate, family and litigation matters.

The firm says it has offices in Toronto, Newmarket, Vaughan and Barrie, and its structured data adds Mississauga as an area served. It offers flat-rate pricing, after-hours and weekend appointments, and in-person meetings Monday to Saturday as well as online meetings. The site cites more than 1,000 cases and 3,000 transactions, and states that clients work directly with their assigned lawyer. Team members named include Stan Aranush de Krupe, Eva Aranush de Krupe, Anthony Galasso and Julieta Daniel.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ronalee-carey-law-ottawa','Ronalee Carey Law','Ottawa','ON','eastern',0,4.8,203,45.428703,-75.614663,'{"name":"Ronalee Carey Law","city":"Ottawa","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"eastern","province":"ON","lat":45.428703,"lng":-75.614663,"address":"TCC Canada - The Blair Centre, 1900 City Park Dr 3rd Floor, Suite 382, Ottawa, ON K1J 1A3","phone":"+16136991765","rating":4.8,"count":203,"slug":"ronalee-carey-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Ronalee+Carey+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=TCC+Canada+-+The+Blair+Centre%2C+1900+City+Park+Dr+3rd+Floor%2C+Suite+382%2C+Ottawa%2C+ON+K1J+1A3","website":"https://ronaleecareylaw.ca","blurb":"Immigration in Ottawa. Rated 4.8 from 203 Google reviews.","type":"logo","src":"images/logos/ronalee-carey-law-ottawa.png"}',NULL,'Ronalee Carey Law is an Ottawa immigration law practice handling visas, permanent residence, refugee claims and citizenship.

Ronalee Carey has practised law in Ontario since 1998 and has worked only in immigration since 2008. The small team handles visitor visas, study permits, post-graduate and open work permits, and family sponsorship, but does not assist with employer-specific work permits or LMIA applications, and does not serve clients in French. Ronalee belongs to the Canadian Bar Association''s immigration section, the Ontario Bar Association''s citizenship and immigration section, and two refugee lawyers'' associations. The staff page also introduces its office dogs, Milo and Indy.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('michael-dibua-law-prof-corp-brampton','Michael Dibua Law Prof Corp.','Brampton','ON','peel-halton',0,4.8,203,43.7029307,-79.7421041,'{"name":"Michael Dibua Law Prof Corp.","city":"Brampton","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"peel-halton","province":"ON","lat":43.7029307,"lng":-79.7421041,"address":"338 Queen St E #207, Brampton, ON L6V 1C4","phone":"+19052163307","rating":4.8,"count":203,"slug":"michael-dibua-law-prof-corp-brampton","mapsUrl":"https://www.google.com/maps/search/Michael+Dibua+Law+Prof+Corp.+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=338+Queen+St+E+%23207%2C+Brampton%2C+ON+L6V+1C4","website":"https://michaeldibualaw.ca","blurb":"Family Law in Brampton. Rated 4.8 from 203 Google reviews.","type":"logo","src":"images/logos/michael-dibua-law-prof-corp-brampton.png"}',NULL,'Michael Dibua Law Prof Corp., based in Brampton, handles family law and civil litigation, including divorce, separation and support.

Michael Dibua obtained his law degree at Obafemi Awolowo University in Nigeria in 1997, was called to the Nigerian Bar in 1999 and completed a master''s degree in law at Cardiff University in 2004. Before opening the practice he worked as in-house counsel in banking, handling debt collection, litigation and risk matters. His family work covers family property, equalization of net family property, the matrimonial home, decision-making responsibility and parenting time. The site says he is upfront with clients about their chances in order to manage expectations.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kahlon-law-mississauga','Kahlon Law','Mississauga','ON','peel-halton',0,5,185,43.6586469,-79.6528355,'{"name":"Kahlon Law","city":"Mississauga","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.6586469,"lng":-79.6528355,"address":"6200 Dixie Rd #223, Mississauga, ON L5T 2E1","phone":"+14165028555","rating":5,"count":185,"slug":"kahlon-law-mississauga","mapsUrl":"https://www.google.com/maps/search/Kahlon+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=6200+Dixie+Rd+%23223%2C+Mississauga%2C+ON+L5T+2E1","website":"https://kahlonlaw.com","blurb":"Criminal Defence in Mississauga. Rated 5.0 from 185 Google reviews.","type":"logo","src":"images/logos/kahlon-law-mississauga.webp"}',NULL,'Kahlon Law is a Mississauga criminal defence firm defending charges that include impaired operation and firearm possession.

The site says the firm has defended more than 500 criminal cases and publishes summaries of selected matters, among them a week-long trial that ended in dismissal, a preliminary inquiry that dismissed firearm charges, and Charter applications on arrest and right to counsel. Founder Antar Kahlon holds a criminal justice degree from the University of Guelph and a law degree from Windsor, worked with Windsor''s Community Legal Aid, clerked at a Michigan district court and edited a legal journal at Windsor.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ryan-edmonds-workplace-counsel-toronto','Ryan Edmonds Workplace Counsel','Toronto','ON','toronto',0,4.9,184,43.6517237,-79.3809618,'{"name":"Ryan Edmonds Workplace Counsel","city":"Toronto","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.6517237,"lng":-79.3809618,"address":"401 Bay St. Ste 1600, Toronto, ON M7A 0A6","phone":"+16473618228","rating":4.9,"count":184,"slug":"ryan-edmonds-workplace-counsel-toronto","mapsUrl":"https://www.google.com/maps/search/Ryan+Edmonds+Workplace+Counsel+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=401+Bay+St.+Ste+1600%2C+Toronto%2C+ON+M7A+0A6","website":"https://rewc-law.com","blurb":"Employment Law in Toronto. Rated 4.9 from 184 Google reviews.","type":"logo","src":"images/logos/ryan-edmonds-workplace-counsel-toronto.webp"}',NULL,'Ryan Edmonds Workplace Counsel is a Toronto employment law firm advising Ontario employees and employers on severance, contracts and workplace disputes.

The firm says Ryan Edmonds founded it to offer innovative legal solutions tailored to each client''s workplace, whether a small business, an employee in transition or a founder. For employees it lists severance package assessment and negotiation, wrongful dismissal claims, contract negotiation, workplace discrimination claims and disability accommodation. Its lawyers also act for management, which the site says gives them insight into how employers think. Its stated values are honesty, transparency and quality, with some humour added.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ambassador-law-corporation-abbotsford','Ambassador Law Corporation','Abbotsford','BC','bc-fraser',0,4.6,194,49.0492037,-122.2972713,'{"name":"Ambassador Law Corporation","city":"Abbotsford","featured":false,"tags":["Real Estate","Business Law"],"caseTypes":["realestate","business"],"region":"bc-fraser","province":"BC","lat":49.0492037,"lng":-122.2972713,"address":"33456 South Fraser Way #120, Abbotsford, BC V2S 2B5","phone":"+16048594825","rating":4.6,"count":194,"slug":"ambassador-law-corporation-abbotsford","mapsUrl":"https://www.google.com/maps/search/Ambassador+Law+Corporation+Abbotsford+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=33456+South+Fraser+Way+%23120%2C+Abbotsford%2C+BC+V2S+2B5","website":"https://ambassadorlaw.ca","blurb":"Real Estate / Business Law in Abbotsford. Rated 4.6 from 194 Google reviews.","type":"logo","src":"images/logos/ambassador-law-corporation-abbotsford.webp"}',NULL,'Ambassador Law Corporation is an Abbotsford firm handling real estate conveyancing, subdivisions, wills and estates, corporate law and notarizations.

The firm says it amalgamated with Terry Sidhu Notarial Services Inc. and serves clients throughout the Fraser Valley. Its real estate group acts on home purchases and sales and changes of mortgage lender, and its subdivision work with municipalities covers rezoning, border realignments and splitting a property into several PIDs. Notarizations include affidavits for BC registries, international documents and real estate transfers; the signer must attend in person with government photo identification. The site cites more than fifteen years in subdivisions and over twenty years overall.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ng-sidhu-law-surrey','Ng Sidhu Law','Surrey','BC','bc-fraser',0,4.7,180,49.1774275,-122.842752,'{"name":"Ng Sidhu Law","city":"Surrey","featured":false,"tags":["Personal Injury","Family Law","Criminal Defence","Wills & Estates"],"caseTypes":["injury","family","criminal","wills"],"region":"bc-fraser","province":"BC","lat":49.1774275,"lng":-122.842752,"address":"13737 96 Ave Ste 1104, Surrey, BC V3V 0C6","phone":"+16047363632","rating":4.7,"count":180,"slug":"ng-sidhu-law-surrey","mapsUrl":"https://www.google.com/maps/search/Ng+Sidhu+Law+Surrey+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=13737+96+Ave+Ste+1104%2C+Surrey%2C+BC+V3V+0C6","website":"https://ngsidhu.com","blurb":"Personal Injury / Family Law in Surrey. Rated 4.7 from 180 Google reviews.","type":"logo","src":"images/logos/ng-sidhu-law-surrey.png"}',NULL,'Ng Sidhu Law is a Surrey full-service firm handling personal injury, ICBC claims, real estate, wills and estates, criminal, family and immigration law.

The firm says it has nine offices across British Columbia and serves the Lower Mainland, listing Abbotsford, Delta, Langley, New Westminster, Port Coquitlam, Richmond and Vancouver among its areas. Services are provided in English, French, Punjabi, Hindi, Mandarin, Cantonese, Sinhalese, Tamil and Spanish. Shawn Sidhu and Zachary Ng are named on its team page, and the site highlights medical malpractice, ICBC Enhanced Care claims and a communication-first way of working on every file.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sabio-law-llp-brampton','Sabio Law LLP','Brampton','ON','peel-halton',0,4.9,172,43.6602327,-79.7222051,'{"name":"Sabio Law LLP","city":"Brampton","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.6602327,"lng":-79.7222051,"address":"201 County Ct Blvd Ste 601, Brampton, ON L6W 4L2","phone":"+19056771110","rating":4.9,"count":172,"slug":"sabio-law-llp-brampton","mapsUrl":"https://www.google.com/maps/search/Sabio+Law+LLP+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=201+County+Ct+Blvd+Ste+601%2C+Brampton%2C+ON+L6W+4L2","website":"https://sabiollp.com","blurb":"Real Estate in Brampton. Rated 4.9 from 172 Google reviews.","type":"logo","src":"images/logos/sabio-law-llp-brampton.webp"}','{"1":[["09:00","18:00"]],"2":[["09:00","18:00"]],"3":[["09:00","18:00"]],"4":[["09:00","18:00"]],"5":[["09:00","18:00"]]}','Sabio Law LLP is a Brampton firm handling real estate, business, estate and litigation matters across Ontario and the Greater Toronto Area.

The firm acts on residential and commercial real estate transactions, development work such as zoning and planning, financing, leases and joint ventures, and disputes including mortgage enforcement. Its clients include brokers, developers, investors and private lenders. Gurpreet heads the litigation practice group, which the site describes as covering complex litigation and arbitration. Sabio Law says it uses value-based pricing and favours resolution and restructuring over litigation where it can.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('md-law-group-edmonton','MD LAW GROUP','Edmonton','AB','ab-edmonton',0,4.7,179,53.5422502,-113.4878713,'{"name":"MD LAW GROUP","city":"Edmonton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-edmonton","province":"AB","lat":53.5422502,"lng":-113.4878713,"address":"10123 99 St NW #820, Edmonton, AB T5J 3H1","phone":"+15875201885","rating":4.7,"count":179,"slug":"md-law-group-edmonton","mapsUrl":"https://www.google.com/maps/search/MD+LAW+GROUP+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10123+99+St+NW+%23820%2C+Edmonton%2C+AB+T5J+3H1","website":"https://www.mdlawgroup.ca","blurb":"Criminal Defence in Edmonton. Rated 4.7 from 179 Google reviews.","type":"logo","src":"images/logos/md-law-group-edmonton.png"}',NULL,'MD Law Group is an Edmonton firm handling criminal defence, family law, civil litigation, employment and personal injury matters across Alberta.

The firm has offices in Edmonton and Calgary, with Dan Murphy listed as managing partner. Its practice areas include civil litigation, criminal defence, debt collection and domestic violence. The Calgary family law page covers divorce, child custody and support, spousal support, property division and cohabitation agreements. The site also carries articles on rights during a police encounter in Alberta, assault charges, what to expect at a criminal trial and recent legal reforms.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('avanessy-giordano-llp-north-york','Avanessy Giordano LLP','North York','ON','toronto',0,4.9,171,43.7640757,-79.487041,'{"name":"Avanessy Giordano LLP","city":"North York","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"toronto","province":"ON","lat":43.7640757,"lng":-79.487041,"address":"1275 Finch Ave W Ste 411, North York, ON M3J 0L5","phone":"+14165515492","rating":4.9,"count":171,"slug":"avanessy-giordano-llp-north-york","mapsUrl":"https://www.google.com/maps/search/Avanessy+Giordano+LLP+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1275+Finch+Ave+W+Ste+411%2C+North+York%2C+ON+M3J+0L5","website":"https://www.avagiolaw.com","blurb":"Personal Injury in North York. Rated 4.9 from 171 Google reviews.","type":"logo","src":"images/logos/avanessy-giordano-llp-north-york.png"}',NULL,'Avanessy Giordano LLP is a North York boutique personal injury firm representing injured people in Toronto and across Ontario.

The firm says it was founded in 2015 by Michael Giordano and Aline Avanessy, each with more than a decade of personal injury experience at large firms before they opened their own practice. They describe a conservative file load, regular updates for clients and a network of medical and rehabilitation practitioners. A separate page covers medical malpractice, where the site says medical professionals are kept on staff to help identify negligence and support a case through litigation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('b-kay-law-office-edmonton','B.Kay Law Office','Edmonton','AB','ab-edmonton',0,5,167,53.4945366,-113.4172195,'{"name":"B.Kay Law Office","city":"Edmonton","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"ab-edmonton","province":"AB","lat":53.4945366,"lng":-113.4172195,"address":"5737 50 St NW, Edmonton, AB T6B 3W5","phone":"+17808004050","rating":5,"count":167,"slug":"b-kay-law-office-edmonton","mapsUrl":"https://www.google.com/maps/search/B.Kay+Law+Office+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5737+50+St+NW%2C+Edmonton%2C+AB+T6B+3W5","website":"https://bkaylaw.com","blurb":"Immigration in Edmonton. Rated 5.0 from 167 Google reviews.","type":"logo","src":"images/logos/b-kay-law-office-edmonton.webp"}',NULL,'B.Kay Law Office is an Edmonton practice handling immigration law, personal injury and notary services for individuals, families and businesses.

The firm was founded by Bikramjit Singh and says it serves Edmonton''s multicultural community, as well as clients across Canada, in English, Punjabi, Hindi and Urdu. Its immigration practice lists Canadian temporary residence programs and admissibility hearings and detention matters. The notary page describes Notary Public and Commissioner for Oaths services in Edmonton and surrounding areas, including affidavits, and tells clients what to bring to an appointment.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jahanshahi-business-law-firm-north-york','Jahanshahi Business Law Firm','North York','ON','toronto',0,4.9,169,43.7238486,-79.3373096,'{"name":"Jahanshahi Business Law Firm","city":"North York","featured":false,"tags":["Business Law"],"caseTypes":["business"],"region":"toronto","province":"ON","lat":43.7238486,"lng":-79.3373096,"address":"18 Wynford Dr Ste 516, North York, ON M3C 0K8","phone":"+14165511569","rating":4.9,"count":169,"slug":"jahanshahi-business-law-firm-north-york","mapsUrl":"https://www.google.com/maps/search/Jahanshahi+Business+Law+Firm+North+York+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=18+Wynford+Dr+Ste+516%2C+North+York%2C+ON+M3C+0K8","website":"https://www.jahanlaw.ca","blurb":"Business Law in North York. Rated 4.9 from 169 Google reviews.","type":"logo","src":"images/logos/jahanshahi-business-law-firm-north-york.png"}',NULL,'Jahanshahi Business Law Firm is a North York firm advising on business purchases and sales, shareholder disputes and ongoing corporate matters.

The firm says it supports startups, entrepreneurs, franchise operations and small or mid-sized businesses, and its work also touches real estate, estate planning and tax planning. It gives ongoing counsel on contracts, corporate matters and reorganizations, and acts for buyers and sellers from structuring and due diligence through closing. For shareholder disputes it addresses ownership, management, control and the breakdown of business relationships. The site also offers general guidance on choosing a law firm, covering experience, fees and disbursements.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('siu-law-professional-corporation-richmond-hill','Siu Law Professional Corporation','Richmond Hill','ON','york-durham',0,5,161,43.8804034,-79.4399051,'{"name":"Siu Law Professional Corporation","city":"Richmond Hill","featured":false,"tags":["Real Estate","Business Law"],"caseTypes":["realestate","business"],"region":"york-durham","province":"ON","lat":43.8804034,"lng":-79.4399051,"address":"10376 Yonge St #305, Richmond Hill, ON L4C 3B8","phone":"+19057377999","rating":5,"count":161,"slug":"siu-law-professional-corporation-richmond-hill","mapsUrl":"https://www.google.com/maps/search/Siu+Law+Professional+Corporation+Richmond+Hill+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10376+Yonge+St+%23305%2C+Richmond+Hill%2C+ON+L4C+3B8","website":"https://siulaw.ca","blurb":"Real Estate / Business Law in Richmond Hill. Rated 5.0 from 161 Google reviews.","type":"logo","src":"images/logos/siu-law-professional-corporation-richmond-hill.png"}',NULL,'Siu Law Professional Corporation is a Richmond Hill real estate law firm handling purchases, sales, mortgages and refinancing.

The lawyer profiled, Andrea, was called to the Ontario Bar in 2011 after graduating from Osgoode Hall Law School, and earlier spent seven years at a chartered bank. Her experience spans legal aid clinics, boutique and Bay Street firms in immigration, civil litigation, wills and estates, and real estate. Purchase services include agreements of purchase and sale, condominium status certificates, title searches and title insurance. The firm also states that it closes new construction purchases in Alberta, and lists powers of attorney, corporate work and notarizing.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('taylor-law-calgary','Taylor Law','Calgary','AB','ab-calgary',0,4.9,164,50.9893367,-114.0502489,'{"name":"Taylor Law","city":"Calgary","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"ab-calgary","province":"AB","lat":50.9893367,"lng":-114.0502489,"address":"550 71 Ave SE, Calgary, AB T2H 0S6","phone":"+14032594151","rating":4.9,"count":164,"slug":"taylor-law-calgary","mapsUrl":"https://www.google.com/maps/search/Taylor+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=550+71+Ave+SE%2C+Calgary%2C+AB+T2H+0S6","website":"https://www.tomtaylorlaw.ca","blurb":"Real Estate in Calgary. Rated 4.9 from 164 Google reviews.","type":"logo","src":"images/logos/taylor-law-calgary.jpg"}','{"1":[["08:00","16:30"]],"2":[["08:00","16:30"]],"3":[["08:00","16:30"]],"4":[["08:00","16:30"]],"5":[["08:00","16:30"]]}','Taylor Law is a Calgary boutique firm handling real estate and estate planning for vendors, purchasers, mortgagors and mortgagees.

The firm says it has served Calgarians for more than thirty-four years and describes tailored legal services with personal attention for every client. Its estate planning page lists wills, enduring powers of attorney, personal directives, trusts and the appointment of trustees. On the real estate side, it advises on purchase agreements, listing agreements, leases and mortgages. Its pages are organized under real estate law and wills and estate planning, with the office located on 71 Avenue SE.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('susan-karpa-calgary','Susan Karpa','Calgary','AB','ab-calgary',0,4.9,163,51.0433704,-114.0737209,'{"name":"Susan Karpa","city":"Calgary","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"ab-calgary","province":"AB","lat":51.0433704,"lng":-114.0737209,"address":"535 10 Ave SW Ste 201, Calgary, AB T2R 0A8","phone":"+15878887149","rating":4.9,"count":163,"slug":"susan-karpa-calgary","mapsUrl":"https://www.google.com/maps/search/Susan+Karpa+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=535+10+Ave+SW+Ste+201%2C+Calgary%2C+AB+T2R+0A8","website":"https://www.susankarpa.com","blurb":"Criminal Defence / Civil Litigation in Calgary. Rated 4.9 from 163 Google reviews.","type":"logo","src":"images/logos/susan-karpa-calgary.png"}','{"1":[["07:00","11:30"]],"2":[["07:00","11:30"]],"3":[["07:00","11:30"]],"4":[["07:00","11:30"]],"5":[["07:00","11:30"]],"6":[["07:00","11:30"]],"7":[["07:00","11:30"]]}','Susan Karpa is a Calgary criminal defence lawyer handling assault, sexual offence, drug and firearms charges for clients across Alberta.

She says she has twenty-five years of experience in criminal law and has defended more than 2,000 people. Her website lists practice areas such as assaults, threats and harassment, domestic assault, sexual assault and sexual offences, child pornography and luring offences, drug offences, and firearms and weapons offences. Each area has a page explaining the charge in plain terms, and the site includes a section of case decisions. Her structured data names Calgary, Airdrie and Cochrane among the communities served.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lawyer-up-canada-richmond-hill','Lawyer UP Canada','Richmond Hill','ON','york-durham',0,4.8,166,43.8412817,-79.3990206,'{"name":"Lawyer UP Canada","city":"Richmond Hill","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"york-durham","province":"ON","lat":43.8412817,"lng":-79.3990206,"address":"330 Hwy 7 Unit 305-C, Richmond Hill, ON L4B 3P8","phone":"+19057456180","rating":4.8,"count":166,"slug":"lawyer-up-canada-richmond-hill","mapsUrl":"https://www.google.com/maps/search/Lawyer+UP+Canada+Richmond+Hill+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=330+Hwy+7+Unit+305-C%2C+Richmond+Hill%2C+ON+L4B+3P8","website":"https://www.lawyerupcanada.ca","blurb":"Criminal Defence in Richmond Hill. Rated 4.8 from 166 Google reviews.","type":"logo","src":"images/logos/lawyer-up-canada-richmond-hill.png"}',NULL,'Lawyer UP Canada is a Richmond Hill criminal defence firm representing people charged with offences such as fraud, theft and assault in Ontario.

The firm describes providing full criminal defence services to people charged with criminal offences who also face related legal consequences. Its website explains each charge in plain language, including fraud, theft, assault, robbery, mischief, failure to stop or remain at the scene of an accident, and harassment and uttering threats. The office is located on Highway 7 in Richmond Hill.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('joseph-a-nagy-injury-law-edmonton','Joseph A. Nagy Injury Law','Edmonton','AB','ab-edmonton',0,4.8,165,53.5408201,-113.4481947,'{"name":"Joseph A. Nagy Injury Law","city":"Edmonton","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"ab-edmonton","province":"AB","lat":53.5408201,"lng":-113.4481947,"address":"7815 101 Ave NW, Edmonton, AB T6A 0K1","phone":"+17807604878","rating":4.8,"count":165,"slug":"joseph-a-nagy-injury-law-edmonton","mapsUrl":"https://www.google.com/maps/search/Joseph+A.+Nagy+Injury+Law+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7815+101+Ave+NW%2C+Edmonton%2C+AB+T6A+0K1","website":"https://josephanagy.com","blurb":"Personal Injury / Civil Litigation in Edmonton. Rated 4.8 from 165 Google reviews.","type":"logo","src":"images/logos/joseph-a-nagy-injury-law-edmonton.png"}',NULL,'This Edmonton injury firm handles motor vehicle accident and personal injury cases for people in central and northern Alberta. Its site covers car, truck, motorcycle and bicycle collisions.

Joseph A. Nagy Injury Law says each of its injury lawyers has more than 20 years of experience and that a senior lawyer keeps a file from the first meeting through resolution rather than passing it to a junior. The team page names Joseph A. Nagy and Howard Poon. Fees are contingency based, and the site states that clients owe no legal fees until a case is resolved. It also publishes a page on Alberta''s switch to no-fault auto insurance, branded Care-First and set for January 1, 2027, and notes that the firm has opposed no-fault coverage and supports FAIR Alberta.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dale-streiman-law-brampton','Dale Streiman Law','Brampton','ON','peel-halton',0,4.7,167,43.697506,-79.775025,'{"name":"Dale Streiman Law","city":"Brampton","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.697506,"lng":-79.775025,"address":"480 Main St N, Brampton, ON L6V 3E3","phone":"+19054557300","rating":4.7,"count":167,"slug":"dale-streiman-law-brampton","mapsUrl":"https://www.google.com/maps/search/Dale+Streiman+Law+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=480+Main+St+N%2C+Brampton%2C+ON+L6V+3E3","website":"https://www.dalestreimanlaw.com","blurb":"Real Estate in Brampton. Rated 4.7 from 167 Google reviews.","type":"logo","src":"images/logos/dale-streiman-law-brampton.webp"}',NULL,'Dale Streiman Law is a full-service Brampton firm handling family law, real estate, business law, and wills and estates for individuals and companies. The practice operates as Dale Streiman Law LLP, or DS Law.

Its lawyers draw on years of experience in the GTA, and the site describes a team of nine lawyers supported by law clerks. Appointments are also offered in Toronto, Vaughan, Milton, Oakville, Burlington and Hamilton. The firm''s stated motto is No Nonsense Law, and it frames its guiding test as what a lawyer would tell a sister or brother to do. Elliott Dale and Fred Streiman are among the lawyers named, and the firm says it keeps an eye on costs as well as outcomes.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('erikson-law-firm-ottawa','Erikson Law Firm','Ottawa','ON','eastern',0,5,155,45.331122,-75.703749,'{"name":"Erikson Law Firm","city":"Ottawa","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"eastern","province":"ON","lat":45.331122,"lng":-75.703749,"address":"18 Deakin St Unit 105, Nepean, ON K2E 8B7","phone":"+16136925885","rating":5,"count":155,"slug":"erikson-law-firm-ottawa","mapsUrl":"https://www.google.com/maps/search/Erikson+Law+Firm+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=18+Deakin+St+Unit+105%2C+Nepean%2C+ON+K2E+8B7","website":"https://eriksonlaw.ca","blurb":"Real Estate in Ottawa. Rated 5.0 from 155 Google reviews.","type":"logo","src":"images/logos/erikson-law-firm-ottawa.png"}',NULL,'Erikson Law Firm in Ottawa handles real estate, tax and family law matters, with flat-fee billing for most of its legal services.

Valentin Erikson owns the firm. He studied at Carleton University and the University of Ottawa, clerked at the Tax Court of Canada and was called to the Ontario bar in 2009. The practice serves clients in Ottawa and across Ontario from an office in Nepean, and its site also mentions estate planning and a section on same-sex legal issues. Notary services include administering oaths, certifying true copies, consent letters for children travelling abroad, passport declarations, and authenticating documents in English, French, Russian, Estonian and Lithuanian.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('west-legal-calgary','West Legal','Calgary','AB','ab-calgary',0,4.7,163,50.9638818,-114.0734118,'{"name":"West Legal","city":"Calgary","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"ab-calgary","province":"AB","lat":50.9638818,"lng":-114.0734118,"address":"10201 Southport Rd SW #1200, Calgary, AB T2W 4X9","phone":"+14037230175","rating":4.7,"count":163,"slug":"west-legal-calgary","mapsUrl":"https://www.google.com/maps/search/West+Legal+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10201+Southport+Rd+SW+%231200%2C+Calgary%2C+AB+T2W+4X9","website":"https://www.west-legal.ca","blurb":"Wills & Estates in Calgary. Rated 4.7 from 163 Google reviews.","type":"logo","src":"images/logos/west-legal-calgary.png"}','{"1":[["08:30","16:30"]],"2":[["08:30","16:30"]],"3":[["08:30","16:30"]],"4":[["08:30","16:30"]],"5":[["08:30","16:30"]]}','West Legal is a Calgary team of lawyers handling wills and estates, probate, family, employment and residential real estate matters.

The firm describes a People First approach and says it serves Calgary, Okotoks and Airdrie. David West practises in real estate, wills and probate, Kim Nutz in employment law for both employees and employers, Machelle Luiters in family law and Kelsey Morrison in wills and estate planning. Adrienne O''Reilly handles corporate, securities, mergers and acquisitions and commercial work. West Legal says it offers flat-rate fees wherever possible, including for wills, enduring powers of attorney, personal directives, probate and residential real estate transactions.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('edmonton-criminal-lawyer-ziv-edmonton','Edmonton Criminal Lawyer Ziv','Edmonton','AB','ab-edmonton',0,4.8,151,53.5424186,-113.4909475,'{"name":"Edmonton Criminal Lawyer Ziv","city":"Edmonton","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"ab-edmonton","province":"AB","lat":53.5424186,"lng":-113.4909475,"address":"10150 100 St NW Unit 700, Edmonton, AB T5J 0P6","phone":"+17806287728","rating":4.8,"count":151,"slug":"edmonton-criminal-lawyer-ziv-edmonton","mapsUrl":"https://www.google.com/maps/search/Edmonton+Criminal+Lawyer+Ziv+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10150+100+St+NW+Unit+700%2C+Edmonton%2C+AB+T5J+0P6","website":"https://edmontoncriminallawyerziv.com","blurb":"Criminal Defence / Civil Litigation in Edmonton. Rated 4.8 from 151 Google reviews.","type":"logo","src":"images/logos/edmonton-criminal-lawyer-ziv-edmonton.png"}',NULL,'Edmonton Criminal Lawyer Ziv is the Ziv Law Group, a criminal defence practice handling assault, drug, theft, fraud and impaired driving charges in Edmonton.

Rory Ziv has practised criminal defence since his admission to the Alberta Bar in 2005 and founded the firm in Edmonton in 2011. His practice includes homicide, sexual assault, impaired driving, major fraud and drug offences. The site sorts its work into financial offences, assault, possession and trafficking, theft, serious offences and driving offences, and says it serves Edmonton along with Fort Saskatchewan, Leduc, Sherwood Park, Spruce Grove, St. Albert and Drayton Valley.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('silver-immigration-montreal','Silver Immigration','Montreal','QC','qc-montreal',0,4.9,145,45.4977899,-73.5673787,'{"name":"Silver Immigration","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.4977899,"lng":-73.5673787,"address":"1010 Rue De la Gauchetière O bureau 200, Montreal, Quebec H3B 2N2","phone":"+18887994769","rating":4.9,"count":145,"slug":"silver-immigration-montreal","mapsUrl":"https://www.google.com/maps/search/Silver+Immigration+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1010+Rue+De+la+Gaucheti%C3%A8re+O+bureau+200%2C+Montreal%2C+Quebec+H3B+2N2","website":"https://silverimmigration.com","blurb":"Immigration in Montreal. Rated 4.9 from 145 Google reviews.","type":"logo","src":"images/logos/silver-immigration-montreal.png"}',NULL,'Silver Immigration is a Montreal firm advising Canadians on US immigration, including work visas, green cards, student visas and entry waivers.

Matthew Silver, a Montreal-based US immigration attorney, founded the firm, which says it has served Canadians since 2019 and presents itself as serving both Montreal and Ottawa. Its service pages cover E-2 and E-1 treaty visas, EB-5 investor green cards, employment-based permanent residence, TN and L-1 work visas, O-1 visas, B-1/B-2 visitor travel, F-1 student visas, OPT after graduation, and Form I-192 waivers for people with a criminal record or DUI. The office is on rue de la Gauchetière Ouest.','dynamic','live',NULL);
