INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lamont-law-hamilton','Lamont Law','Hamilton','ON','hamilton-niagara',0,4.8,93,43.2504928,-79.8740293,'{"name":"Lamont Law","city":"Hamilton","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"hamilton-niagara","province":"ON","lat":43.2504928,"lng":-79.8740293,"address":"44 Charlton Ave W, Hamilton, ON L8P 2C1","phone":"+19055296668","rating":4.8,"count":93,"slug":"lamont-law-hamilton","mapsUrl":"https://www.google.com/maps/search/Lamont+Law+Hamilton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=44+Charlton+Ave+W%2C+Hamilton%2C+ON+L8P+2C1","website":"https://lamontlaw.ca","blurb":"Personal Injury in Hamilton. Rated 4.8 from 93 Google reviews.","type":"logo","src":"images/logos/lamont-law-hamilton.png"}',NULL,'Lamont Law is a Hamilton personal injury firm that focuses on serious and catastrophic injuries, accident benefits and long-term disability denials.

The site lists motor vehicle accidents, dog attacks, slip and falls, medical and nursing home negligence, wrongful death, brain injuries and spinal cord injuries among its cases for Hamilton and the GTA, and says it only takes catastrophic injury matters with an estimated value above $50,000. Erica Lamont, who was born in Hamilton, studied at the University of Waterloo and the University of Calgary and was admitted to the Law Society of Ontario in 2014. She is joined by lawyer Braden Adsett and paralegals Carrie Stewart and Phil Vivian.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ndiaye-enokou-avocats-gatineau','Ndiaye Enokou Avocats','Gatineau','QC','qc-outaouais',0,4.6,97,45.4257626,-75.7169565,'{"name":"Ndiaye Enokou Avocats","city":"Gatineau","featured":false,"tags":["Immigration","Criminal Defence","Family Law"],"caseTypes":["immigration","criminal","family"],"region":"qc-outaouais","province":"QC","lat":45.4257626,"lng":-75.7169565,"address":"129 Prom. du Portage Bur 210, Gatineau, QC J8X 2K2","phone":"+18196640738","rating":4.6,"count":97,"slug":"ndiaye-enokou-avocats-gatineau","mapsUrl":"https://www.google.com/maps/search/Ndiaye+Enokou+Avocats+Gatineau+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=129+Prom.+du+Portage+Bur+210%2C+Gatineau%2C+QC+J8X+2K2","website":"https://www.neavocats.com","blurb":"Immigration / Criminal Defence in Gatineau. Rated 4.6 from 97 Google reviews.","type":"logo","src":"images/logos/ndiaye-enokou-avocats-gatineau.png"}',NULL,'Ndiaye Enokou Avocats is a Gatineau firm handling immigration, criminal, family and business law in French and English.

The firm, which also uses the name N&E Avocats, operates three offices in Quebec, in Gatineau, Trois-Rivières and Sherbrooke. Its immigration page covers temporary and permanent residence, study and work permits, family sponsorship and asylum applications for individuals, families, students and professionals who want to settle in Canada or bring relatives. The site says the firm represents clients before the competent courts and presents its approach as tailored to each situation.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('manbir-sodhi-brampton','Manbir Sodhi','Brampton','ON','peel-halton',0,4.8,88,43.6852731,-79.7615335,'{"name":"Manbir Sodhi","city":"Brampton","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.6852731,"lng":-79.7615335,"address":"9 George St N Unit 102, Brampton, ON L6V 1E9","phone":"+19054572546","rating":4.8,"count":88,"slug":"manbir-sodhi-brampton","mapsUrl":"https://www.google.com/maps/search/Manbir+Sodhi+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=9+George+St+N+Unit+102%2C+Brampton%2C+ON+L6V+1E9","website":"https://www.manbirsodhilaw.com","blurb":"Criminal Defence in Brampton. Rated 4.8 from 88 Google reviews.","type":"logo","src":"images/logos/manbir-sodhi-brampton.png"}',NULL,'Manbir Sodhi is a Brampton criminal defence lawyer who represents people charged with offences, including impaired driving.

His site says he practises exclusively in criminal law and offers representation at each stage, from a police request to turn oneself in through arrest, bail hearings, pre-trial and trial. Listed practice areas include domestic and sexual assault, weapons, drug and criminal driving offences, traffic and bylaw matters, search warrants, theft, fraud and shoplifting, youth criminal offences and professional disciplinary proceedings. The office is on George Street North in Brampton and the firm serves clients across the GTA and Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('harvey-katz-law-office-hamilton','Harvey Katz Law Office','Hamilton','ON','hamilton-niagara',0,4.6,91,43.2586526,-79.877649,'{"name":"Harvey Katz Law Office","city":"Hamilton","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"hamilton-niagara","province":"ON","lat":43.2586526,"lng":-79.877649,"address":"14 Hess St S, Hamilton, ON L8P 3M9","phone":"+19055231442","rating":4.6,"count":91,"slug":"harvey-katz-law-office-hamilton","mapsUrl":"https://www.google.com/maps/search/Harvey+Katz+Law+Office+Hamilton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=14+Hess+St+S%2C+Hamilton%2C+ON+L8P+3M9","website":"https://www.harveykatzlaw.ca","blurb":"Personal Injury in Hamilton. Rated 4.6 from 91 Google reviews.","type":"logo","src":"images/logos/harvey-katz-law-office-hamilton.png"}',NULL,'Harvey Katz Law Office is a Hamilton firm handling personal injury, civil litigation, wills and estates, and real estate matters.

The site says the firm has represented the Hamilton community for over 45 years and has a team of four lawyers: partners Harvey Katz and Eli Jakubovic, plus Michael Bishop and Bianca Zimperi. Harvey Katz was born and raised in the Hamilton area. Its personal injury work includes accident benefits and disability matters, civil litigation covers property disputes, contract disputes and debt collection, and estates work spans estate planning, probate administration, trusts and guardianships.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mrk-law-professional-corporation-mississauga','MRK Law Professional Corporation','Mississauga','ON','peel-halton',0,4.9,85,43.5973571,-79.759854,'{"name":"MRK Law Professional Corporation","city":"Mississauga","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"peel-halton","province":"ON","lat":43.5973571,"lng":-79.759854,"address":"6981 Millcreek Dr #44, Mississauga, ON L5N 6B8","phone":"+19058261326","rating":4.9,"count":85,"slug":"mrk-law-professional-corporation-mississauga","mapsUrl":"https://www.google.com/maps/search/MRK+Law+Professional+Corporation+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=6981+Millcreek+Dr+%2344%2C+Mississauga%2C+ON+L5N+6B8","website":"https://www.mrklaw.ca","blurb":"Criminal Defence / Civil Litigation in Mississauga. Rated 4.9 from 85 Google reviews.","type":"logo","src":"images/logos/mrk-law-professional-corporation-mississauga.jpg"}',NULL,'MRK Law Professional Corporation is a Mississauga boutique firm covering criminal defence, civil litigation, solicitor services and family law.

Mina R. Khalil is the lawyer and principal, and the site describes the firm as rooted in Peel and Halton Region while serving clients across Ontario, including Brampton, Milton and Oakville. Civil work includes employment disputes, wrongful and constructive dismissal and mediation. Solicitor services cover commercial leases, partnership, joint venture and shareholder agreements, and employment or contractor agreements, while family work includes marriage contracts. The firm says it accepts legal aid certificates for most criminal matters.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lama-law-real-estate-lawyer-oakville','Lama Law Real Estate Lawyer','Oakville','ON','peel-halton',0,5,83,43.4445084,-79.6906544,'{"name":"Lama Law Real Estate Lawyer","city":"Oakville","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"peel-halton","province":"ON","lat":43.4445084,"lng":-79.6906544,"address":"209 Speers Rd Unit 8, Oakville, ON L6K 0H5","phone":"+19053373433","rating":5,"count":83,"slug":"lama-law-real-estate-lawyer-oakville","mapsUrl":"https://www.google.com/maps/search/Lama+Law+Real+Estate+Lawyer+Oakville+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=209+Speers+Rd+Unit+8%2C+Oakville%2C+ON+L6K+0H5","website":"https://realestatelawyerontario.ca","blurb":"Real Estate / Wills & Estates in Oakville. Rated 5.0 from 83 Google reviews.","type":"logo","src":"images/logos/lama-law-real-estate-lawyer-oakville.png"}',NULL,'Lama Law Real Estate Lawyer is an Oakville firm helping clients buy, sell and refinance homes across the Greater Toronto Area.

Pav Lama earned a bachelor''s degree at York University and a law degree at the University of Birmingham in the UK, and was called to the Ontario bar in 2016. The site also lists corporate law, commercial law, notary services, and wills and powers of attorney. The page title refers to fixed fee closings, and the office is on Speers Road in Oakville.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('rja-law-edmonton','RJA Law','Edmonton','AB','ab-edmonton',0,4.9,84,53.542172,-113.4879109,'{"name":"RJA Law","city":"Edmonton","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"ab-edmonton","province":"AB","lat":53.542172,"lng":-113.4879109,"address":"Sun Life Place, 2140, 10123 99 St NW, Edmonton, AB T5J 3H1","phone":"+17804555820","rating":4.9,"count":84,"slug":"rja-law-edmonton","mapsUrl":"https://www.google.com/maps/search/RJA+Law+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=Sun+Life+Place%2C+2140%2C+10123+99+St+NW%2C+Edmonton%2C+AB+T5J+3H1","website":"https://www.rjalaw.ca","blurb":"Immigration in Edmonton. Rated 4.9 from 84 Google reviews.","type":"logo","src":"images/logos/rja-law-edmonton.png"}',NULL,'RJA Law is an Edmonton immigration practice handling appeals, refugee matters, work and visit permits and permanent residence applications.

The site describes decades of exclusive focus on immigration and refugee law. Its work includes entry for tourists, business visitors and workers, rehabilitation applications and temporary resident permits for criminal inadmissibility, provincial nominee programs, business immigration, Express Entry, spousal and common-law sponsorship, and family class applications. The team can communicate in English, French, Mandarin, Punjabi, Hindi and Spanish, and the office is in Sun Life Place.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('alam-real-estate-law-mississauga','Alam Real Estate Law','Mississauga','ON','peel-halton',0,5,82,43.6363554,-79.6225317,'{"name":"Alam Real Estate Law","city":"Mississauga","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"peel-halton","province":"ON","lat":43.6363554,"lng":-79.6225317,"address":"5100 Dixie Rd, Mississauga, ON L4W 1C9","phone":"+16479785565","rating":5,"count":82,"slug":"alam-real-estate-law-mississauga","mapsUrl":"https://www.google.com/maps/search/Alam+Real+Estate+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5100+Dixie+Rd%2C+Mississauga%2C+ON+L4W+1C9","website":"https://alamrealestatelaw.com","blurb":"Real Estate / Wills & Estates in Mississauga. Rated 5.0 from 82 Google reviews.","type":"logo","src":"images/logos/alam-real-estate-law-mississauga.jpg"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Alam Real Estate Law is a Mississauga firm handling property purchases, sales, refinancing and real estate litigation in the GTA and Halton.

Principal lawyer Jawaid Alam has degrees in commerce, economics and finance, business management and law, holds Ontario accreditation of his law degree through the National Committee of Accreditation, and speaks English, Hindi and Urdu. The firm also lists construction litigation, registering and removing liens, commercial property development litigation, and examination of agreements of purchase and sale and mortgage agreements. It serves residential and commercial clients across Mississauga and the surrounding communities.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jsb-calgary-employment-law-calgary','JSB Calgary Employment Law','Calgary','AB','ab-calgary',0,4.6,89,51.0498788,-114.07204,'{"name":"JSB Calgary Employment Law","city":"Calgary","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"ab-calgary","province":"AB","lat":51.0498788,"lng":-114.07204,"address":"500 4 Ave SW #2500, Calgary, AB T2P 2V6","phone":"+14036205400","rating":4.6,"count":89,"slug":"jsb-calgary-employment-law-calgary","mapsUrl":"https://www.google.com/maps/search/JSB+Calgary+Employment+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=500+4+Ave+SW+%232500%2C+Calgary%2C+AB+T2P+2V6","website":"https://jsblaw.ca","blurb":"Employment Law in Calgary. Rated 4.6 from 89 Google reviews.","type":"logo","src":"images/logos/jsb-calgary-employment-law-calgary.webp"}',NULL,'JSB Calgary Employment Law is a Calgary firm handling terminations, severance packages and constructive dismissal for employees and executives.

According to its website, the firm mainly acts for people whose employment has ended, whether with or without cause, and also works with employers on employment agreements, workplace investigations, workplace conflict and employment standards compliance. Its listed services extend to human rights complaints, discrimination and harassment, disability, maternity and other job-protected leaves, layoffs, independent contractor classification, and non-competition and non-solicitation covenants. The firm says most of its files settle out of court, and its office is on 4 Avenue SW.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jk-law-calgary','JK Law','Calgary','AB','ab-calgary',0,5,81,50.9866545,-114.0702412,'{"name":"JK Law","city":"Calgary","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"ab-calgary","province":"AB","lat":50.9866545,"lng":-114.0702412,"address":"7500 Macleod Trl SE Ste 207, Calgary, AB T2H 0L9","phone":"+14034549864","rating":5,"count":81,"slug":"jk-law-calgary","mapsUrl":"https://www.google.com/maps/search/JK+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7500+Macleod+Trl+SE+Ste+207%2C+Calgary%2C+AB+T2H+0L9","website":"https://www.jklawoffice.ca","blurb":"Real Estate in Calgary. Rated 5.0 from 81 Google reviews.","type":"logo","src":"images/logos/jk-law-calgary.webp"}',NULL,'JK Law is a Calgary firm offering real estate, corporate and commercial, wills and estates, immigration, personal injury and child welfare legal services.

The firm says its lawyers have more than three decades of combined experience serving clients in Canada and abroad, and that it acts for people in Calgary and surrounding areas. Its site lists Jide Kupoluyi and Ola Ogbonna among the team. On real estate it describes residential and commercial purchases and sales, while its business practice is aimed at owners and entrepreneurs, whom the lawyers say they understand because they run businesses themselves. Immigration work covers temporary visas, permanent residence and citizenship, and the office also offers notary public and commissioner for oaths services.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kirk-law-office-ottawa','Kirk Law Office','Ottawa','ON','eastern',0,4.9,81,45.4121285,-75.6812148,'{"name":"Kirk Law Office","city":"Ottawa","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"eastern","province":"ON","lat":45.4121285,"lng":-75.6812148,"address":"34 Hawthorne Ave, Ottawa, ON K1S 0B1","phone":"+16132388006","rating":4.9,"count":81,"slug":"kirk-law-office-ottawa","mapsUrl":"https://www.google.com/maps/search/Kirk+Law+Office+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=34+Hawthorne+Ave%2C+Ottawa%2C+ON+K1S+0B1","website":"https://www.kirklawoffice.ca","blurb":"Real Estate in Ottawa. Rated 4.9 from 81 Google reviews.","type":"logo","src":"images/logos/kirk-law-office-ottawa.png"}',NULL,'Kirk Law Office is an Ottawa practice handling residential real estate, wills, powers of attorney and estate administration.

Team members are described as fluent in English, French, Ukrainian, Polish and Russian. On the real estate side the office acts for private lenders and for buyers and sellers of new and resale properties, including condominiums, recreational properties, vacant or development land and investment properties, and it drafts leases and agreements of purchase and sale. Leslie J. Kirk, an Ottawa native, was called to the Ontario bar in 2009 after articling with the City of Ottawa''s legal department; her work includes rent-to-own transactions, multi-unit residential sales and RRSP-funded mortgages. Iuliia Shulakewych, who holds the TEP designation, is also profiled.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('apna-law-llp-burnaby','Apna Law LLP','Burnaby','BC','bc-burnaby',0,4.7,84,49.2013947,-122.9849304,'{"name":"Apna Law LLP","city":"Burnaby","featured":false,"tags":["Family Law","Civil Litigation"],"caseTypes":["family","litigation"],"region":"bc-burnaby","province":"BC","lat":49.2013947,"lng":-122.9849304,"address":"5489 Byrne Rd Ste 272, Burnaby, BC V5J 3J1","phone":"+16043984168","rating":4.7,"count":84,"slug":"apna-law-llp-burnaby","mapsUrl":"https://www.google.com/maps/search/Apna+Law+LLP+Burnaby+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5489+Byrne+Rd+Ste+272%2C+Burnaby%2C+BC+V5J+3J1","website":"https://apnalaw.ca","blurb":"Family Law / Civil Litigation in Burnaby. Rated 4.7 from 84 Google reviews.","type":"logo","src":"images/logos/apna-law-llp-burnaby.png"}',NULL,'Apna Law LLP is a Burnaby firm of trial and appellate lawyers handling family, estate, personal injury and civil disputes.

The firm opened in 2018, serves British Columbia and Alberta, and says its lawyers have more than 40 years of combined experience inside and outside the courtroom. Its name is a Punjabi word loosely meaning ours, which the firm links to community and collaboration. The family law team named on the site includes James Gill, Amanda James, Hannah Gowans and Ingrid Lee, and its family pages explain that an appeal to the Court of Appeal is not a re-hearing of the case. The site also publishes articles, including one on international students and immigration consultants.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('the-myers-law-company-vancouver','The Myers Law Company','Vancouver','BC','bc-vancouver',0,4.9,80,49.2825871,-123.1111384,'{"name":"The Myers Law Company","city":"Vancouver","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"bc-vancouver","province":"BC","lat":49.2825871,"lng":-123.1111384,"address":"319 W Pender St, Vancouver, BC V6B 1T3","phone":"+16044169600","rating":4.9,"count":80,"slug":"the-myers-law-company-vancouver","mapsUrl":"https://www.google.com/maps/search/The+Myers+Law+Company+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=319+W+Pender+St%2C+Vancouver%2C+BC+V6B+1T3","website":"https://www.notguiltyvancouver.com","blurb":"Criminal Defence in Vancouver. Rated 4.9 from 80 Google reviews.","type":"logo","src":"images/logos/the-myers-law-company-vancouver.png"}',NULL,'The Myers Law Company is a Vancouver criminal defence firm led by Justin Myers and Zack Myers, with traffic and family matters also listed.

According to its website, the lawyers appear in Youth Court, Provincial Court, BC Supreme Court, the Court of Appeal and the Supreme Court of Canada, and can attend in Alberta, Ontario and other jurisdictions on request. Serious matters named include murder, drug importation, firearms, theft, trafficking and arson. The firm describes its approach as detail-oriented and transparent, with lawyers who often write detailed legal arguments and who collaborate on strategy and trials without raising the cost to the client. The office is on West Pender Street.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('fraese-aymont-family-lawyers-calgary-calgary','Fraese Aymont Family Lawyers Calgary','Calgary','AB','ab-calgary',0,4.9,80,51.0485035,-114.0745966,'{"name":"Fraese Aymont Family Lawyers Calgary","city":"Calgary","featured":false,"tags":["Family Law","Civil Litigation"],"caseTypes":["family","litigation"],"region":"ab-calgary","province":"AB","lat":51.0485035,"lng":-114.0745966,"address":"605 5 Ave SW #2600, Calgary, AB T2P 3H5","phone":"+14034601230","rating":4.9,"count":80,"slug":"fraese-aymont-family-lawyers-calgary-calgary","mapsUrl":"https://www.google.com/maps/search/Fraese+Aymont+Family+Lawyers+Calgary+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=605+5+Ave+SW+%232600%2C+Calgary%2C+AB+T2P+3H5","website":"https://www.calgaryfamilylaw.ca","blurb":"Family Law / Civil Litigation in Calgary. Rated 4.9 from 80 Google reviews.","type":"logo","src":"images/logos/fraese-aymont-family-lawyers-calgary-calgary.png"}',NULL,'Fraese Aymont is a boutique family law firm in Calgary handling divorce, separation, parenting, support and property division.

The firm says family law is all it does. Its downtown Calgary office serves Calgary, Airdrie, Cochrane, Okotoks and Chestermere, and its services also include family agreements such as separation and cohabitation agreements, mediation, arbitration and court proceedings. The site features Brandi Aymont and her paralegal Devonna McFarlane, and offers child support and spousal support calculators along with a guide to divorce and separation in Alberta that discusses negotiation, mediation, arbitration and court procedure.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jim-dean-law-professional-corporation-london','Jim Dean Law Professional Corporation','London','ON','southwestern',0,4.7,83,42.9806072,-81.2208589,'{"name":"Jim Dean Law Professional Corporation","city":"London","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"southwestern","province":"ON","lat":42.9806072,"lng":-81.2208589,"address":"399 Hamilton Rd, London, ON N5Z 1R8","phone":"+12266633326","rating":4.7,"count":83,"slug":"jim-dean-law-professional-corporation-london","mapsUrl":"https://www.google.com/maps/search/Jim+Dean+Law+Professional+Corporation+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=399+Hamilton+Rd%2C+London%2C+ON+N5Z+1R8","website":"https://www.jimdeanlaw.com","blurb":"Criminal Defence in London. Rated 4.7 from 83 Google reviews.","type":"logo","src":"images/logos/jim-dean-law-professional-corporation-london.png"}',NULL,'Jim Dean Law Professional Corporation is a London, Ontario firm focused on criminal law and wills and estate planning.

According to its website, Jim Dean founded the firm in 2011 after about two decades as a police officer, and it has since grown to four full-time employees. The site lists lawyers Chris Marquis and Victoria Heppenheimer and senior law clerk Tammy Courage alongside Dean, who is a barrister, solicitor and notary public. The firm is based at the Hamilton Road Legal Centre, notes after-hours availability for clients in custody, and also describes assistance to other lawyers and professionals.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('wahab-law-kitchener','Wahab Law','Kitchener','ON','waterloo-guelph',0,4.8,80,43.423714,-80.4536094,'{"name":"Wahab Law","city":"Kitchener","featured":false,"tags":["Immigration","Real Estate","Employment Law"],"caseTypes":["immigration","realestate","employment"],"region":"waterloo-guelph","province":"ON","lat":43.423714,"lng":-80.4536094,"address":"218 Woodhaven Rd, Kitchener, ON N2C 1V6","phone":"+12266861070","rating":4.8,"count":80,"slug":"wahab-law-kitchener","mapsUrl":"https://www.google.com/maps/search/Wahab+Law+Kitchener+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=218+Woodhaven+Rd%2C+Kitchener%2C+ON+N2C+1V6","website":"https://www.wahablaw.com","blurb":"Immigration / Real Estate in Kitchener. Rated 4.8 from 80 Google reviews.","type":"logo","src":"images/logos/wahab-law-kitchener.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Wahab Law is a Kitchener firm handling real estate, family, employment, wills and estate, and civil litigation matters.

The firm says it serves Kitchener, Waterloo, Cambridge, the Greater Toronto Area and surrounding regions. Khaled Wahab is the managing lawyer, with Nima Pannu listed as an associate and Richard David Christy as executive advisor. Real estate work covers buying, selling and refinancing with transparent pricing, while the family practice handles custody disputes, support calculations, asset distribution and divorce. The site also lists notary services and independent legal advice, and says clients are served throughout the Waterloo Region.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kalia-law-firm-brampton','Kalia Law Firm','Brampton','ON','peel-halton',0,4.7,81,43.750942,-79.7270575,'{"name":"Kalia Law Firm","city":"Brampton","featured":false,"tags":["Family Law","Real Estate"],"caseTypes":["family","realestate"],"region":"peel-halton","province":"ON","lat":43.750942,"lng":-79.7270575,"address":"2120 N Park Dr #213, Brampton, ON L6S 0C9","phone":"+19057900020","rating":4.7,"count":81,"slug":"kalia-law-firm-brampton","mapsUrl":"https://www.google.com/maps/search/Kalia+Law+Firm+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2120+N+Park+Dr+%23213%2C+Brampton%2C+ON+L6S+0C9","website":"https://www.kalialaw.com","blurb":"Family Law / Real Estate in Brampton. Rated 4.7 from 81 Google reviews.","type":"logo","src":"images/logos/kalia-law-firm-brampton.png"}',NULL,'Kalia Law Firm is a Brampton practice offering family law, real estate, wills and estates, notary and independent legal advice services.

The firm says it serves Brampton and nearby communities including Mississauga, Guelph, Georgetown, Caledon and Milton. Tulika Kalia is licensed as a barrister and solicitor in Ontario and handles family and real estate matters, and she says her network of lawyers extends the firm''s reach to more than four jurisdictions worldwide. The notary practice covers statutory declarations, affidavits, invitation letters, powers of attorney, name change applications and certified true copies, and the site also lists probate, travel documents and immigration services.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tsf-law-mississauga','TSF Law','Mississauga','ON','peel-halton',0,5,76,43.6288179,-79.6688955,'{"name":"TSF Law","city":"Mississauga","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"peel-halton","province":"ON","lat":43.6288179,"lng":-79.6688955,"address":"259 Traders Blvd E Unit 10, Mississauga, ON L4Z 2E5","phone":"+13655178731","rating":5,"count":76,"slug":"tsf-law-mississauga","mapsUrl":"https://www.google.com/maps/search/TSF+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=259+Traders+Blvd+E+Unit+10%2C+Mississauga%2C+ON+L4Z+2E5","website":"https://tsflaw.ca","blurb":"Personal Injury in Mississauga. Rated 5.0 from 76 Google reviews.","type":"logo","src":"images/logos/tsf-law-mississauga.png"}',NULL,'TSF Law is a Mississauga personal injury firm acting for people with denied long term disability benefits and injuries from car accidents and falls.

The firm says it practises personal injury law exclusively and acts for clients from across Ontario. Partner Terio Francis grew up in Toronto, studied at Dalhousie''s Schulich School of Law, and has appeared before the Superior Court of Justice and the License Appeal Tribunal and arbitrated at the Financial Services Commission of Ontario. The team also includes associate KristoFer Angle, licensed paralegal Licia Lionessa, Andrea Seecharan and Andreea Savin, and the head office is on Traders Boulevard East.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('zamani-law-toronto','Zamani Law','Toronto','ON','toronto',0,4.9,77,43.6503164,-79.3842467,'{"name":"Zamani Law","city":"Toronto","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"toronto","province":"ON","lat":43.6503164,"lng":-79.3842467,"address":"121 Richmond St W Suite 1100, Toronto, ON M5H 2K1","phone":"+16475788054","rating":4.9,"count":77,"slug":"zamani-law-toronto","mapsUrl":"https://www.google.com/maps/search/Zamani+Law+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=121+Richmond+St+W+Suite+1100%2C+Toronto%2C+ON+M5H+2K1","website":"https://zamani-law.com","blurb":"Criminal Defence in Toronto. Rated 4.9 from 77 Google reviews.","type":"logo","src":"images/logos/zamani-law-toronto.png"}',NULL,'Zamani Law is a Toronto criminal defence firm that represents people facing criminal allegations across the Greater Toronto Area.

Its practice areas include bail hearings and domestic violence charges, and the firm says its priority is protecting clients'' rights while seeking a reasonable resolution or withdrawal of charges. For family law, wills and estate planning and real estate, it describes alliances with other practitioners to whom it directs clients, noting that family disputes are often linked to criminal proceedings. Founder Farid Zamani is a co-founder of Children without Borders, a non-profit that raises awareness of child labour and sponsors education for children in Afghan communities. The office is on Richmond Street West.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('badesha-law-criminal-lawyer-brampton-brampton','Badesha Law Criminal Lawyer Brampton','Brampton','ON','peel-halton',0,5,75,43.748244,-79.699368,'{"name":"Badesha Law Criminal Lawyer Brampton","city":"Brampton","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"peel-halton","province":"ON","lat":43.748244,"lng":-79.699368,"address":"80 Maritime Ontario Blvd Ste 240, Brampton, ON L6S 0E7","phone":"+12894060110","rating":5,"count":75,"slug":"badesha-law-criminal-lawyer-brampton-brampton","mapsUrl":"https://www.google.com/maps/search/Badesha+Law+Criminal+Lawyer+Brampton+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=80+Maritime+Ontario+Blvd+Ste+240%2C+Brampton%2C+ON+L6S+0E7","website":"https://criminallawyerinbrampton.com","blurb":"Criminal Defence / Civil Litigation in Brampton. Rated 5.0 from 75 Google reviews.","type":"logo","src":"images/logos/badesha-law-criminal-lawyer-brampton-brampton.png"}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Badesha Law is a Brampton criminal defence firm representing people charged with assault, DUI, theft, domestic violence and other offences.

The firm is led by founding lawyer Harprit Badesha and senior lawyer Kajol Panchol. It says it acts from the first police involvement through bail hearings and trial, across Brampton, Mississauga, Peel Region and the Greater Toronto Area. Other charges listed include sexual assault, dangerous driving, uttering threats, and theft under and over $5,000. According to the site, fees can be flat or flexible, and the firm describes itself as available around the clock.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('swift-law-calgary','Swift Law','Calgary','AB','ab-calgary',0,4.9,75,51.0243501,-114.1112054,'{"name":"Swift Law","city":"Calgary","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"ab-calgary","province":"AB","lat":51.0243501,"lng":-114.1112054,"address":"2130 33 Ave SW B, Calgary, AB T2T 1Z6","phone":"+14033654397","rating":4.9,"count":75,"slug":"swift-law-calgary","mapsUrl":"https://www.google.com/maps/search/Swift+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2130+33+Ave+SW+B%2C+Calgary%2C+AB+T2T+1Z6","website":"https://www.swiftllp.ca","blurb":"Wills & Estates in Calgary. Rated 4.9 from 75 Google reviews.","type":"logo","src":"images/logos/swift-law-calgary.webp"}',NULL,'Swift Law is a Calgary real estate law practice, also called Swift LLP, handling residential purchases, sales and refinances.

The firm describes itself as a mobile practice based in Marda Loop, with flexible appointment options. Its site names Paul Kennett and Angela Mouton and cites more than 20 years of experience, and it lists wills and estates, mediation, and notary and commissioner for oaths services alongside real estate. It says it prepares custom fee estimates, gives direct access to the lawyer, and explains how the lawyer''s role differs from that of the realtor and mortgage broker in getting a deal to close.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('conron-law-professional-corporation-london','Conron Law Professional Corporation','London','ON','southwestern',0,5,73,42.985112,-81.2523468,'{"name":"Conron Law Professional Corporation","city":"London","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"southwestern","province":"ON","lat":42.985112,"lng":-81.2523468,"address":"Mezzanine Level, 140 Fullarton St #202, London, ON N6A 5P2","phone":"+15196731881","rating":5,"count":73,"slug":"conron-law-professional-corporation-london","mapsUrl":"https://www.google.com/maps/search/Conron+Law+Professional+Corporation+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=Mezzanine+Level%2C+140+Fullarton+St+%23202%2C+London%2C+ON+N6A+5P2","website":"https://www.conronlaw.ca","blurb":"Criminal Defence in London. Rated 5.0 from 73 Google reviews.","type":"logo","src":"images/logos/conron-law-professional-corporation-london.png"}',NULL,'Conron Law Professional Corporation is a London, Ontario criminal defence firm covering charges from assault to drug trafficking.

The firm says it handles all criminal charges, including domestic and non-domestic assault, aggravated and sexual assault, impaired driving, dangerous operation, theft and property crimes, drug possession and trafficking, firearm offences and breaches of court orders. Carolynn V. Conron, who holds an LL.M., heads the practice and has more than a decade in practice, with associate Katie Gosen and licensed paralegal Ashley Bates on the team. The office is on the mezzanine level at Fullarton Street.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('frenkel-tobin-llp-toronto','Frenkel Tobin LLP','Toronto','ON','toronto',0,4.9,73,43.6471843,-79.3923527,'{"name":"Frenkel Tobin LLP","city":"Toronto","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"toronto","province":"ON","lat":43.6471843,"lng":-79.3923527,"address":"317 Adelaide St W #1001, Toronto, ON M5V 1P9","phone":"+14163634273","rating":4.9,"count":73,"slug":"frenkel-tobin-llp-toronto","mapsUrl":"https://www.google.com/maps/search/Frenkel+Tobin+LLP+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=317+Adelaide+St+W+%231001%2C+Toronto%2C+ON+M5V+1P9","website":"https://frenkeltobin.ca","blurb":"Family Law in Toronto. Rated 4.9 from 73 Google reviews.","type":"logo","src":"images/logos/frenkel-tobin-llp-toronto.png"}',NULL,'Frenkel Tobin LLP is a downtown Toronto boutique firm focused exclusively on family and divorce law.

The firm says its lawyers act for clients in Ontario, across Canada and internationally, including mothers, fathers, grandparents, seniors, LGBTQ clients, people with limited finances and those with high net worth. Listed areas include separation, parenting schedules and decision-making for children, child support and spousal support. David Frenkel has practised only family law since 2008, has published in the Canadian Family Law Quarterly, Law Times and the Globe and Mail, and has spoken at the Law Society of Ontario''s Family Law Summit; David Tobin and several other lawyers are also profiled.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('m-j-o-nions-vancouver','M.J. O''Nions','Vancouver','BC','bc-vancouver',0,4.8,74,49.2803797,-123.1227709,'{"name":"M.J. O''Nions","city":"Vancouver","featured":false,"tags":["Family Law","Wills & Estates"],"caseTypes":["family","wills"],"region":"bc-vancouver","province":"BC","lat":49.2803797,"lng":-123.1227709,"address":"938 Howe St #311, Vancouver, BC V6Z 1N9","phone":"+16044497779","rating":4.8,"count":74,"slug":"m-j-o-nions-vancouver","mapsUrl":"https://www.google.com/maps/search/M.J.+O%27Nions+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=938+Howe+St+%23311%2C+Vancouver%2C+BC+V6Z+1N9","website":"https://www.mjonions.com","blurb":"Family Law / Wills & Estates in Vancouver. Rated 4.8 from 74 Google reviews.","type":"logo","src":"images/logos/m-j-o-nions-vancouver.jpg"}',NULL,'MJ O''Nions, now Stride Law, is a Vancouver firm practising family law, mediation, wills and estates and business law.

The site describes the firm as Stride Law, formerly M.J. O''Nions Lawyers & Mediators, a British Columbia practice whose areas include mediation, collaborative divorce, family law agreements, wills and estates, business law and notary services. On estates it describes litigation over unfair wills and the defence of estates against challenges, along with probate, letters of administration and flat-rate estate plans covering a will, power of attorney and advance health care directive. It says it does not charge for photocopying, faxing or secretarial time.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lazar-law-firm-london','Lazar Law Firm','London','ON','southwestern',0,4.6,77,42.9856912,-81.2487404,'{"name":"Lazar Law Firm","city":"London","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"southwestern","province":"ON","lat":42.9856912,"lng":-81.2487404,"address":"200 Queens Ave Ste 615, London, ON N6A 1J3","phone":"+15196019010","rating":4.6,"count":77,"slug":"lazar-law-firm-london","mapsUrl":"https://www.google.com/maps/search/Lazar+Law+Firm+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=200+Queens+Ave+Ste+615%2C+London%2C+ON+N6A+1J3","website":"https://lazarlaw.ca","blurb":"Real Estate in London. Rated 4.6 from 77 Google reviews.","type":"logo","src":"images/logos/lazar-law-firm-london.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Lazar Law Firm is a London, Ontario firm covering real estate, business, wills and estates, family law and paralegal services.

Its real estate practice handles residential and commercial purchases and sales, mortgage refinances and private mortgages, with title searches and closing coordination. The business side lists asset and share transactions, business purchases and sales, commercial leasing, start-ups and incorporation. Wills services include single, multiple and mirror wills for couples, plus estate administration and applications for a Certificate of Appointment of Estate Trustee. Its paralegal and civil services extend to Small Claims Court, the Landlord and Tenant Board and Provincial Offences Court.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('slipacoff-immigration-law-ottawa','Slipacoff Immigration Law','Ottawa','ON','eastern',0,5,70,45.3443125,-75.9246968,'{"name":"Slipacoff Immigration Law","city":"Ottawa","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"eastern","province":"ON","lat":45.3443125,"lng":-75.9246968,"address":"1000 Innovation Dr Ste 500, Kanata, ON K2K 3E7","phone":"+16138638776","rating":5,"count":70,"slug":"slipacoff-immigration-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Slipacoff+Immigration+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1000+Innovation+Dr+Ste+500%2C+Kanata%2C+ON+K2K+3E7","website":"https://slipacofflaw.com","blurb":"Immigration in Ottawa. Rated 5.0 from 70 Google reviews.","type":"logo","src":"images/logos/slipacoff-immigration-law-ottawa.png"}',NULL,'Slipacoff Immigration Law is an Ottawa-area practice handling immigration refusals, appeals, study permits, visitor visas and sponsorships.

Adam Slipacoff, a fourth-generation Canadian and Ottawa native, studied at Carleton University and Osgoode Hall Law School. The firm says it serves Toronto and Ottawa and represents clients challenging refusals through appeals and judicial applications to court, responds to procedural fairness letters and works on inadmissibility. Other listed services are Express Entry, spousal sponsorship, citizenship applications and PR card renewals. The office address is in Kanata, and the site also publishes guidance on settlement services for newcomers.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dabros-law-ottawa','Dabros Law','Ottawa','ON','eastern',0,4.9,71,45.428703,-75.6146629,'{"name":"Dabros Law","city":"Ottawa","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"eastern","province":"ON","lat":45.428703,"lng":-75.6146629,"address":"1900 City Park Dr suite 341, Ottawa, ON K1J 1A3","phone":"+16137149100","rating":4.9,"count":71,"slug":"dabros-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Dabros+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1900+City+Park+Dr+suite+341%2C+Ottawa%2C+ON+K1J+1A3","website":"https://www.dabroslaw.com","blurb":"Real Estate in Ottawa. Rated 4.9 from 71 Google reviews.","type":"logo","src":"images/logos/dabros-law-ottawa.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Dabros Law is a family-run Ottawa law office handling estates, wills and powers of attorney, residential real estate and personal injury.

The firm says it serves the greater Ottawa area, including Nepean, Barrhaven, South Keys, Findlay Creek, Orleans, Greely, Manotick and Stittsville. Founder Shane A. Dabros holds a degree from the University of Ottawa and a master''s in law from the University of Bristol, grew up in Orleans and names responsiveness as a pillar of his service. Slip and fall and car accident injuries are listed under personal injury, and the site also covers probate and estate administration as well as home purchases, sales and refinancing.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('boghossian-morais-llp-ottawa','Boghossian Morais LLP','Ottawa','ON','eastern',0,4.9,71,45.4066621,-75.7210209,'{"name":"Boghossian Morais LLP","city":"Ottawa","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"eastern","province":"ON","lat":45.4066621,"lng":-75.7210209,"address":"24 Bayswater Ave, Ottawa, ON K1Y 2E4","phone":"+18777010109","rating":4.9,"count":71,"slug":"boghossian-morais-llp-ottawa","mapsUrl":"https://www.google.com/maps/search/Boghossian+Morais+LLP+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=24+Bayswater+Ave%2C+Ottawa%2C+ON+K1Y+2E4","website":"https://bmlawyers.ca","blurb":"Immigration in Ottawa. Rated 4.9 from 71 Google reviews.","type":"logo","src":"images/logos/boghossian-morais-llp-ottawa.png"}',NULL,'Boghossian Morais LLP is an Ottawa firm whose two lawyers and support staff work exclusively in immigration and refugee law.

The firm says it offers services in English, French, Armenian and Brazilian Portuguese. Its listed work includes Express Entry applications under the Canadian Experience Class and Federal Skilled Worker and Trades programs, provincial nominee applications, visitor and study permits, business immigration, intra-company transfers, work permits, hiring temporary foreign workers and family sponsorship. The team page identifies a founding member of the Canadian Immigration Lawyers Association, and appointments by Skype are available for clients outside the National Capital Region.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('matthew-feehan-estate-lawyer-edmonton','Matthew Feehan Estate Lawyer','Edmonton','AB','ab-edmonton',0,4.7,74,53.5423152,-113.5254749,'{"name":"Matthew Feehan Estate Lawyer","city":"Edmonton","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"ab-edmonton","province":"AB","lat":53.5423152,"lng":-113.5254749,"address":"10160 118 St NW, Edmonton, AB T5K 1Y4","phone":"+17804246430","rating":4.7,"count":74,"slug":"matthew-feehan-estate-lawyer-edmonton","mapsUrl":"https://www.google.com/maps/search/Matthew+Feehan+Estate+Lawyer+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=10160+118+St+NW%2C+Edmonton%2C+AB+T5K+1Y4","website":"https://matthewfeehan.ca","blurb":"Wills & Estates in Edmonton. Rated 4.7 from 74 Google reviews.","type":"logo","src":"images/logos/matthew-feehan-estate-lawyer-edmonton.jpg"}',NULL,'Matthew Feehan Estate Lawyer is an Edmonton practice dealing with wills, probate and estate administration.

The website header lists F.M. (Ned) Feehan QC, Mark E. Feehan and Matthew F. Feehan, and says the practice serves clients across Canada from offices in Alberta and British Columbia. Its pages explain what probate is and when it is required, how applications and grants of administration work, why a person should have a will and what naming an executor involves.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('agp-llp-ottawa-criminal-lawyers-ottawa','AGP LLP Ottawa Criminal Lawyers','Ottawa','ON','eastern',0,4.6,75,45.419433,-75.6904642,'{"name":"AGP LLP Ottawa Criminal Lawyers","city":"Ottawa","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"eastern","province":"ON","lat":45.419433,"lng":-75.6904642,"address":"116 Lisgar St Ste 200, Ottawa, ON K2P 0C2","phone":"+16132359779","rating":4.6,"count":75,"slug":"agp-llp-ottawa-criminal-lawyers-ottawa","mapsUrl":"https://www.google.com/maps/search/AGP+LLP+Ottawa+Criminal+Lawyers+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=116+Lisgar+St+Ste+200%2C+Ottawa%2C+ON+K2P+0C2","website":"https://www.agpllp.ca","blurb":"Criminal Defence in Ottawa. Rated 4.6 from 75 Google reviews.","type":"logo","src":"images/logos/agp-llp-ottawa-criminal-lawyers-ottawa.webp"}','{"1":[["08:30","17:00"]],"2":[["08:30","17:00"]],"3":[["08:30","17:00"]],"4":[["08:30","17:00"]],"5":[["08:30","17:00"]]}','AGP LLP is an Ottawa criminal defence firm of trial and appellate lawyers handling appeals, assault, drinking and driving, drug and homicide cases.

The firm says it was founded in Ottawa two decades ago and describes a custom-crafted defence for each client. Its practice areas include bail hearings, domestic assaults, sexual assault and white-collar matters, and it acts for executives, civil servants, doctors, pharmacists, high-tech workers, diplomats and organizations facing criminal or regulatory issues. A separate appeals page explains that criminal appeals turn on finding legal errors, and says the firm defends against Crown appeals from acquittal or sentence and takes referrals from other lawyers.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gauthier-and-mines-criminal-lawyers-vancouver','Gauthier & Mines Criminal Lawyers','Vancouver','BC','bc-vancouver',0,4.9,70,49.2876033,-123.1171306,'{"name":"Gauthier & Mines Criminal Lawyers","city":"Vancouver","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"bc-vancouver","province":"BC","lat":49.2876033,"lng":-123.1171306,"address":"355 Burrard St #1550, Vancouver, BC V6C 2G8","phone":"+16046881460","rating":4.9,"count":70,"slug":"gauthier-and-mines-criminal-lawyers-vancouver","mapsUrl":"https://www.google.com/maps/search/Gauthier+%26+Mines+Criminal+Lawyers+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=355+Burrard+St+%231550%2C+Vancouver%2C+BC+V6C+2G8","website":"https://mineslaw.com","blurb":"Criminal Defence in Vancouver. Rated 4.9 from 70 Google reviews.","type":"logo","src":"images/logos/gauthier-and-mines-criminal-lawyers-vancouver.png"}',NULL,'Gauthier & Mines Criminal Lawyers is a Vancouver firm that has defended criminal charges across British Columbia since 1993.

Formerly Mines & Company, the firm lists Michael Mines, Ian Gauthier, Patrick Johnston, Courtney McLaughlin and Ishnoor Dhillon, and says its lawyers focus solely on criminal law, civil forfeiture and Motor Vehicle Act defence. Charges it names include assault, driving, drug, sexual assault, theft and fraud, weapons, murder and other serious offences, plus driving prohibitions and professional discipline. The firm appears in courts throughout Metro Vancouver and the rest of the province, has conducted cases in Alberta, Ontario, Quebec and the Yukon, and describes Alternative Measures programs that can end a prosecution without a criminal record.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jeremie-john-martin-montreal','Jérémie John Martin','Montreal','QC','qc-montreal',0,4.8,71,45.49602,-73.576563,'{"name":"Jérémie John Martin","city":"Montreal","featured":false,"tags":["Civil Litigation"],"caseTypes":["litigation"],"region":"qc-montreal","province":"QC","lat":45.49602,"lng":-73.576563,"address":"1440 Sainte-Catherine St. West #522, Montreal, Quebec H3G 1R8","phone":"+15148396014","rating":4.8,"count":71,"slug":"jeremie-john-martin-montreal","mapsUrl":"https://www.google.com/maps/search/J%C3%A9r%C3%A9mie+John+Martin+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1440+Sainte-Catherine+St.+West+%23522%2C+Montreal%2C+Quebec+H3G+1R8","website":"https://www.maitremartin.com","blurb":"Civil Litigation in Montreal. Rated 4.8 from 71 Google reviews.","type":"logo","src":"images/logos/jeremie-john-martin-montreal.png"}',NULL,'Jérémie John Martin is a bilingual Montreal litigation lawyer who practises and pleads in both French and English.

According to his website, Me Martin is originally from Quebec, now lives on the Island of Montreal and serves all judicial districts of Quebec. He favours a diplomatic approach aimed at settling files out of court, while remaining ready to plead. In 2006 he took the national inter-university debating championship Face à Face in Sherbrooke with colleague Yves Tanguay, and also earned the individual pleader''s bursary. The site has pages on his services, fees, the courthouses he serves, partners and associates, and media appearances.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hum-employment-law-firm-toronto','Hum Employment Law Firm','Toronto','ON','toronto',0,4.7,72,43.6486362,-79.3817439,'{"name":"Hum Employment Law Firm","city":"Toronto","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.6486362,"lng":-79.3817439,"address":"First Canadian Place, 100 King St W Ste 5700, Toronto, ON M5H 1H1","phone":"+14162142329","rating":4.7,"count":72,"slug":"hum-employment-law-firm-toronto","mapsUrl":"https://www.google.com/maps/search/Hum+Employment+Law+Firm+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=First+Canadian+Place%2C+100+King+St+W+Ste+5700%2C+Toronto%2C+ON+M5H+1H1","website":"https://thehumlawfirm.ca","blurb":"Employment Law in Toronto. Rated 4.7 from 72 Google reviews.","type":"logo","src":"images/logos/hum-employment-law-firm-toronto.webp"}',NULL,'Hum Employment Law Firm is a Toronto firm focused on workplace and employment law, human rights, investigations and mediation.

The firm says it practises in Ontario and Quebec, in English and French, for employers and employees and for plaintiffs and defendants. Its main office is in downtown Toronto, with additional offices in Markham, Mississauga, Richmond Hill and Scarborough and appointments also held in London, Ontario and Montreal. Services listed include workplace investigations, shareholder disputes, professional regulation matters and litigation, and employer guidance on contracts, policies, risk management and compliance. The site publishes articles on topics such as constructive dismissal, medical leave and AI use in the workplace.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('z-legal-litigation-lawyer-toronto','Z Legal Litigation Lawyer','Toronto','ON','toronto',0,4.9,69,43.7000989,-79.3972723,'{"name":"Z Legal Litigation Lawyer","city":"Toronto","featured":false,"tags":["Civil Litigation","Employment Law","Wills & Estates","Family Law"],"caseTypes":["litigation","employment","wills","family"],"region":"toronto","province":"ON","lat":43.7000989,"lng":-79.3972723,"address":"1984 Yonge St, Toronto, ON M4S 1Z7","phone":"+18552337440","rating":4.9,"count":69,"slug":"z-legal-litigation-lawyer-toronto","mapsUrl":"https://www.google.com/maps/search/Z+Legal+Litigation+Lawyer+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1984+Yonge+St%2C+Toronto%2C+ON+M4S+1Z7","website":"https://www.zlegal.ca","blurb":"Civil Litigation / Employment Law in Toronto. Rated 4.9 from 69 Google reviews.","type":"logo","src":"images/logos/z-legal-litigation-lawyer-toronto.png"}',NULL,'Z Legal is a Toronto litigation firm handling estate, employment, commercial and family disputes and professional misconduct matters.

Founder Martin Zatovkanuk is described as a litigation lawyer with more than a decade of experience before all levels of Ontario courts. The firm says it represents clients from the outset of a matter to its end, whether it resolves by settlement, mediation, arbitration or trial. Its employment practice acts for employees and employers on wrongful dismissal, severance pay, constructive dismissal and workplace harassment across Toronto and the GTA, while other pages cover real estate litigation and will challenges. It mentions flat-rate and contingency fee options.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('muenz-criminal-law-calgary','Muenz Criminal Law','Calgary','AB','ab-calgary',0,4.9,69,51.0480333,-114.0732375,'{"name":"Muenz Criminal Law","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.0480333,"lng":-114.0732375,"address":"550 6 Ave SW #900, Calgary, AB T2P 0S2","phone":"+14035436666","rating":4.9,"count":69,"slug":"muenz-criminal-law-calgary","mapsUrl":"https://www.google.com/maps/search/Muenz+Criminal+Law+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=550+6+Ave+SW+%23900%2C+Calgary%2C+AB+T2P+0S2","website":"https://www.rickmuenz.ca","blurb":"Criminal Defence in Calgary. Rated 4.9 from 69 Google reviews.","type":"logo","src":"images/logos/muenz-criminal-law-calgary.png"}','{"1":[["08:30","21:00"]],"2":[["08:30","21:00"]],"3":[["08:30","21:00"]],"4":[["08:30","21:00"]],"5":[["08:30","21:00"]],"6":[["08:30","21:00"]],"7":[["08:30","21:00"]]}','Muenz Criminal Law is a Calgary criminal defence firm whose lead lawyer has practised exclusively in criminal law since 1992.

Rick Muenz leads the firm, and its pages also name Alvin Luximon, Maria Muenz and Giuliana Di Lorenzo. He holds admissions in Alberta (1993) and British Columbia (2001), has worked on cases in five provinces and the Yukon, and teaches in the Advanced Criminal Law Course at the University of Calgary Faculty of Law. Listed charges include sexual assault, domestic assault, impaired driving, drug trafficking, theft and fraud, and youth offences. The firm says staff can explain the legal process in French, Spanish and Italian, and it works with The Pardon Group on record suspensions, U.S. entry waivers and digital fingerprinting.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('frouhar-law-ottawa','Frouhar Law','Ottawa','ON','eastern',0,4.7,71,45.4179029,-75.6961238,'{"name":"Frouhar Law","city":"Ottawa","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"eastern","province":"ON","lat":45.4179029,"lng":-75.6961238,"address":"190 O''Connor St Ste 700, Ottawa, ON K2P 1T6","phone":"+16132382000","rating":4.7,"count":71,"slug":"frouhar-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Frouhar+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=190+O%27Connor+St+Ste+700%2C+Ottawa%2C+ON+K2P+1T6","website":"https://www.frouharlaw.com","blurb":"Criminal Defence in Ottawa. Rated 4.7 from 71 Google reviews.","type":"logo","src":"images/logos/frouhar-law-ottawa.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Frouhar Law is an Ottawa criminal defence firm defending assault, impaired driving, drug, sexual assault, homicide and fraud charges.

The firm says it serves Ottawa, Brockville and Eastern Ontario and lists an emergency line available around the clock. Mash Frouhar was called to the Ontario Bar in 2009, previously worked as an Assistant Crown Attorney and as a defence lawyer with Legal Aid Ontario, and offers services in English, French and Farsi. Connie D''Angelo was called in 1993 and has practised only criminal law, including representing police officers before the Special Investigations Unit and at Police Services Act hearings. Micaela Rodriguez is also on the team.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('wvgb-personal-injury-lawyers-ottawa','WVGB Personal Injury Lawyers','Ottawa','ON','eastern',0,4.9,67,45.3634125,-75.7875245,'{"name":"WVGB Personal Injury Lawyers","city":"Ottawa","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"eastern","province":"ON","lat":45.3634125,"lng":-75.7875245,"address":"2571 Carling Ave #200, Ottawa, ON K2B 7H7","phone":"+16135055025","rating":4.9,"count":67,"slug":"wvgb-personal-injury-lawyers-ottawa","mapsUrl":"https://www.google.com/maps/search/WVGB+Personal+Injury+Lawyers+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2571+Carling+Ave+%23200%2C+Ottawa%2C+ON+K2B+7H7","website":"https://www.wvglaw.com","blurb":"Personal Injury in Ottawa. Rated 4.9 from 67 Google reviews.","type":"logo","src":"images/logos/wvgb-personal-injury-lawyers-ottawa.png"}',NULL,'WVGB Personal Injury Lawyers is an Ottawa firm acting for people hurt in car crashes, falls, brain injuries and other accidents.

The site describes WVGB Law Group as established in 2021 through a partnership between Villeneuve Litigation P.C. and Wolfe Lawyers P.C., serving English and French speaking communities in Ottawa and the Ottawa Valley. It says clients work directly with a partner who oversees the case personally. Practice pages cover car accidents, slip and trip and falls, brain injuries, animal attacks and rideshare and taxi accidents, along with wills and estates, and the site explains the time limits that apply to injury cases.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hammer-injury-law-edmonton','Hammer Injury Law','Edmonton','AB','ab-edmonton',0,5,65,53.5411321,-113.5135157,'{"name":"Hammer Injury Law","city":"Edmonton","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"ab-edmonton","province":"AB","lat":53.5411321,"lng":-113.5135157,"address":"11150 Jasper Ave #355, Edmonton, AB T5K 0C7","phone":"+15874054092","rating":5,"count":65,"slug":"hammer-injury-law-edmonton","mapsUrl":"https://www.google.com/maps/search/Hammer+Injury+Law+Edmonton+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=11150+Jasper+Ave+%23355%2C+Edmonton%2C+AB+T5K+0C7","website":"https://www.hammerinjurylaw.ca","blurb":"Personal Injury in Edmonton. Rated 5.0 from 65 Google reviews.","type":"logo","src":"images/logos/hammer-injury-law-edmonton.png"}',NULL,'Hammer Injury Law is an Edmonton personal injury firm focused on motor vehicle accident injuries, serious injury and wrongful death.

Richard J. Mallett graduated from the University of Alberta in 1989, was admitted to the Alberta Bar in 1990 and spent his first ten years in insurance defence and corporate law before acting exclusively for injured people from 1999. He established the firm in 2023 and has appeared in Alberta courts, the Supreme Courts of the Northwest Territories and the Yukon, the CPP Appeal Tribunal and the WCB Appeals Commission. The firm says it serves Alberta, British Columbia, the Yukon and the Northwest Territories, and it also describes class actions.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lambert-law-victoria','Lambert Law','Victoria','BC','bc-victoria',0,4.6,70,48.4693634,-123.3623087,'{"name":"Lambert Law","city":"Victoria","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"bc-victoria","province":"BC","lat":48.4693634,"lng":-123.3623087,"address":"1095 McKenzie Ave, Victoria, BC V8P 2L5","phone":"+12505887679","rating":4.6,"count":70,"slug":"lambert-law-victoria","mapsUrl":"https://www.google.com/maps/search/Lambert+Law+Victoria+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1095+McKenzie+Ave%2C+Victoria%2C+BC+V8P+2L5","website":"https://lambertlaw.com","blurb":"Personal Injury in Victoria. Rated 4.6 from 70 Google reviews.","type":"logo","src":"images/logos/lambert-law-victoria.png"}',NULL,'Lambert Law is a Victoria firm handling personal injury, medical malpractice, motor vehicle tribunal matters and general litigation.

The firm says Rory Lambert and his legal team have represented members of the Victoria community for more than 30 years. On medical malpractice, its pages say it works with doctors, nurses and other medical professionals who assess a case before a decision to sue, and note that litigation against medical professionals can be costly and take several years. The site also outlines the general two-year limitation period in British Columbia, measured from the last date of the treatment alleged to be negligent.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nanda-family-and-divorce-lawyers-mississauga','Nanda Family and Divorce Lawyers','Mississauga','ON','peel-halton',0,5,64,43.5964038,-79.6369796,'{"name":"Nanda Family and Divorce Lawyers","city":"Mississauga","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"peel-halton","province":"ON","lat":43.5964038,"lng":-79.6369796,"address":"2 Robert Speck Pkwy Suite 750, Mississauga, ON L4Z 1H8","phone":"+18666606640","rating":5,"count":64,"slug":"nanda-family-and-divorce-lawyers-mississauga","mapsUrl":"https://www.google.com/maps/search/Nanda+Family+and+Divorce+Lawyers+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2+Robert+Speck+Pkwy+Suite+750%2C+Mississauga%2C+ON+L4Z+1H8","website":"https://familylawyersmississauga.com","blurb":"Family Law in Mississauga. Rated 5.0 from 64 Google reviews.","type":"logo","src":"images/logos/nanda-family-and-divorce-lawyers-mississauga.png"}',NULL,'Nanda Family and Divorce Lawyers is a Mississauga firm handling divorce, child custody, child support and financial issues after separation.

The site describes a family law team that guides clients through the legal steps of ending a marriage, sets up child arrangement orders on where children live and how decisions about their upbringing are made, and addresses financial adjustments after separation. The firm says its Mississauga family lawyers aim for fair resolutions and keep the well-being of children in focus. Its office is on Robert Speck Parkway.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('dhasi-law-family-lawyer-brampton-brampton','Dhasi Law Family Lawyer Brampton','Brampton','ON','peel-halton',0,4.9,65,43.7999386,-79.7489725,'{"name":"Dhasi Law Family Lawyer Brampton","city":"Brampton","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"peel-halton","province":"ON","lat":43.7999386,"lng":-79.7489725,"address":"6475 Mayfield Rd Unit 206, Brampton, ON L6P 4N2","phone":"+16475096952","rating":4.9,"count":65,"slug":"dhasi-law-family-lawyer-brampton-brampton","mapsUrl":"https://www.google.com/maps/search/Dhasi+Law+Family+Lawyer+Brampton+Brampton+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=6475+Mayfield+Rd+Unit+206%2C+Brampton%2C+ON+L6P+4N2","website":"https://www.dhasilaw.com","blurb":"Family Law in Brampton. Rated 4.9 from 65 Google reviews.","type":"logo","src":"images/logos/dhasi-law-family-lawyer-brampton-brampton.webp"}',NULL,'Dhasi Law is a Brampton firm serving Ontario clients in personal injury, immigration, criminal law, civil litigation, estates and real estate.

The site lists a wide set of practice areas: personal injury, immigration, criminal law, civil litigation, notary public, wills, estates and trusts, real estate, corporate law and family law. For injuries caused by negligence, it describes pursuing compensation for medical expenses and lost income. Immigration work covers applications, permits and sponsorships for individuals and families, and the criminal practice supports clients facing charges through the court process. The office is on Mayfield Road in Brampton.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lt-lawyers-llp-calgary','LT Lawyers LLP','Calgary','AB','ab-calgary',0,5,63,51.0480395,-114.0754341,'{"name":"LT Lawyers LLP","city":"Calgary","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"ab-calgary","province":"AB","lat":51.0480395,"lng":-114.0754341,"address":"630 6 Ave SW #750, Calgary, AB T2P 0S8","phone":"+14034838888","rating":5,"count":63,"slug":"lt-lawyers-llp-calgary","mapsUrl":"https://www.google.com/maps/search/LT+Lawyers+LLP+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=630+6+Ave+SW+%23750%2C+Calgary%2C+AB+T2P+0S8","website":"https://ltlawyers.ca","blurb":"Personal Injury / Civil Litigation in Calgary. Rated 5.0 from 63 Google reviews.","type":"logo","src":"images/logos/lt-lawyers-llp-calgary.png"}',NULL,'LT Lawyers LLP is a Calgary boutique firm representing injured people and those denied long-term disability benefits in Alberta and British Columbia.

Co-founders Ryan Lee and Peter Trieu lead the firm; Lee previously acted for insurance companies in personal injury cases and has appeared before the Alberta Court of King''s Bench and the Supreme Court of British Columbia. The site notes that two of its lawyers are former criminal prosecutors, and lists Daniel Gelb, Faye Gelb and Bridget Belsher among the team. Matters named include car crashes, injuries caused by negligence and long-term disability denials and terminations, with strategies ranging from settlement to trial.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nanuq-law-victoria','Nanuq Law','Victoria','BC','bc-victoria',0,5,62,48.463826,-123.4042573,'{"name":"Nanuq Law","city":"Victoria","featured":false,"tags":["Personal Injury","Wills & Estates","Civil Litigation"],"caseTypes":["injury","wills","litigation"],"region":"bc-victoria","province":"BC","lat":48.463826,"lng":-123.4042573,"address":"359 Marigold Rd, Victoria, BC V8Z 4R1","phone":"+17784335297","rating":5,"count":62,"slug":"nanuq-law-victoria","mapsUrl":"https://www.google.com/maps/search/Nanuq+Law+Victoria+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=359+Marigold+Rd%2C+Victoria%2C+BC+V8Z+4R1","website":"https://www.nanuqlaw.com","blurb":"Personal Injury / Wills & Estates in Victoria. Rated 5.0 from 62 Google reviews.","type":"logo","src":"images/logos/nanuq-law-victoria.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Nanuq Law is a Victoria boutique firm handling personal injury, employment law and estate litigation, with real estate and wills also listed.

The firm, which its site data dates to 2011, takes its name from Nanuq, the master of the polar bears, and compares the animal''s strength to its own approach. Marlisa H. Martin is profiled on the site. Practice pages cover motor vehicle accidents, slip and fall injuries, medical malpractice, injuries at work, pedestrian and bicycle injuries, estate litigation, real estate purchases and leases, and wills and power of attorney. Motor vehicle accident work is described as taken on a contingency fee basis.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('charney-legal-toronto','Charney Legal','Toronto','ON','toronto',0,4.9,63,43.6879948,-79.4124285,'{"name":"Charney Legal","city":"Toronto","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"toronto","province":"ON","lat":43.6879948,"lng":-79.4124285,"address":"383 Spadina Rd Suite 200, Toronto, ON M6C 1A7","phone":"+16475502918","rating":4.9,"count":63,"slug":"charney-legal-toronto","mapsUrl":"https://www.google.com/maps/search/Charney+Legal+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=383+Spadina+Rd+Suite+200%2C+Toronto%2C+ON+M6C+1A7","website":"https://charneylegal.ca","blurb":"Wills & Estates in Toronto. Rated 4.9 from 63 Google reviews.","type":"logo","src":"images/logos/charney-legal-toronto.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Charney Legal is a Toronto remote law firm handling wills, estates, probate and real estate matters for clients across Ontario.

Charney Legal Professional Corporation says it works online and uses technology to serve Ontario and clients elsewhere, and it also offers online or in-person mediation for family and estate disputes. Its estate services include tailored estate plans and advice to trustees, executors and beneficiaries on administering an estate and obtaining Certificates of Appointment of Estate Trustee, with or without a will. Real estate work includes mortgage refinances. The office address is on Spadina Road in Toronto.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mikhael-avocat-inc-montreal','Mikhael Avocat Inc.','Montreal','QC','qc-montreal',0,4.9,63,45.503694,-73.5574091,'{"name":"Mikhael Avocat Inc.","city":"Montreal","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"qc-montreal","province":"QC","lat":45.503694,"lng":-73.5574091,"address":"204 R. Notre Dame O #300, Montreal, Quebec H2Y 1T3","phone":"+15144271414","rating":4.9,"count":63,"slug":"mikhael-avocat-inc-montreal","mapsUrl":"https://www.google.com/maps/search/Mikhael+Avocat+Inc.+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=204+R.+Notre+Dame+O+%23300%2C+Montreal%2C+Quebec+H2Y+1T3","website":"https://mikhaelavocat.com","blurb":"Family Law in Montreal. Rated 4.9 from 63 Google reviews.","type":"logo","src":"images/logos/mikhael-avocat-inc-montreal.png"}',NULL,'Mikhael Avocat is a Montreal law firm handling immigration and joint divorce matters, with offices in Montreal and Outaouais.

The firm was founded by Me Marianne Mikhael, who holds a Licentiate in Law from the University of Ottawa, has been a member of the Québec Bar since 2020 and belongs to the Québec Association of Immigration Lawyers and the Canadian Association of Refugee Lawyers. The site says the firm helps individuals and families with Canadian immigration matters, handles joint divorces by encouraging open dialogue between spouses, and offers translation services to overcome language barriers. Its page titles also mention business law and Gatineau.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('whitestone-law-ottawa','Whitestone Law','Ottawa','ON','eastern',0,5,61,45.4276094,-75.6767084,'{"name":"Whitestone Law","city":"Ottawa","featured":false,"tags":["Real Estate","Wills & Estates","Business Law"],"caseTypes":["realestate","wills","business"],"region":"eastern","province":"ON","lat":45.4276094,"lng":-75.6767084,"address":"5 Ave Blackburn, Ottawa, ON K1N 8A2","phone":"+16136511865","rating":5,"count":61,"slug":"whitestone-law-ottawa","mapsUrl":"https://www.google.com/maps/search/Whitestone+Law+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5+Ave+Blackburn%2C+Ottawa%2C+ON+K1N+8A2","website":"https://whitestonelaw.ca","blurb":"Real Estate / Wills & Estates in Ottawa. Rated 5.0 from 61 Google reviews.","type":"logo","src":"images/logos/whitestone-law-ottawa.png"}',NULL,'Whitestone Law is an Ottawa firm providing corporate and commercial law, real estate transactions and estate planning for clients across Ontario.

The firm says it acts for businesses, individuals and families, and that clients work directly with their lawyer for continuity and clear communication. Corporate work covers mergers and acquisitions, incorporations, restructuring, contract drafting and regulatory compliance, with ongoing advisory and general counsel services available. Real estate files include buying, selling and refinancing, and estate planning centres on wills and inheritance planning. The site states that costs are explained before work starts and that every lawyer on the team is licensed in Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('malina-a-roshan-mississauga','Malina A. Roshan','Mississauga','ON','peel-halton',0,4.9,62,43.6794609,-79.670997,'{"name":"Malina A. Roshan","city":"Mississauga","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"peel-halton","province":"ON","lat":43.6794609,"lng":-79.670997,"address":"7895 Tranmere Dr Ste 21, Mississauga, ON L5S 1V9","phone":"+14168346428","rating":4.9,"count":62,"slug":"malina-a-roshan-mississauga","mapsUrl":"https://www.google.com/maps/search/Malina+A.+Roshan+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=7895+Tranmere+Dr+Ste+21%2C+Mississauga%2C+ON+L5S+1V9","website":"https://www.roshanlaw.com","blurb":"Family Law in Mississauga. Rated 4.9 from 62 Google reviews.","type":"logo","src":"images/logos/malina-a-roshan-mississauga.webp"}',NULL,'Malina Roshan runs Roshan Law, a Mississauga practice handling family and divorce law as well as criminal defence matters.

According to its website, Malina Roshan founded the firm in 2010 and has more than 15 years as a family and criminal lawyer, regularly appearing in the Superior Court of Justice. The firm lists service to the Greater Toronto Area and communities including Brampton, Etobicoke, North York, Hamilton, Milton, Guelph, Kitchener, Waterloo, Vaughan, Newmarket, Oakville, Burlington, Oshawa and Orangeville. It says it offers clear pricing, regular updates on the file and a process that starts with booking a meeting.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hergott-law-kelowna','Hergott Law','Kelowna','BC','bc-okanagan',0,4.8,63,49.8894754,-119.4933656,'{"name":"Hergott Law","city":"Kelowna","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"bc-okanagan","province":"BC","lat":49.8894754,"lng":-119.4933656,"address":"1385 Ellis St, Kelowna, BC V1Y 1Z9","phone":"+18554374688","rating":4.8,"count":63,"slug":"hergott-law-kelowna","mapsUrl":"https://www.google.com/maps/search/Hergott+Law+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1385+Ellis+St%2C+Kelowna%2C+BC+V1Y+1Z9","website":"https://www.hlaw.ca","blurb":"Wills & Estates in Kelowna. Rated 4.8 from 63 Google reviews.","type":"logo","src":"images/logos/hergott-law-kelowna.webp"}',NULL,'Hergott Law is a Kelowna boutique firm focused on estate planning and estate administration, including probate and executor support.

Paul Hergott leads the firm, which he and his wife Terri opened in 2007 to serve Kelowna and West Kelowna; Terri provides administrative support, and the site calls it a team of two. The firm says Paul moved from litigation and defending injured people''s rights to practising exclusively in estate administration. Services listed include obtaining probate or letters of administration, supporting executors, seeking compensation for executors'' work and will curing. It also advises on wills, powers of attorney and representation agreements, and describes serving the Okanagan since 1995.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('just-done-law-office-toronto','Just Done Law Office','Toronto','ON','toronto',0,4.8,62,43.659124,-79.383546,'{"name":"Just Done Law Office","city":"Toronto","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"toronto","province":"ON","lat":43.659124,"lng":-79.383546,"address":"386 Yonge St #1006, Toronto, ON M5B 1N9","phone":"+16477812288","rating":4.8,"count":62,"slug":"just-done-law-office-toronto","mapsUrl":"https://www.google.com/maps/search/Just+Done+Law+Office+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=386+Yonge+St+%231006%2C+Toronto%2C+ON+M5B+1N9","website":"https://www.justdonelaw.com","blurb":"Real Estate in Toronto. Rated 4.8 from 62 Google reviews.","type":"logo","src":"images/logos/just-done-law-office-toronto.png"}',NULL,'Just Done Law Office is a Toronto firm focused on real estate transactions including home purchases, sales, title transfers and mortgage refinances.

Principal lawyer Julian Prieto practises real estate transactions and real estate litigation, says he has overseen more than $300 million in transaction volume and holds a JD from McGill University. He has represented clients at the Superior Court of Ontario and administrative tribunals. The firm says its service can be completed remotely and lists its steps, which include reviewing the agreement of purchase and sale and status certificates, checking title for liens and mortgages, advising on land transfer tax and arranging title insurance. It publishes fixed prices for each service.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('jeffrey-r-horricks-law-corporation-vancouver','Jeffrey R. Horricks Law Corporation','Vancouver','BC','bc-vancouver',0,5,59,49.2805947,-123.1174441,'{"name":"Jeffrey R. Horricks Law Corporation","city":"Vancouver","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"bc-vancouver","province":"BC","lat":49.2805947,"lng":-123.1174441,"address":"777 Richards St Suite 602, Vancouver, BC V6B 0M6","phone":"+16043053152","rating":5,"count":59,"slug":"jeffrey-r-horricks-law-corporation-vancouver","mapsUrl":"https://www.google.com/maps/search/Jeffrey+R.+Horricks+Law+Corporation+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=777+Richards+St+Suite+602%2C+Vancouver%2C+BC+V6B+0M6","website":"https://horrickslaw.net","blurb":"Wills & Estates in Vancouver. Rated 5.0 from 59 Google reviews.","type":"logo","src":"images/logos/jeffrey-r-horricks-law-corporation-vancouver.png"}',NULL,'Jeffrey Horricks Law Corporation is a Vancouver practice handling real estate, corporate and estate law.

Jeffrey Horricks was born and raised in Vancouver, studied at the University of Victoria and earned his Juris Doctor from Bond University in Australia. After returning in 2012 he worked at a corporate and securities firm and then at a boutique criminal law practice, and he established Horricks Law in 2014. The firm serves individuals, families and businesses across Vancouver and the Lower Mainland, with real estate pages covering strata properties, mortgages and financing, and development and investment deals. It says clients speak directly with the lawyer and that flat-fee options are offered.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bin-xia-zhang-montreal','Bin Xia Zhang','Montreal','QC','qc-montreal',0,5,58,45.5027367,-73.5572834,'{"name":"Bin Xia Zhang","city":"Montreal","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"qc-montreal","province":"QC","lat":45.5027367,"lng":-73.5572834,"address":"465 Rue Saint-Jean bureau 603, Montreal, Quebec H2Y 2R6","phone":"+15146329386","rating":5,"count":58,"slug":"bin-xia-zhang-montreal","mapsUrl":"https://www.google.com/maps/search/Bin+Xia+Zhang+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=465+Rue+Saint-Jean+bureau+603%2C+Montreal%2C+Quebec+H2Y+2R6","website":"https://www.quebecvisa.ca","blurb":"Immigration in Montreal. Rated 5.0 from 58 Google reviews.","type":"logo","src":"images/logos/bin-xia-zhang-montreal.png"}',NULL,'Bin Xia Zhang is a Montreal immigration lawyer who helps international students and temporary foreign workers seek permanent residence.

According to the site, the practice has run since 2016 and works mainly on temporary residence, permanent residence and Canadian citizenship applications. Bin Xia Zhang immigrated to Canada from China at age 9, and later worked in a college''s international students department helping with temporary residence applications. The practice describes assessing eligibility, planning a route to permanent residence where a client is eligible, guiding clients toward eligibility where not, and helping prepare and assemble applications. The website is available in English and French and the office is on rue Saint-Jean.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('vml-family-law-llp-calgary','VML Family Law LLP','Calgary','AB','ab-calgary',0,4.8,60,51.0309152,-114.0710267,'{"name":"VML Family Law LLP","city":"Calgary","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"ab-calgary","province":"AB","lat":51.0309152,"lng":-114.0710267,"address":"2424 4 St SW #1030, Calgary, AB T2S 0L4","phone":"+15873581211","rating":4.8,"count":60,"slug":"vml-family-law-llp-calgary","mapsUrl":"https://www.google.com/maps/search/VML+Family+Law+LLP+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2424+4+St+SW+%231030%2C+Calgary%2C+AB+T2S+0L4","website":"https://vmlfamilylaw.com","blurb":"Family Law in Calgary. Rated 4.8 from 60 Google reviews.","type":"logo","src":"images/logos/vml-family-law-llp-calgary.webp"}',NULL,'VML Family Law LLP is a Calgary family law firm offering divorce, custody, child support, mediation, arbitration and litigation services.

The firm says its team includes mediators, arbitrators, parenting coordinators and litigators. Listed services also include asset and debt separation, adoption, child abduction law, prenuptial agreements, legal coaching and the preparation of agreements and legal documents. Emily Varga is a co-founding partner, and the team page also names Holly McCord Lonseth, Suman Parmar, Tanisha Smith, Anne Marie Harrison, Danijela Radinovic, Caleigh Hunt, Hannah Grant and Kamiko Bosch. The firm describes a compassionate approach to emotionally charged family matters and has an office on 4 Street SW.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('berard-avocats-montreal','Bérard Avocats','Montreal','QC','qc-montreal',0,4.7,61,45.5302654,-73.6080076,'{"name":"Bérard Avocats","city":"Montreal","featured":false,"tags":["Real Estate","Civil Litigation","Business Law"],"caseTypes":["realestate","litigation","business"],"region":"qc-montreal","province":"QC","lat":45.5302654,"lng":-73.6080076,"address":"6413 Boul. Saint-Laurent, Montréal, QC H2S 3C3","phone":"+14383751132","rating":4.7,"count":61,"slug":"berard-avocats-montreal","mapsUrl":"https://www.google.com/maps/search/B%C3%A9rard+Avocats+Montreal+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=6413+Boul.+Saint-Laurent%2C+Montr%C3%A9al%2C+QC+H2S+3C3","website":"https://berardavocats.com","blurb":"Real Estate / Civil Litigation in Montreal. Rated 4.7 from 61 Google reviews.","type":"logo","src":"images/logos/berard-avocats-montreal.png"}',NULL,'Bérard Avocats is a Montreal firm handling civil, commercial, real estate and construction law disputes, established in the city in 2016.

The firm''s site describes commercial disputes such as unpaid invoices and debts, missed deliveries by suppliers, difficulties with commercial leases and whether to incorporate, and says early legal advice can reduce the impact of such problems on a business. Its practice areas are listed as civil law, real estate law, construction law and commercial law, and it says it supports clients from diagnosis through to resolution of a file. The site also mentions a YouTube channel and refers to Me Bérard.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('j-kalirai-law-firm-mississauga','J. Kalirai Law Firm','Mississauga','ON','peel-halton',0,4.8,59,43.5912644,-79.636863,'{"name":"J. Kalirai Law Firm","city":"Mississauga","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.5912644,"lng":-79.636863,"address":"90 Burnhamthorpe Rd W #1400, Mississauga, ON L5B 3C3","phone":"+14372481234","rating":4.8,"count":59,"slug":"j-kalirai-law-firm-mississauga","mapsUrl":"https://www.google.com/maps/search/J.+Kalirai+Law+Firm+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=90+Burnhamthorpe+Rd+W+%231400%2C+Mississauga%2C+ON+L5B+3C3","website":"https://www.yourcriminallawyer.ca","blurb":"Criminal Defence in Mississauga. Rated 4.8 from 59 Google reviews.","type":"logo","src":"images/logos/j-kalirai-law-firm-mississauga.png"}',NULL,'Kalirai Law Firm is a Mississauga criminal defence firm covering drug, driving, assault and other offences, founded by lawyer Jeevan Kalirai.

The site lists arson, assault and related charges, drug offences under the Controlled Drugs and Substances Act and the Cannabis Act, impaired and dangerous driving, driving while disqualified, criminal harassment and criminal negligence causing death. Jeevan Kalirai holds an LL.B. (Honours) and a B.A. in Biomedical Sciences (Honours). The firm says it works at every level of court and offers flat fee pricing and flexible payment plans. The office is on Burnhamthorpe Road West.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('stephane-cote-real-estate-lawyer-avocat-ottawa','Stephane Cote Real Estate Lawyer/Avocat','Ottawa','ON','eastern',0,4.7,60,45.4653487,-75.5368183,'{"name":"Stephane Cote Real Estate Lawyer/Avocat","city":"Ottawa","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"eastern","province":"ON","lat":45.4653487,"lng":-75.5368183,"address":"2052 St Joseph Blvd, Ottawa, ON K1C 1E6","phone":"+16137144641","rating":4.7,"count":60,"slug":"stephane-cote-real-estate-lawyer-avocat-ottawa","mapsUrl":"https://www.google.com/maps/search/Stephane+Cote+Real+Estate+Lawyer%2FAvocat+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2052+St+Joseph+Blvd%2C+Ottawa%2C+ON+K1C+1E6","website":"https://scotelaw.com","blurb":"Real Estate / Wills & Estates in Ottawa. Rated 4.7 from 60 Google reviews.","type":"logo","src":"images/logos/stephane-cote-real-estate-lawyer-avocat-ottawa.png"}',NULL,'Stephane Cote Real Estate Lawyer/Avocat is a legal practice in Ottawa, Ontario, listed under real estate and wills and estates. The directory records its office at 2052 St Joseph Boulevard, and the practice name pairs the English word lawyer with the French avocat. The firm''s own website text could not be read when this entry was prepared, so no further detail about its lawyers, languages or services is stated here.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('chandler-law-kelowna','Chandler Law','Kelowna','BC','bc-okanagan',0,4.9,57,49.8848373,-119.4952968,'{"name":"Chandler Law","city":"Kelowna","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-okanagan","province":"BC","lat":49.8848373,"lng":-119.4952968,"address":"1630 Pandosy St #402, Kelowna, BC V1Y 1P7","phone":"+12507624415","rating":4.9,"count":57,"slug":"chandler-law-kelowna","mapsUrl":"https://www.google.com/maps/search/Chandler+Law+Kelowna+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1630+Pandosy+St+%23402%2C+Kelowna%2C+BC+V1Y+1P7","website":"https://www.chandlerlaw.ca","blurb":"Family Law in Kelowna. Rated 4.9 from 57 Google reviews.","type":"logo","src":"images/logos/chandler-law-kelowna.png"}',NULL,'Chandler Law is a Kelowna family law firm advising on separation, divorce, parenting, support and property division.

John Chandler, the founding partner, holds a B.A. and LL.B. and represents clients throughout the Okanagan and across British Columbia, preferring resolution where possible but prepared to go to trial. The firm also prepares cohabitation, prenuptial or marriage, and separation agreements and assists with mediation and negotiated settlements. Parenting arrangements, child and spousal support, and division of property and debt are among the issues it names. Chantelle A., a legal assistant and office manager who has worked in the legal field since 2018, keeps the office running.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('brum-immigration-ottawa','Brum Immigration','Ottawa','ON','eastern',0,5,55,45.3846125,-75.6730117,'{"name":"Brum Immigration","city":"Ottawa","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"eastern","province":"ON","lat":45.3846125,"lng":-75.6730117,"address":"1376 Bank St #308, Ottawa, ON K1H 7Y3","phone":"+16133020001","rating":5,"count":55,"slug":"brum-immigration-ottawa","mapsUrl":"https://www.google.com/maps/search/Brum+Immigration+Ottawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1376+Bank+St+%23308%2C+Ottawa%2C+ON+K1H+7Y3","website":"https://brumimmigration.ca","blurb":"Immigration in Ottawa. Rated 5.0 from 55 Google reviews.","type":"logo","src":"images/logos/brum-immigration-ottawa.png"}',NULL,'Brum Immigration is an Ottawa practice led by Renata Brum, a former Senior Citizenship Judge of Canada and Regulated Canadian Immigration Consultant.

The site says Brum served for 11 years as a citizenship judge, was born in the Azores, Portugal, and limits the practice to a select number of clients so that every case is managed personally. Applications it names include provincial nominee programs, Canadian citizenship, citizenship waivers on compassionate grounds and the Citizenship Act subsection 5(4) route. The firm also lists services for business clients moving workers to Canada and has begun offering US immigration services.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sunny-kaler-law-abbotsford','Sunny Kaler Law','Abbotsford','BC','bc-fraser',0,5,55,49.0689579,-122.3595413,'{"name":"Sunny Kaler Law","city":"Abbotsford","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"bc-fraser","province":"BC","lat":49.0689579,"lng":-122.3595413,"address":"3710 Townline Rd #110, Abbotsford, BC V2T 0G6","phone":"+16048325712","rating":5,"count":55,"slug":"sunny-kaler-law-abbotsford","mapsUrl":"https://www.google.com/maps/search/Sunny+Kaler+Law+Abbotsford+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=3710+Townline+Rd+%23110%2C+Abbotsford%2C+BC+V2T+0G6","website":"https://www.sunnykalerlaw.ca","blurb":"Criminal Defence in Abbotsford. Rated 5.0 from 55 Google reviews.","type":"logo","src":"images/logos/sunny-kaler-law-abbotsford.png"}',NULL,'Sunny Kaler Law is a criminal defence practice in Abbotsford, British Columbia. The firm''s website currently carries only a notice that the site is under construction, along with the office address on Townline Road in Abbotsford. No further details about its lawyers, services or court experience are published there, so this entry is limited to the firm''s name, location and listed practice area of criminal defence.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mincher-koeman-law-chambers-calgary','Mincher Koeman Law Chambers','Calgary','AB','ab-calgary',0,4.8,56,51.0465931,-114.0766913,'{"name":"Mincher Koeman Law Chambers","city":"Calgary","featured":false,"tags":["Family Law","Wills & Estates","Real Estate"],"caseTypes":["family","wills","realestate"],"region":"ab-calgary","province":"AB","lat":51.0465931,"lng":-114.0766913,"address":"707 7 Ave SW #1300, Calgary, AB T2P 3H6","phone":"+14039103000","rating":4.8,"count":56,"slug":"mincher-koeman-law-chambers-calgary","mapsUrl":"https://www.google.com/maps/search/Mincher+Koeman+Law+Chambers+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=707+7+Ave+SW+%231300%2C+Calgary%2C+AB+T2P+3H6","website":"https://familylawyerab.com","blurb":"Family Law / Wills & Estates in Calgary. Rated 4.8 from 56 Google reviews.","type":"logo","src":"images/logos/mincher-koeman-law-chambers-calgary.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Mincher Koeman Law Chambers is a Calgary family law practice with a Canmore presence, handling divorce, custody and property matters.

The firm''s website describes work that runs from simple desk divorces to complex custody and property cases, with separate sections for mediation and arbitration, parenting and guardianship, and fertility and surrogacy. It also names real estate, wills and estates, criminal law and Indigenous law among the matters its team takes on. Lawyer Andrew Koeman is named on the site, which also covers Alberta''s new family law procedure for 2026 and the Family Focused Protocol. The firm says it works as a collaborative team and draws on decades of combined experience with families and individuals.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hnt-law-guelph','HNT Law','Guelph','ON','waterloo-guelph',0,4.9,54,43.4942797,-80.2222848,'{"name":"HNT Law","city":"Guelph","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"waterloo-guelph","province":"ON","lat":43.4942797,"lng":-80.2222848,"address":"350 Hanlon Creek Boulevard Unit 108, Guelph, ON N1C 1B9","phone":"+15198304699","rating":4.9,"count":54,"slug":"hnt-law-guelph","mapsUrl":"https://www.google.com/maps/search/HNT+Law+Guelph+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=350+Hanlon+Creek+Boulevard+Unit+108%2C+Guelph%2C+ON+N1C+1B9","website":"https://www.hntlaw.ca","blurb":"Real Estate in Guelph. Rated 4.9 from 54 Google reviews.","type":"logo","src":"images/logos/hnt-law-guelph.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','HNT Law is a Guelph firm handling residential real estate purchases, sales and refinancing, along with wills and estate planning for Ontario clients.

According to its website, the firm analyzes paperwork, performs title searches and prepares the legal documents needed when a client buys or sells a home. Founder Hai Tran also teaches as an Assistant Professor of Law at the University of Guelph, with courses that range from Real Estate Law to Canadian Business Law. On the estates side, the firm says it has guided hundreds of clients through wills, powers of attorney and related planning. Its site is titled as serving both Guelph and Toronto.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('randy-norris-mississauga','Randy Norris','Mississauga','ON','peel-halton',0,4.8,55,43.5972299,-79.6360033,'{"name":"Randy Norris","city":"Mississauga","featured":false,"tags":["Criminal Defence","Civil Litigation"],"caseTypes":["criminal","litigation"],"region":"peel-halton","province":"ON","lat":43.5972299,"lng":-79.6360033,"address":"4 Robert Speck Pkwy #1500, Mississauga, ON L4Z 1S1","phone":"+19053664354","rating":4.8,"count":55,"slug":"randy-norris-mississauga","mapsUrl":"https://www.google.com/maps/search/Randy+Norris+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=4+Robert+Speck+Pkwy+%231500%2C+Mississauga%2C+ON+L4Z+1S1","website":"https://www.mississaugacriminaldefencelawyers.com","blurb":"Criminal Defence / Civil Litigation in Mississauga. Rated 4.8 from 55 Google reviews.","type":"logo","src":"images/logos/randy-norris-mississauga.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Randy Norris is a Mississauga criminal defence lawyer and former Crown Attorney who defends serious charges in Mississauga, Brampton and Peel Region.

A graduate of Osgoode Hall Law School, he began as a Crown Attorney in 1994 and moved into private practice in 1999. His website lists sexual assault, domestic assault, child pornography, theft and fraud, youth matters and impaired driving as the charges he regularly defends. The site also explains release conditions, bail terms and disclosure for people who have just been charged. His office is in Mississauga, and the structured data on the site names Mississauga, Brampton and Ontario as the areas served.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('share-lawyers-calgary-calgary','Share Lawyers Calgary','Calgary','AB','ab-calgary',0,4.9,53,51.0495031,-114.0734208,'{"name":"Share Lawyers Calgary","city":"Calgary","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"ab-calgary","province":"AB","lat":51.0495031,"lng":-114.0734208,"address":"330 5 St SW Ste 1800, Calgary, AB T2P 0J4","phone":"+15878033049","rating":4.9,"count":53,"slug":"share-lawyers-calgary-calgary","mapsUrl":"https://www.google.com/maps/search/Share+Lawyers+Calgary+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=330+5+St+SW+Ste+1800%2C+Calgary%2C+AB+T2P+0J4","website":"https://sharelawyers.com","blurb":"Employment Law in Calgary. Rated 4.9 from 53 Google reviews.","type":"logo","src":"images/logos/share-lawyers-calgary-calgary.png"}',NULL,'Share Lawyers, listed in Calgary, is a long-term disability insurance practice whose website describes a Toronto base and service across Canada.

According to the firm, it opened in 1987 and has focused on denied and delayed disability claims, both employee group benefits and privately purchased coverage. Its pages name insurers such as Manulife, Sun Life, Canada Life, OTIP, Desjardins and Blue Cross, and say the firm has helped more than 10,000 people pursue benefits. Co-founder David Share has practised since 1985 and taught trial advocacy at Osgoode Hall Law School. Other lawyers named on the site include Steven Muller, Samantha Share and Janice E. Grevler.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kaysi-fagan-calgary','Kaysi Fagan','Calgary','AB','ab-calgary',0,4.9,53,51.0419048,-114.0660506,'{"name":"Kaysi Fagan","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.0419048,"lng":-114.0660506,"address":"1117 1 St SW #202, Calgary, AB T2R 0T9","phone":"+10351717773","rating":4.9,"count":53,"slug":"kaysi-fagan-calgary","mapsUrl":"https://www.google.com/maps/search/Kaysi+Fagan+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1117+1+St+SW+%23202%2C+Calgary%2C+AB+T2R+0T9","website":"https://kaysifagan.com","blurb":"Criminal Defence in Calgary. Rated 4.9 from 53 Google reviews.","type":"logo","src":"images/logos/kaysi-fagan-calgary.webp"}',NULL,'Kaysi Fagan is a Calgary criminal defence lawyer who represents people charged with offences ranging from minor theft to first-degree murder.

Her website says she has defended prosecutions at every level of court in Alberta and across Canada, including the Supreme Court of Canada. Her listed credentials are a Master of Laws, a Juris Doctor and an honours Bachelor of Arts, and the site notes that she was formerly based at the headquarters of the International Police organization, INTERPOL. The office is on First Street SW in downtown Calgary. The site presents her as a sole practitioner, with sample cases and a profile of her background.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('wyman-and-williamson-criminal-defence-lawyers-calgary','Wyman & Williamson Criminal Defence Lawyers','Calgary','AB','ab-calgary',0,5,51,51.0465571,-114.0756951,'{"name":"Wyman & Williamson Criminal Defence Lawyers","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.0465571,"lng":-114.0756951,"address":"645 7 Ave SW #2650, Calgary, AB T2P 4G8","phone":"+15873168733","rating":5,"count":51,"slug":"wyman-and-williamson-criminal-defence-lawyers-calgary","mapsUrl":"https://www.google.com/maps/search/Wyman+%26+Williamson+Criminal+Defence+Lawyers+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=645+7+Ave+SW+%232650%2C+Calgary%2C+AB+T2P+4G8","website":"https://criminallawyercalgary.ca","blurb":"Criminal Defence in Calgary. Rated 5.0 from 51 Google reviews.","type":"logo","src":"images/logos/wyman-and-williamson-criminal-defence-lawyers-calgary.png"}','{"1":[["08:00","17:00"]],"2":[["08:00","17:00"]],"3":[["08:00","17:00"]],"4":[["08:00","17:00"]],"5":[["08:00","17:00"]]}','Wyman & Williamson is a Calgary criminal defence firm that handles only Criminal Code prosecutions, with a focus on sexual assault and impaired driving.

The firm says its lawyers act at all levels of court in Alberta, have made several appearances before the Supreme Court of Canada, and take cases throughout Western Canada. Its pages explain domestic assault matters, including the conditions police impose barring communication after a domestic incident, and cover simple and aggravated assault, threats and bail conditions. The website also describes the consequences of a sexual assault conviction, among them possible incarceration and registration on the sex offender registry. Its Calgary office sits on Seventh Avenue SW.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mccrea-immigration-law-vancouver','McCrea Immigration Law','Vancouver','BC','bc-vancouver',0,4.8,53,49.2802449,-123.1097316,'{"name":"McCrea Immigration Law","city":"Vancouver","featured":false,"tags":["Immigration"],"caseTypes":["immigration"],"region":"bc-vancouver","province":"BC","lat":49.2802449,"lng":-123.1097316,"address":"560 Beatty St #205, Vancouver, BC V6B 2L3","phone":"+16046628200","rating":4.8,"count":53,"slug":"mccrea-immigration-law-vancouver","mapsUrl":"https://www.google.com/maps/search/McCrea+Immigration+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=560+Beatty+St+%23205%2C+Vancouver%2C+BC+V6B+2L3","website":"https://www.mccrealaw.ca","blurb":"Immigration in Vancouver. Rated 4.8 from 53 Google reviews.","type":"logo","src":"images/logos/mccrea-immigration-law-vancouver.png"}',NULL,'McCrea Immigration Law is a Vancouver firm advising on work permits, permanent residence, citizenship and corporate immigration.

The firm says it has worked only in Canadian immigration law for more than three decades, and that its lawyers came from not-for-profit organizations and global law firms. Its site describes a plain-spoken style that turns legal language into practical advice, with the same attention given to a large corporation as to an individual applicant. The practice offers anything from a single narrow step to a full program of applications, and also assists clients dealing with audits. Its office is on Beatty Street in Vancouver, British Columbia.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bulwark-law-criminal-defence-lawyer-calgary','Bulwark Law Criminal Defence Lawyer','Calgary','AB','ab-calgary',0,5,50,51.0480411,-114.0754221,'{"name":"Bulwark Law Criminal Defence Lawyer","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.0480411,"lng":-114.0754221,"address":"630 6 Ave SW #520, Calgary, AB T2P 0S8","phone":"+15873272547","rating":5,"count":50,"slug":"bulwark-law-criminal-defence-lawyer-calgary","mapsUrl":"https://www.google.com/maps/search/Bulwark+Law+Criminal+Defence+Lawyer+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=630+6+Ave+SW+%23520%2C+Calgary%2C+AB+T2P+0S8","website":"https://bulwarklaw.ca","blurb":"Criminal Defence in Calgary. Rated 5.0 from 50 Google reviews.","type":"logo","src":"images/logos/bulwark-law-criminal-defence-lawyer-calgary.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]],"6":[["09:00","17:00"]],"7":[["09:00","17:00"]]}','Bulwark Law Criminal Defence is a Calgary firm handling assault, bail, driving offences, financial crime and murder and manslaughter charges across Alberta.

Owner Jeremy Newton obtained his law degree in 2011, worked first as a generalist, and then spent more than ten years as a Federal Prosecutor on cases across Alberta, where he also trained police and correctional officers. The firm''s site says he took a case to the Supreme Court of Canada, and recalls that his father was a criminal defence lawyer. Bulwark Law has offices in Calgary and Airdrie, and its pages describe each area of practice in turn.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gurpreet-ghag-law-group-vancouver','Gurpreet Ghag Law Group','Vancouver','BC','bc-vancouver',0,4.9,51,49.2263684,-123.0909496,'{"name":"Gurpreet Ghag Law Group","city":"Vancouver","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"bc-vancouver","province":"BC","lat":49.2263684,"lng":-123.0909496,"address":"6405 Fraser St #200, Vancouver, BC V5W 3A6","phone":"+17789569871","rating":4.9,"count":51,"slug":"gurpreet-ghag-law-group-vancouver","mapsUrl":"https://www.google.com/maps/search/Gurpreet+Ghag+Law+Group+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=6405+Fraser+St+%23200%2C+Vancouver%2C+BC+V5W+3A6","website":"https://www.ghaglaw.com","blurb":"Wills & Estates in Vancouver. Rated 4.9 from 51 Google reviews.","type":"logo","src":"images/logos/gurpreet-ghag-law-group-vancouver.jpg"}',NULL,'Gurpreet Ghag Law Group is a boutique Vancouver firm whose website centres on real estate law, with family and criminal law also named.

Its real estate pages describe buying and selling transactions, drafting purchase and sale agreements, title searches, and representation of buyers and sellers in residential and commercial deals. Other listed services include landlord and tenant matters such as leases and eviction proceedings, property development and finance, real estate investment, litigation and dispute resolution, planning and zoning, and notarial service. The firm''s office is on Fraser Street in Vancouver, British Columbia.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pav-singh-criminal-lawyer-mississauga','Pav Singh Criminal Lawyer','Mississauga','ON','peel-halton',0,4.9,51,43.6181961,-79.6732124,'{"name":"Pav Singh Criminal Lawyer","city":"Mississauga","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"peel-halton","province":"ON","lat":43.6181961,"lng":-79.6732124,"address":"90 Matheson Blvd W Ste 101, Mississauga, ON L5R 3R3","phone":"+14169022002","rating":4.9,"count":51,"slug":"pav-singh-criminal-lawyer-mississauga","mapsUrl":"https://www.google.com/maps/search/Pav+Singh+Criminal+Lawyer+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=90+Matheson+Blvd+W+Ste+101%2C+Mississauga%2C+ON+L5R+3R3","website":"https://www.lawpsk.com","blurb":"Criminal Defence in Mississauga. Rated 4.9 from 51 Google reviews.","type":"logo","src":"images/logos/pav-singh-criminal-lawyer-mississauga.png"}',NULL,'Pav Singh is a Mississauga criminal defence lawyer who represents clients across Peel Region, Toronto and surrounding areas.

His website says he completed a Bachelor of Arts in Criminal Justice at Ryerson University, a law degree at the University of Leicester, and a Master of Laws at Osgoode Hall Law School. The site states that his personal line is answered around the clock, every day of the year, and that evening, weekend and out-of-office meetings are available. Fees are quoted upfront, with block fee and hourly options and payment plans. His office is on Matheson Boulevard West in Mississauga, Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('campbell-litigation-waterloo','Campbell Litigation','Waterloo','ON','waterloo-guelph',0,4.8,51,43.4993976,-80.5353302,'{"name":"Campbell Litigation","city":"Waterloo","featured":false,"tags":["Personal Injury","Civil Litigation"],"caseTypes":["injury","litigation"],"region":"waterloo-guelph","province":"ON","lat":43.4993976,"lng":-80.5353302,"address":"40 Durward Pl, Waterloo, ON N2L 4E4","phone":"+15198861204","rating":4.8,"count":51,"slug":"campbell-litigation-waterloo","mapsUrl":"https://www.google.com/maps/search/Campbell+Litigation+Waterloo+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=40+Durward+Pl%2C+Waterloo%2C+ON+N2L+4E4","website":"https://petkerlaw.com","blurb":"Personal Injury / Civil Litigation in Waterloo. Rated 4.8 from 51 Google reviews.","type":"logo","src":"images/logos/campbell-litigation-waterloo.png"}',NULL,'Campbell Litigation is a Waterloo practice handling personal injury, wrongful death and commercial and construction disputes in Kitchener-Waterloo.

Lawyer Richard Campbell has litigated since 1999, working mainly for plaintiffs in personal injury, professional negligence, product liability, secured creditors'' remedies and contract matters. He holds a Bachelor of Arts from St. Jerome''s College and a Juris Doctor from Osgoode Hall Law School, and conducts trials and appeals in the Ontario courts. The site says he advises early on whether a dispute can be mediated, arbitrated or negotiated before litigation. Its articles cover fiduciary duty in closely held companies and ATV accidents.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('hoogbruin-and-company-vancouver','Hoogbruin & Company','Vancouver','BC','bc-vancouver',0,4.9,49,49.2861578,-123.1256058,'{"name":"Hoogbruin & Company","city":"Vancouver","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"bc-vancouver","province":"BC","lat":49.2861578,"lng":-123.1256058,"address":"1166 Alberni St Suite 1604, Vancouver, BC V6E 3Z3","phone":"+16046093783","rating":4.9,"count":49,"slug":"hoogbruin-and-company-vancouver","mapsUrl":"https://www.google.com/maps/search/Hoogbruin+%26+Company+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1166+Alberni+St+Suite+1604%2C+Vancouver%2C+BC+V6E+3Z3","website":"https://www.hoogbruin.com","blurb":"Personal Injury in Vancouver. Rated 4.9 from 49 Google reviews.","type":"logo","src":"images/logos/hoogbruin-and-company-vancouver.webp"}',NULL,'Hoogbruin & Company is a Vancouver litigation firm handling strata, real estate and commercial disputes, along with injury and wrongful death claims.

The firm''s website says it has taken on cases across British Columbia since 1987. Its practice pages cover strata corporations, strata owners and tenants, real estate litigation, commercial litigation, wills and estates, slip, trip and fall injuries, medical malpractice and wrongful death. Lawyers named on the site are Michael Hoogbruin, Arsen Krekovic and Abraham An. Its about page describes how injuries can affect work, family and mental health, and sets out the fee structure the firm uses. The office is on Alberni Street in downtown Vancouver.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('white-and-jeet-criminal-defence-calgary','White & Jeet Criminal Defence','Calgary','AB','ab-calgary',0,4.9,49,51.080931,-114.0311377,'{"name":"White & Jeet Criminal Defence","city":"Calgary","featured":false,"tags":["Criminal Defence"],"caseTypes":["criminal"],"region":"ab-calgary","province":"AB","lat":51.080931,"lng":-114.0311377,"address":"1212 31 Ave NE Ste 202, Calgary, AB T2E 7S8","phone":"+15877411351","rating":4.9,"count":49,"slug":"white-and-jeet-criminal-defence-calgary","mapsUrl":"https://www.google.com/maps/search/White+%26+Jeet+Criminal+Defence+Calgary+Alberta","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1212+31+Ave+NE+Ste+202%2C+Calgary%2C+AB+T2E+7S8","website":"https://whitejeetlaw.com","blurb":"Criminal Defence in Calgary. Rated 4.9 from 49 Google reviews.","type":"logo","src":"images/logos/white-and-jeet-criminal-defence-calgary.webp"}',NULL,'White & Jeet Criminal Defence is a Calgary team of criminal lawyers with offices in Lethbridge, Medicine Hat and Red Deer, serving all of Alberta.

The firm''s website sets out practice areas that include violent and serious charges, sexual assault, murder and homicide, drug and controlled substance offences, financial and complex matters, and criminal driving offences. It also explains administration of justice offences, such as breaches of release conditions or probation under section 145 of the Criminal Code. The firm says its work runs from early investigation and bail hearings through trial, appeals and post-conviction matters, and it operates a round-the-clock help line.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bergel-magence-guelph','Bergel Magence','Guelph','ON','waterloo-guelph',0,4.9,49,43.5438833,-80.24895,'{"name":"Bergel Magence","city":"Guelph","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"waterloo-guelph","province":"ON","lat":43.5438833,"lng":-80.24895,"address":"24 Carden St Ste 300A, Guelph, ON N1H 3A2","phone":"+18664923743","rating":4.9,"count":49,"slug":"bergel-magence-guelph","mapsUrl":"https://www.google.com/maps/search/Bergel+Magence+Guelph+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=24+Carden+St+Ste+300A%2C+Guelph%2C+ON+N1H+3A2","website":"https://www.bergellaw.com","blurb":"Personal Injury in Guelph. Rated 4.9 from 49 Google reviews.","type":"logo","src":"images/logos/bergel-magence-guelph.webp"}','{"1":[["00:00","23:59"]],"2":[["00:00","23:59"]],"3":[["00:00","23:59"]],"4":[["00:00","23:59"]],"5":[["00:00","23:59"]],"6":[["00:00","23:59"]],"7":[["00:00","23:59"]]}','Bergel Magence is a personal injury firm listed in Guelph, with a Toronto practice for catastrophically injured clients across Ontario.

According to the firm, it was founded in 1972 by Hy Bergel, a former Provincial Court Deputy Judge, and is now led by partners Andrew Bergel, Ilan Bergel and Jeremy Magence. Its pages cover car, motorcycle, truck, pedestrian and bicycle accidents, slip and fall claims, dog bites, medical malpractice and brain injuries. The site lists services in English, French, Hebrew, Russian, Persian, Italian, Spanish and Chinese, and describes the practice as a three-generation family business.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('onyx-law-group-vancouver','Onyx Law Group','Vancouver','BC','bc-vancouver',0,4.6,52,49.281898,-123.1179131,'{"name":"Onyx Law Group","city":"Vancouver","featured":false,"tags":["Family Law","Wills & Estates"],"caseTypes":["family","wills"],"region":"bc-vancouver","province":"BC","lat":49.281898,"lng":-123.1179131,"address":"650 W Georgia St #1215, Vancouver, BC V6B 4N8","phone":"+16043302207","rating":4.6,"count":52,"slug":"onyx-law-group-vancouver","mapsUrl":"https://www.google.com/maps/search/Onyx+Law+Group+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=650+W+Georgia+St+%231215%2C+Vancouver%2C+BC+V6B+4N8","website":"https://onyxlaw.ca","blurb":"Family Law / Wills & Estates in Vancouver. Rated 4.6 from 52 Google reviews.","type":"logo","src":"images/logos/onyx-law-group-vancouver.webp"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Onyx Law Group is a Vancouver boutique handling family law, divorce, and estate and trust litigation across Metro Vancouver.

The firm says it combines family and estate work, which lets it handle personal disputes that touch both areas. Its lead lawyers, Candace and Judith, are described as having more than twenty years of combined family and estate law experience, and the team also includes paralegals. Offices are listed in Vancouver, Burnaby and Surrey, and the site names Richmond, Coquitlam, North Vancouver, West Vancouver and New Westminster among places served. Its pages explain the British Columbia Family Law Act, property division and parenting rules, and describe flexible billing methods.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('osra-avocats-laval','Osra Avocats','Laval','QC','qc-laval-laurentides',0,4.9,48,45.5650398,-73.7243739,'{"name":"Osra Avocats","city":"Laval","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"qc-laval-laurentides","province":"QC","lat":45.5650398,"lng":-73.7243739,"address":"1555 Bd de l''Avenir #306, Laval, Quebec H7S 2N5","phone":"+18773492659","rating":4.9,"count":48,"slug":"osra-avocats-laval","mapsUrl":"https://www.google.com/maps/search/Osra+Avocats+Laval+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1555+Bd+de+l%27Avenir+%23306%2C+Laval%2C+Quebec+H7S+2N5","website":"https://www.osraavocats.com","blurb":"Family Law in Laval. Rated 4.9 from 48 Google reviews.","type":"logo","src":"images/logos/osra-avocats-laval.png"}',NULL,'Osra Avocats est un cabinet de Laval, in Quebec, that works mainly in family law across the greater Montreal region.

Its website lists contested and amicable divorces, separation, negotiated settlements, child custody, child and spousal support, changes to support orders, partition of the family patrimony and the partnership of acquests, safeguard measures and loss of parental authority. The firm says family law rests above all on human and psychological considerations, so each file is handled with attention to the client''s needs and expectations, with an emphasis on listening. Lawyer Me Wafa Ouafi is named on the site''s team page.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('oracle-law-vancouver','Oracle Law','Vancouver','BC','bc-vancouver',0,5,47,49.2806097,-123.1176899,'{"name":"Oracle Law","city":"Vancouver","featured":false,"tags":["Real Estate","Business Law"],"caseTypes":["realestate","business"],"region":"bc-vancouver","province":"BC","lat":49.2806097,"lng":-123.1176899,"address":"777 Richards St Suite 602, Vancouver, BC V6B 0M6","phone":"+16044428242","rating":5,"count":47,"slug":"oracle-law-vancouver","mapsUrl":"https://www.google.com/maps/search/Oracle+Law+Vancouver+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=777+Richards+St+Suite+602%2C+Vancouver%2C+BC+V6B+0M6","website":"https://oraclelaw.ca","blurb":"Real Estate / Business Law in Vancouver. Rated 5.0 from 47 Google reviews.","type":"logo","src":"images/logos/oracle-law-vancouver.png"}',NULL,'Oracle Law is a Vancouver firm handling real estate conveyancing, mortgage refinancing and corporate law, with flat-fee residential purchase and sale work.

Its website lists residential and strata purchases, commercial property purchases, family transfers and gifted property, and subdivisions. Lawyer Peter has more than ten years of experience, has run his own firm, and works alongside clients'' accountants, mortgage brokers and realtors when issues arise. He is fluent in Greek and serves clients in both English and Greek, and the site notes his involvement in the Greek Community of Greater Vancouver. The firm describes its pricing as transparent and its advice as practical.','dynamic','live',NULL);
