INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('vallillee-family-lawyers-london','Vallillee Family Lawyers','London','ON','southwestern',0,4.6,42,42.9856912,-81.2487404,'{"name":"Vallillee Family Lawyers","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9856912,"lng":-81.2487404,"address":"200 Queens Ave Ste 440, London, ON N6A 1J3","phone":"+15194885263","rating":4.6,"count":42,"slug":"vallillee-family-lawyers-london","mapsUrl":"https://www.google.com/maps/search/Vallillee+Family+Lawyers+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=200+Queens+Ave+Ste+440%2C+London%2C+ON+N6A+1J3","website":"https://www.valaw.ca","blurb":"Family Law in London. Rated 4.6 from 42 Google reviews.","type":"logo","src":"images/logos/vallillee-family-lawyers-london.png"}',NULL,'Vallillee Family Lawyers is a London, Ontario boutique handling separation, divorce, parenting, support, property and Children''s Aid Society matters.

