INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nichols-law-professional-corporation-markham','Nichols Law Professional Corporation','Markham','ON','york-durham',0,4.6,42,43.8799253,-79.2608577,'{"name":"Nichols Law Professional Corporation","city":"Markham","featured":false,"tags":["Real Estate","Wills & Estates","Business Law"],"caseTypes":["realestate","wills","business"],"region":"york-durham","province":"ON","lat":43.8799253,"lng":-79.2608577,"address":"161 Main Street Markham N, Markham, ON L3P 1Y2","phone":"+19052947780","rating":4.6,"count":42,"slug":"nichols-law-professional-corporation-markham","mapsUrl":"https://www.google.com/maps/search/Nichols+Law+Professional+Corporation+Markham+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=161+Main+Street+Markham+N%2C+Markham%2C+ON+L3P+1Y2","website":"https://www.markhamlaw.com","blurb":"Real Estate / Wills & Estates in Markham. Rated 4.6 from 42 Google reviews.","type":"logo","src":"images/logos/nichols-law-professional-corporation-markham.png"}',NULL,'Nichols Law Professional Corporation is a Markham firm covering real estate, wills, powers of attorney, business law and notary services.

