INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('family-lawyers-collective-llp-london','Family Lawyers Collective LLP','London','ON','southwestern',0,4.8,40,42.9856912,-81.2487404,'{"name":"Family Lawyers Collective LLP","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9856912,"lng":-81.2487404,"address":"200 Queens Ave Ste 301, London, ON N6A 1J3","phone":"+12267853130","rating":4.8,"count":40,"slug":"family-lawyers-collective-llp-london","mapsUrl":"https://www.google.com/maps/search/Family+Lawyers+Collective+LLP+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=200+Queens+Ave+Ste+301%2C+London%2C+ON+N6A+1J3","website":"https://flco.ca","blurb":"Family Law in London. Rated 4.8 from 40 Google reviews.","type":"logo","src":"images/logos/family-lawyers-collective-llp-london.png"}',NULL,'Family Lawyers Collective LLP is a London, Ontario family law firm covering separation, divorce, parenting time, property division and domestic contracts.

