INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('nora-law-professional-corporation-london','Nora Law Professional Corporation','London','ON','southwestern',0,4.9,39,42.9811124,-81.2511519,'{"name":"Nora Law Professional Corporation","city":"London","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"southwestern","province":"ON","lat":42.9811124,"lng":-81.2511519,"address":"341 Talbot St, London, ON N6A 2R5","phone":"+15192000065","rating":4.9,"count":39,"slug":"nora-law-professional-corporation-london","mapsUrl":"https://www.google.com/maps/search/Nora+Law+Professional+Corporation+London+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=341+Talbot+St%2C+London%2C+ON+N6A+2R5","website":"https://www.noralaw.ca","blurb":"Family Law in London. Rated 4.9 from 39 Google reviews.","type":"logo","src":"images/logos/nora-law-professional-corporation-london.png"}',NULL,'Nora Law Professional Corporation is a London, Ontario firm covering family, immigration and refugee, child protection and business law.

