INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('maam-law-mississauga','Maam Law','Mississauga','ON','peel-halton',0,5,38,43.5923772,-79.6380369,'{"name":"Maam Law","city":"Mississauga","featured":false,"tags":["Real Estate"],"caseTypes":["realestate"],"region":"peel-halton","province":"ON","lat":43.5923772,"lng":-79.6380369,"address":"east Tower, 77 City Centre Dr Ste 501, Mississauga, ON L5B 1M5","phone":"+12898854786","rating":5,"count":38,"slug":"maam-law-mississauga","mapsUrl":"https://www.google.com/maps/search/Maam+Law+Mississauga+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=east+Tower%2C+77+City+Centre+Dr+Ste+501%2C+Mississauga%2C+ON+L5B+1M5","website":"https://maamlaw.com","blurb":"Real Estate in Mississauga. Rated 5.0 from 38 Google reviews.","type":"logo","src":"images/logos/maam-law-mississauga.webp"}',NULL,'Maam Law is a Mississauga firm offering family law, wills and powers of attorney, real estate, immigration, elder abuse prevention and notarization services.

