INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('pathfinder-law-abbotsford','Pathfinder Law','Abbotsford','BC','bc-fraser',0,5,37,49.0392256,-122.2937442,'{"name":"Pathfinder Law","city":"Abbotsford","featured":false,"tags":["Family Law","Civil Litigation"],"caseTypes":["family","litigation"],"region":"bc-fraser","province":"BC","lat":49.0392256,"lng":-122.2937442,"address":"2001 McCallum Rd #104, Abbotsford, BC V2S 3N3","phone":"+16048504685","rating":5,"count":37,"slug":"pathfinder-law-abbotsford","mapsUrl":"https://www.google.com/maps/search/Pathfinder+Law+Abbotsford+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2001+McCallum+Rd+%23104%2C+Abbotsford%2C+BC+V2S+3N3","website":"https://www.pathfinderlaw.ca","blurb":"Family Law / Civil Litigation in Abbotsford. Rated 5.0 from 37 Google reviews.","type":"logo","src":"images/logos/pathfinder-law-abbotsford.png"}',NULL,'Pathfinder Law is an Abbotsford firm handling family law, divorce, civil litigation, construction, employment, wills and business matters.

