INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('sirois-avocat-quebec-city','Sirois Avocat','Quebec City','QC','qc-quebec',0,4.9,37,46.7678109,-71.2888069,'{"name":"Sirois Avocat","city":"Quebec City","featured":false,"tags":["Immigration","Civil Litigation"],"caseTypes":["immigration","litigation"],"region":"qc-quebec","province":"QC","lat":46.7678109,"lng":-71.2888069,"address":"2828 Boul Laurier Bureaux 700, Québec City, Quebec G1V 0B9","phone":"+14185201036","rating":4.9,"count":37,"slug":"sirois-avocat-quebec-city","mapsUrl":"https://www.google.com/maps/search/Sirois+Avocat+Quebec+City+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=2828+Boul+Laurier+Bureaux+700%2C+Qu%C3%A9bec+City%2C+Quebec+G1V+0B9","website":"https://www.siroisavocat.com","blurb":"Immigration / Civil Litigation in Quebec City. Rated 4.9 from 37 Google reviews.","type":"logo","src":"images/logos/sirois-avocat-quebec-city.webp"}',NULL,'Sirois Avocat is a Quebec City firm practising immigration, business and civil law, founded in 2021 by Me Sirois.

He earned an LL.B. from Université Laval in 2019, has belonged to the Barreau du Québec since February 2020, and has focused on immigration in private practice. The firm says its approach rests on efficiency, personal service and information technology. Me Sirois received the 2021 firm start-up grant of the Jeune Barreau de Québec and has been a member of the Association québécoise des avocats et avocates en droit de l''immigration since 2020. He guides clients through temporary and permanent residence applications and helps entrepreneurs meet their legal obligations.','dynamic','live',NULL);
