INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('white-macgillivray-lester-llp-thunder-bay','White Macgillivray Lester LLP','Thunder Bay','ON','northern',0,4.9,82,48.4345565,-89.2194275,'{"name":"White Macgillivray Lester LLP","city":"Thunder Bay","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"northern","province":"ON","lat":48.4345565,"lng":-89.2194275,"address":"1 Cumberland St S, Thunder Bay, ON P7B 2T1","phone":"+18073441000","rating":4.9,"count":82,"slug":"white-macgillivray-lester-llp-thunder-bay","mapsUrl":"https://www.google.com/maps/search/White+Macgillivray+Lester+LLP+Thunder+Bay+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1+Cumberland+St+S%2C+Thunder+Bay%2C+ON+P7B+2T1","website":"https://www.tbayinjurylaw.com","blurb":"Personal Injury in Thunder Bay. Rated 4.9 from 82 Google reviews.","type":"logo","src":"images/logos/white-macgillivray-lester-llp-thunder-bay.png"}',NULL,'White Macgillivray Lester LLP is a Thunder Bay personal injury firm serving clients across Northwestern Ontario.

