INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('miskin-law-peterborough','Miskin Law','Peterborough','ON','simcoe-central',0,4.6,75,44.3028218,-78.3286273,'{"name":"Miskin Law","city":"Peterborough","featured":false,"tags":["Personal Injury","Real Estate","Wills & Estates"],"caseTypes":["injury","realestate","wills"],"region":"simcoe-central","province":"ON","lat":44.3028218,"lng":-78.3286273,"address":"351 Charlotte St, Peterborough, ON K9J 2W1","phone":"+17057557363","rating":4.6,"count":75,"slug":"miskin-law-peterborough","mapsUrl":"https://www.google.com/maps/search/Miskin+Law+Peterborough+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=351+Charlotte+St%2C+Peterborough%2C+ON+K9J+2W1","website":"https://www.miskinlaw.ca","blurb":"Personal Injury / Real Estate in Peterborough. Rated 4.6 from 75 Google reviews.","type":"logo","src":"images/logos/miskin-law-peterborough.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Miskin Law is a Peterborough firm handling personal injury, asbestos and mesothelioma matters, class actions, real estate, corporate law and estates.

The site says the firm has served Canadians since 1981 and keeps offices in Peterborough, Toronto and Oshawa. Personal injury work is aimed at Ontario residents, while mesothelioma and class action matters are taken on for people across the country. It explains that mesothelioma compensation in Canada generally comes through asbestos trusts, and publishes articles on work history affidavits. Founder Murray Miskin is described as a plaintiff''s personal injury lawyer with more than 40 years of practice and involvement with the Canadian Bar Association and the ADR Institute of Canada. Injury cases are handled on contingency, and the firm also prepares wills and estate plans.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tlc-family-law-prince-george','TLC Family Law','Prince George','BC','bc-north',0,4.8,67,53.9199902,-122.7556322,'{"name":"TLC Family Law","city":"Prince George","featured":false,"tags":["Family Law"],"caseTypes":["family"],"region":"bc-north","province":"BC","lat":53.9199902,"lng":-122.7556322,"address":"1896 3rd Ave, Prince George, BC V2M 1G4","phone":"+12505633630","rating":4.8,"count":67,"slug":"tlc-family-law-prince-george","mapsUrl":"https://www.google.com/maps/search/TLC+Family+Law+Prince+George+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1896+3rd+Ave%2C+Prince+George%2C+BC+V2M+1G4","website":"https://www.tlc-law.ca","blurb":"Family Law in Prince George. Rated 4.8 from 67 Google reviews.","type":"logo","src":"images/logos/tlc-family-law-prince-george.webp"}',NULL,'TLC Family Law Practice is a Prince George firm handling divorce, parenting arrangements, support and property division under British Columbia family law.

According to its website, the practice also has offices in Parksville and serves the Nanaimo and Qualicum area. Tracy L. Clark is named as a family lawyer with over 30 years in practice. The firm says its primary aim is to settle matters by agreement quickly and efficiently, while taking cases to court when that is necessary. Listed services include flat fee agreements, uncontested divorces, guardianship, parenting time and access, child and spousal support, variation of existing orders, pension and property division, family debt, and cohabitation, marriage and prenuptial agreements.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('andrews-donnelly-llp-kingston','Andrews Donnelly LLP','Kingston','ON','eastern',0,4.7,66,44.2595867,-76.5203935,'{"name":"Andrews Donnelly LLP","city":"Kingston","featured":false,"tags":["Family Law","Civil Litigation"],"caseTypes":["family","litigation"],"region":"eastern","province":"ON","lat":44.2595867,"lng":-76.5203935,"address":"1471 John Counter Blvd #302, Kingston, ON K7M 8S8","phone":"+16135313032","rating":4.7,"count":66,"slug":"andrews-donnelly-llp-kingston","mapsUrl":"https://www.google.com/maps/search/Andrews+Donnelly+LLP+Kingston+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=1471+John+Counter+Blvd+%23302%2C+Kingston%2C+ON+K7M+8S8","website":"https://www.andrewsdonnellylaw.ca","blurb":"Family Law / Civil Litigation in Kingston. Rated 4.7 from 66 Google reviews.","type":"logo","src":"images/logos/andrews-donnelly-llp-kingston.png"}',NULL,'Andrews Donnelly LLP is a Kingston boutique firm handling family law, estate litigation and civil litigation.

The firm describes its dispute resolution services as available in Kingston, Frontenac County, Prince Edward County and surrounding areas, including Brockville, Napanee, Belleville and Picton. Family work covers custody, access, child and spousal support and division of property. Estate litigation covers will challenges, power of attorney disputes, capacity questions and the passing of fiduciary accounts. The site has profiles for lawyers Paul and Whitney, and says fees can be arranged as fixed-fee or project-based billing, hourly engagements, or monthly retainers.','dynamic','live',NULL);
