INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('de-bakker-law-thunder-bay','de Bakker Law','Thunder Bay','ON','northern',0,4.6,49,48.430023,-89.230954,'{"name":"de Bakker Law","city":"Thunder Bay","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"northern","province":"ON","lat":48.430023,"lng":-89.230954,"address":"217 Algoma St S, Thunder Bay, ON P7B 3C3","phone":"+18073452356","rating":4.6,"count":49,"slug":"de-bakker-law-thunder-bay","mapsUrl":"https://www.google.com/maps/search/de+Bakker+Law+Thunder+Bay+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=217+Algoma+St+S%2C+Thunder+Bay%2C+ON+P7B+3C3","website":"https://www.debakkerlaw.ca","blurb":"Law firm in Thunder Bay. Rated 4.6 from 49 Google reviews.","type":"logo","src":"images/logos/de-bakker-law-thunder-bay.webp"}',NULL,'de Bakker Law is a Thunder Bay firm handling real estate, wills and estates, criminal, civil litigation, corporate and immigration matters.

The site presents the practice as representing Thunder Bay with over 40 years of experience, and also lists medical malpractice among its services. Deborah de Bakker practises wills, estates and real estate alongside her son. She is described as a lifelong Thunder Bay resident with a B.A. from Queen''s University and an LL.B. from Osgoode Hall Law School, a member of the Law Society of Ontario and the Thunder Bay Law Association, and a past member of the federal Judicial Appointments Advisory Committee. The team page also names Vlad Popescu, Jennifer Hay, Jessica Macaulay and Carly Deboni.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('bakleh-avocats-and-associes-saint-jerome','Bakleh Avocats & Associés','Saint-Jerome','QC','qc-laval-laurentides',0,5,43,45.7760489,-74.002924,'{"name":"Bakleh Avocats & Associés","city":"Saint-Jerome","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"qc-laval-laurentides","province":"QC","lat":45.7760489,"lng":-74.002924,"address":"35 Rue de la Gare, Saint-Jérôme, QC J7Z 5A2","phone":"+15144308335","rating":5,"count":43,"slug":"bakleh-avocats-and-associes-saint-jerome","mapsUrl":"https://www.google.com/maps/search/Bakleh+Avocats+%26+Associ%C3%A9s+Saint-Jerome+Quebec","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=35+Rue+de+la+Gare%2C+Saint-J%C3%A9r%C3%B4me%2C+QC+J7Z+5A2","website":"https://baklehavocats.com","blurb":"Law firm in Saint-Jerome. Rated 5.0 from 43 Google reviews.","type":"logo","src":"images/logos/bakleh-avocats-and-associes-saint-jerome.png"}',NULL,'Bakleh Avocats & Associés is a Saint-Jerome firm working in criminal, penal, civil and real estate law, and it also contests traffic tickets.

Its website explains that the team helps drivers keep their demerit points and their licence when a ticket is contested, including tickets issued in Montreal. The firm also runs an immigration practice that pairs Me Charlis Bakleh with regulated immigration consultant Joseph Zakhour for study permits, work visas, permanent residence and status regularization, in Quebec, Ontario or remotely. Real estate law is listed among its practice areas. The site is in French.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('fazio-law-sarnia','Fazio Law','Sarnia','ON','southwestern',0,4.8,44,42.9847142,-82.3999695,'{"name":"Fazio Law","city":"Sarnia","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"southwestern","province":"ON","lat":42.9847142,"lng":-82.3999695,"address":"568 Christina St N, Sarnia, ON N7T 7X6","phone":"+15193440777","rating":4.8,"count":44,"slug":"fazio-law-sarnia","mapsUrl":"https://www.google.com/maps/search/Fazio+Law+Sarnia+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=568+Christina+St+N%2C+Sarnia%2C+ON+N7T+7X6","website":"https://faziolaw.net","blurb":"Law firm in Sarnia. Rated 4.8 from 44 Google reviews.","type":"logo","src":"images/logos/fazio-law-sarnia.jpg"}',NULL,'Fazio Law is a Sarnia firm that has handled real estate, business and estate matters since 1988 for individuals, families, charities and companies.

According to its website, the practice serves Sarnia and the surrounding area, from small businesses to large corporations, and covers estate planning, real estate transactions and corporate law. Frank Fazio was called to the Ontario bar in 1988 and has more than 37 years in practice. The site says he has served on boards in Sarnia-Lambton, including the YMCA, the Downtown Business Improvement Area, the Lung Association and the real estate section of the Lambton Law Association, and that the aim is to explain legal dealings in everyday English.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('simeson-law-oshawa','Simeson Law','Oshawa','ON','york-durham',0,4.8,42,43.8998278,-78.8599287,'{"name":"Simeson Law","city":"Oshawa","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"york-durham","province":"ON","lat":43.8998278,"lng":-78.8599287,"address":"100 Bond St E, Oshawa, ON L1G 0B7","phone":"+19055795302","rating":4.8,"count":42,"slug":"simeson-law-oshawa","mapsUrl":"https://www.google.com/maps/search/Simeson+Law+Oshawa+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=100+Bond+St+E%2C+Oshawa%2C+ON+L1G+0B7","website":"https://www.kslawfirm.ca","blurb":"Personal Injury in Oshawa. Rated 4.8 from 42 Google reviews.","type":"logo","src":"images/logos/simeson-law-oshawa.png"}',NULL,'Simeson Law LLP is an Oshawa firm handling personal injury, criminal defence, family and employment law matters.

The firm says it has acted for accident victims for over 35 years, in matters such as car, bicycle and boating accidents, brain injuries, catastrophic injury, slip and falls, animal attacks, medical malpractice, product liability, accident benefits, and disability, life and property insurance disputes. Its criminal practice covers Criminal Code, provincial and Highway Traffic Act offences, and employment pages address wrongful dismissal. Alastair H. Simeson is the partner in charge of litigation and a former president of the Oshawa Chamber of Commerce, and Sean M. Simeson is an associate lawyer.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('blfon-personal-injury-lawyer-north-bay','BLFON Personal Injury Lawyer','North Bay','ON','northern',0,5,38,46.308148,-79.459869,'{"name":"BLFON Personal Injury Lawyer","city":"North Bay","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"northern","province":"ON","lat":46.308148,"lng":-79.459869,"address":"437 Sherbrooke St, North Bay, ON P1B 2C2","phone":"+18005960743","rating":5,"count":38,"slug":"blfon-personal-injury-lawyer-north-bay","mapsUrl":"https://www.google.com/maps/search/BLFON+Personal+Injury+Lawyer+North+Bay+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=437+Sherbrooke+St%2C+North+Bay%2C+ON+P1B+2C2","website":"https://blfonlaw.ca","blurb":"Personal Injury in North Bay. Rated 5.0 from 38 Google reviews.","type":"logo","src":"images/logos/blfon-personal-injury-lawyer-north-bay.png"}',NULL,'BLFON Personal Injury Lawyer is a North Bay firm handling car accidents, slip and falls and other injury cases in Ontario.

The site describes offices in Sarnia, North Bay and Collingwood and identifies the firm as a member of Barapp Law Alliance. Listed practice areas include car accidents, orthopaedic injuries, slip and fall accidents, motorcycle accidents, public transit accidents and pedestrian accidents. It says it acts on a contingency fee basis, so clients pay legal fees only if the case succeeds. The about page names lawyers including Eric Barapp, Lorne Weinstock, Eti Taylor, Nabeel Sera, Michael Brill and Albert Wong.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('fallow-gould-llp-kingston','Fallow Gould LLP','Kingston','ON','eastern',0,5,37,44.242067,-76.480842,'{"name":"Fallow Gould LLP","city":"Kingston","featured":false,"tags":["Wills & Estates","Civil Litigation"],"caseTypes":["wills","litigation"],"region":"eastern","province":"ON","lat":44.242067,"lng":-76.480842,"address":"The Woolen Mill, 4 Cataraqui St #114, Kingston, ON K7K 1Z7","phone":"+16137660200","rating":5,"count":37,"slug":"fallow-gould-llp-kingston","mapsUrl":"https://www.google.com/maps/search/Fallow+Gould+LLP+Kingston+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=The+Woolen+Mill%2C+4+Cataraqui+St+%23114%2C+Kingston%2C+ON+K7K+1Z7","website":"https://www.fallowgould.ca","blurb":"Wills & Estates / Civil Litigation in Kingston. Rated 5.0 from 37 Google reviews.","type":"logo","src":"images/logos/fallow-gould-llp-kingston.png"}',NULL,'Fallow Gould LLP is a Kingston firm offering estate planning, estate administration, beneficiary guidance and estate litigation.

Its website describes the work as bespoke and carried out with discretion and precision, with the aim that a client''s legacy endures for generations. The firm is listed under wills and estates and civil litigation, and it operates from The Woolen Mill at 4 Cataraqui Street in Kingston, Ontario. The site offers little further detail beyond this summary of its estate work.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('osborne-law-group-st-catharines','Osborne Law Group','St. Catharines','ON','hamilton-niagara',0,4.8,36,43.1586812,-79.2413373,'{"name":"Osborne Law Group","city":"St. Catharines","featured":false,"tags":["Wills & Estates"],"caseTypes":["wills"],"region":"hamilton-niagara","province":"ON","lat":43.1586812,"lng":-79.2413373,"address":"5 Race St, St. Catharines, ON L2R 3M1","phone":"+19056889352","rating":4.8,"count":36,"slug":"osborne-law-group-st-catharines","mapsUrl":"https://www.google.com/maps/search/Osborne+Law+Group+St.+Catharines+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=5+Race+St%2C+St.+Catharines%2C+ON+L2R+3M1","website":"https://www.osbornelaw.ca","blurb":"Wills & Estates in St. Catharines. Rated 4.8 from 36 Google reviews.","type":"logo","src":"images/logos/osborne-law-group-st-catharines.png"}','{"1":[["09:00","17:00"]],"2":[["09:00","17:00"]],"3":[["09:00","17:00"]],"4":[["09:00","17:00"]],"5":[["09:00","17:00"]]}','Osborne Law Group focuses on Ontario probate applications, estate administration and wills, alongside real estate and corporate law, for Niagara residents.

Based at 5 Race Street in St. Catharines, the firm says it has over 17 years of practice and more than 3,500 clients served across its practice areas. Its site explains Certificates of Appointment of Estate Trustee with and without a will, Small Estate Certificates for estates under $150,000, and when a bank, investment firm or purchaser may ask for probate. Stephen Osborne is named as its probate and estate lawyer, and fixed-fee options are mentioned for eligible probate applications.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ain-whitehead-llp-barrie','Ain Whitehead LLP','Barrie','ON','simcoe-central',0,4.7,36,44.390831,-79.6898911,'{"name":"Ain Whitehead LLP","city":"Barrie","featured":false,"tags":["Real Estate","Wills & Estates"],"caseTypes":["realestate","wills"],"region":"simcoe-central","province":"ON","lat":44.390831,"lng":-79.6898911,"address":"27 Clapperton St, Barrie, ON L4M 3E6","phone":"+17057258171","rating":4.7,"count":36,"slug":"ain-whitehead-llp-barrie","mapsUrl":"https://www.google.com/maps/search/Ain+Whitehead+LLP+Barrie+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=27+Clapperton+St%2C+Barrie%2C+ON+L4M+3E6","website":"https://www.ainwhitehead.com","blurb":"Real Estate / Wills & Estates in Barrie. Rated 4.7 from 36 Google reviews.","type":"logo","src":"images/logos/ain-whitehead-llp-barrie.png"}',NULL,'Ain Whitehead LLP is a Barrie firm handling business, real estate and wills and estates law.

The site marks ten years of the practice and names lawyers Andrew Ain, Graydon Ebert, Jill Annett, Kathryn Whitehead and Tony Servello. Andrew''s work centres on residential real estate, mortgage lending and commercial transactions, with a focus on land development and condominium law, plus corporate matters such as new corporations, shareholder agreements and the buying and selling of businesses. Real estate pages cover commercial leasing, lease negotiation and drafting, and include a land transfer calculator. Areas mentioned include the City of Barrie and the Township of Springwater.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('lambert-boenders-employment-lawyer-toronto','Lambert Boenders Employment Lawyer','Toronto','ON','toronto',0,5,33,43.6516092,-79.3823093,'{"name":"Lambert Boenders Employment Lawyer","city":"Toronto","featured":false,"tags":["Employment Law"],"caseTypes":["employment"],"region":"toronto","province":"ON","lat":43.6516092,"lng":-79.3823093,"address":"65 Queen St W Ste 615, Toronto, ON M5H 2M8","phone":"+14165617323","rating":5,"count":33,"slug":"lambert-boenders-employment-lawyer-toronto","mapsUrl":"https://www.google.com/maps/search/Lambert+Boenders+Employment+Lawyer+Toronto+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=65+Queen+St+W+Ste+615%2C+Toronto%2C+ON+M5H+2M8","website":"https://www.employmentlawcounsel.ca","blurb":"Employment Law in Toronto. Rated 5.0 from 33 Google reviews.","type":"logo","src":"images/logos/lambert-boenders-employment-lawyer-toronto.png"}',NULL,'Lambert Boenders is a Toronto employment and human rights law practice that advises both employees and employers on termination and workplace issues.

The site says Lambert earned a B.A. (Hons) from Victoria College at the University of Toronto and a J.D. from Osgoode Hall Law School in 1994, entered employment and human rights practice in 2009 and was called to the Ontario bar in 2010. Before practising law he worked for more than twenty-five years in business, including as Vice-President of Operations with an international insurance company. Listed services include reviewing employment offer letters and contracts, performance management and improvement issues, and non-solicitation and non-competition clauses. The office is on Queen Street West.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('ewen-boyd-llp-barrie','Ewen Boyd LLP','Barrie','ON','simcoe-central',0,4.8,32,44.3696871,-79.7082797,'{"name":"Ewen Boyd LLP","city":"Barrie","featured":false,"tags":["Family Law","Real Estate","Wills & Estates"],"caseTypes":["family","realestate","wills"],"region":"simcoe-central","province":"ON","lat":44.3696871,"lng":-79.7082797,"address":"11 Patterson Rd #24, Barrie, ON L4N 7W5","phone":"+17052526730","rating":4.8,"count":32,"slug":"ewen-boyd-llp-barrie","mapsUrl":"https://www.google.com/maps/search/Ewen+Boyd+LLP+Barrie+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=11+Patterson+Rd+%2324%2C+Barrie%2C+ON+L4N+7W5","website":"https://www.ewenboyd.com","blurb":"Family Law / Real Estate in Barrie. Rated 4.8 from 32 Google reviews.","type":"logo","src":"images/logos/ewen-boyd-llp-barrie.webp"}',NULL,'Ewen Boyd LLP is a Barrie firm that handled family, real estate, wills and estate planning and corporate law, and has announced that it is closing.

The firm''s website says that after more than eleven years of service it will close its doors in the near future, and that it no longer holds any wills or powers of attorney, which have been transferred to Ness Law in Orillia. Before the closure notice, its site described help across Simcoe County and Muskoka. Former clients who need a closed real estate or family file are directed to a mailing address in Barrie.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('murray-and-associates-llp-st-catharines','Murray & Associates LLP','St. Catharines','ON','hamilton-niagara',0,4.7,31,43.1576581,-79.2489043,'{"name":"Murray & Associates LLP","city":"St. Catharines","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"hamilton-niagara","province":"ON","lat":43.1576581,"lng":-79.2489043,"address":"14 Church, St. Catharines, ON L2R 3B3","phone":"+19056878200","rating":4.7,"count":31,"slug":"murray-and-associates-llp-st-catharines","mapsUrl":"https://www.google.com/maps/search/Murray+%26+Associates+LLP+St.+Catharines+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=14+Church%2C+St.+Catharines%2C+ON+L2R+3B3","website":"https://www.murlaw.ca","blurb":"Law firm in St. Catharines. Rated 4.7 from 31 Google reviews.","type":"logo","src":"images/logos/murray-and-associates-llp-st-catharines.jpg"}',NULL,'Murray & Associates LLP is a Niagara Region firm covering real estate, wills and estates, corporate, mortgages, power of sale, family and municipal law.

Formerly Heelis, Litle, Almas and Murray LLP, the practice says it has served the region for nearly 50 years from 14 Church Street in St. Catharines. Its site names lawyers H. A. Patrick Little, Bryce W. B. Murray, Adam DiFruscia and William Heelis. The firm says its blend of legal service and client rapport has kept generations of business owners, families and residents returning, and that its broad range of practice areas lets it compete with larger firms.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('kooner-priddle-law-group-kamloops','Kooner Priddle Law Group','Kamloops','BC','bc-thompson',0,4.7,30,50.6734698,-120.3369498,'{"name":"Kooner Priddle Law Group","city":"Kamloops","featured":false,"tags":["Civil Litigation","Employment Law","Personal Injury"],"caseTypes":["litigation","employment","injury"],"region":"bc-thompson","province":"BC","lat":50.6734698,"lng":-120.3369498,"address":"172 Battle St, Kamloops, BC V2C 2L2","phone":"+12504348911","rating":4.7,"count":30,"slug":"kooner-priddle-law-group-kamloops","mapsUrl":"https://www.google.com/maps/search/Kooner+Priddle+Law+Group+Kamloops+British+Columbia","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=172+Battle+St%2C+Kamloops%2C+BC+V2C+2L2","website":"https://koonerpriddlelaw.ca","blurb":"Civil Litigation / Employment Law in Kamloops. Rated 4.7 from 30 Google reviews.","type":"logo","src":"images/logos/kooner-priddle-law-group-kamloops.png"}',NULL,'Kooner Priddle Law Group is a Kamloops litigation firm handling personal injury, malpractice, estate litigation, employment and contract disputes.

The site says its Kamloops lawyers offer a full scope of litigation services, from giving an opinion on a legal matter to designing litigation strategies, and that it acts for clients from all walks of life. Its malpractice page covers harm from misdiagnosis, surgical or prescription errors and failure to diagnose or monitor a condition, and describes its team as trial lawyers. The office is at 172 Battle Street in Kamloops, British Columbia.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('gerry-law-thunder-bay','Gerry Law','Thunder Bay','ON','northern',0,4.8,29,48.4360337,-89.218462,'{"name":"Gerry Law","city":"Thunder Bay","featured":false,"tags":["Personal Injury"],"caseTypes":["injury"],"region":"northern","province":"ON","lat":48.4360337,"lng":-89.218462,"address":"34 Cumberland St N, Thunder Bay, ON P7A 4L3","phone":"+18665322676","rating":4.8,"count":29,"slug":"gerry-law-thunder-bay","mapsUrl":"https://www.google.com/maps/search/Gerry+Law+Thunder+Bay+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=34+Cumberland+St+N%2C+Thunder+Bay%2C+ON+P7A+4L3","website":"https://gerrylaw.ca","blurb":"Personal Injury in Thunder Bay. Rated 4.8 from 29 Google reviews.","type":"logo","src":"images/logos/gerry-law-thunder-bay.webp"}',NULL,'Gerry Law is a Thunder Bay personal injury firm that also takes on sexual assault and slip and fall cases in Ontario.

The site is built around lawyer Natalie Gerry, whose profile lists a Juris Doctor from the Bora Laskin Faculty of Law and an honours B.A. from Trinity College at the University of Toronto, along with a section of selected reported decisions. The firm says it charges no legal fees until a file is resolved, and notes that initial case evaluations are limited to personal injury and sexual assault matters. The office is at 34 Cumberland Street North.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('tremblay-law-group-pc-north-bay','Tremblay Law Group PC','North Bay','ON','northern',0,4.9,28,46.304565,-79.4599735,'{"name":"Tremblay Law Group PC","city":"North Bay","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"northern","province":"ON","lat":46.304565,"lng":-79.4599735,"address":"195 Regina St, North Bay, ON P1B 2J6","phone":"+17054742920","rating":4.9,"count":28,"slug":"tremblay-law-group-pc-north-bay","mapsUrl":"https://www.google.com/maps/search/Tremblay+Law+Group+PC+North+Bay+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=195+Regina+St%2C+North+Bay%2C+ON+P1B+2J6","website":"https://tremblaylawgroup.ca","blurb":"Law firm in North Bay. Rated 4.9 from 28 Google reviews.","type":"logo","src":"images/logos/tremblay-law-group-pc-north-bay.png"}',NULL,'Tremblay Law Group PC is a North Bay firm offering real estate, corporate, litigation, family, criminal and estates law in the Nipissing area.

The firm says it offers services in English and French, with lawyers also serving Sturgeon Falls. Its history page traces the practice to 1993, when Wallace & Carr and Klein & Klein merged as Wallace Klein Partners in Law, followed by a 2024 rebrand under Managing Partner Christian Tremblay. It now lists eight legal professionals. Real estate work includes commercial and industrial transactions, conventional, high ratio and reverse mortgages, power of sale and foreclosure proceedings, and condominium registration.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('parlatore-law-niagara-niagara-falls','Parlatore Law, Niagara','Niagara Falls','ON','hamilton-niagara',0,5,27,43.1049444,-79.1020138,'{"name":"Parlatore Law, Niagara","city":"Niagara Falls","featured":false,"tags":["Personal Injury","Real Estate"],"caseTypes":["injury","realestate"],"region":"hamilton-niagara","province":"ON","lat":43.1049444,"lng":-79.1020138,"address":"6387 Morrison St Ste 200, Niagara Falls, ON L2E 7H1","phone":"+13658807777","rating":5,"count":27,"slug":"parlatore-law-niagara-niagara-falls","mapsUrl":"https://www.google.com/maps/search/Parlatore+Law%2C+Niagara+Niagara+Falls+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=6387+Morrison+St+Ste+200%2C+Niagara+Falls%2C+ON+L2E+7H1","website":"https://www.parlatorelawyers.com","blurb":"Personal Injury / Real Estate in Niagara Falls. Rated 5.0 from 27 Google reviews.","type":"logo","src":"images/logos/parlatore-law-niagara-niagara-falls.webp"}',NULL,'Parlatore Law handles personal injury cases and residential real estate transactions for clients in Niagara Falls and across the Niagara Region.

The firm''s website says its lawyers act for people in Niagara Falls and surrounding communities, and lists personal injury and real estate under its practice areas. It states that clients pay no fees if there is no recovery, and that each case is treated as unique to the individual. The office is at 6387 Morrison Street, Suite 200, in Niagara Falls, Ontario.','dynamic','live',NULL);
INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('mclaren-bryan-law-professional-corporation-peterborough','McLaren Bryan Law Professional Corporation','Peterborough','ON','simcoe-central',0,5,25,44.3094825,-78.3310917,'{"name":"McLaren Bryan Law Professional Corporation","city":"Peterborough","featured":false,"tags":["General Practice"],"caseTypes":[],"region":"simcoe-central","province":"ON","lat":44.3094825,"lng":-78.3310917,"address":"398 McDonnel St Unit# 4, Peterborough, ON K9H 2X4","phone":"+16479016815","rating":5,"count":25,"slug":"mclaren-bryan-law-professional-corporation-peterborough","mapsUrl":"https://www.google.com/maps/search/McLaren+Bryan+Law+Professional+Corporation+Peterborough+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=398+McDonnel+St+Unit%23+4%2C+Peterborough%2C+ON+K9H+2X4","website":"https://mclarenbryanlaw.com","blurb":"Law firm in Peterborough. Rated 5.0 from 25 Google reviews.","type":"logo","src":"images/logos/mclaren-bryan-law-professional-corporation-peterborough.webp"}',NULL,'McLaren Bryan Law is a Peterborough practice handling residential and commercial real estate, immigration, wills and estates, and family law.

