INSERT OR IGNORE INTO firms (slug,name,city,province,region,featured,rating,review_count,lat,lng,data,hours,about,page_mode,status,created_by) VALUES ('williams-litigation-north-north-bay','Williams Litigation North','North Bay','ON','northern',0,4.8,24,46.2886085,-79.4508933,'{"name":"Williams Litigation North","city":"North Bay","featured":false,"tags":["Civil Litigation"],"caseTypes":["litigation"],"region":"northern","province":"ON","lat":46.2886085,"lng":-79.4508933,"address":"176 Lakeshore Dr Unit 4A, North Bay, ON P1A 2A8","phone":"+17052235464","rating":4.8,"count":24,"slug":"williams-litigation-north-north-bay","mapsUrl":"https://www.google.com/maps/search/Williams+Litigation+North+North+Bay+Ontario","dirUrl":"https://www.google.com/maps/dir/?api=1&destination=176+Lakeshore+Dr+Unit+4A%2C+North+Bay%2C+ON+P1A+2A8","website":"https://www.williamslitigationnorth.ca","blurb":"Civil Litigation in North Bay. Rated 4.8 from 24 Google reviews.","type":"logo","src":"images/logos/williams-litigation-north-north-bay.png"}',NULL,'Williams Litigation North is a North Bay civil litigation firm covering insurance, personal injury, long-term disability and professional liability.

Operating as Williams Litigation Lawyers from 176 Lakeshore Drive, the firm describes its approach as modern counsel with classic care and says it does law differently. Its site includes a French-language heading for bodily injury and a team page naming Ashlee L. Barber, Kelly P. Hart, Tara Lemke, Jeremy R. Rubenstein, Eric R. Williams, David Cutler, Gabrielle Parsons and Gabriella Gader. A news item notes that two of its lawyers were included in a Canadian lawyer ranking publication.','dynamic','live',NULL);
